import { useT } from "@/lib/language-context";

import { ArcadeGameCard, GameId, GameInfo } from "@/components/arcade/ArcadeGameCard";
import { ArcadeHeader } from "@/components/arcade/ArcadeHeader";
import { ArcadeLeaderboard } from "@/components/arcade/ArcadeLeaderboard";
import { ArcadeHallOfFame, HallOfFameEntry } from "@/components/arcade/ArcadeHallOfFame";
import { GameOverModal } from "@/components/arcade/GameOverModal";

type HubTab = "games" | "leaderboard" | "hof";

function getGames(t: (key: string) => string): GameInfo[] {
  return [
    { id: "endless_biker", title: "Endless Biker", emoji: "🏍️", desc: t("arcade.corriSalta"), scoreLabel: "m" },
    { id: "traffic_racer", title: "Traffic Racer", emoji: "🚦", desc: t("arcade.sorpassaTraffico"), scoreLabel: "pt" },
    { id: "wheelie", title: "Wheelie Challenge", emoji: "🤸", desc: t("arcade.tieniImpennata"), scoreLabel: "s" },
    { id: "tetris", title: "Tetris", emoji: "🧩", desc: t("arcade.classicoSenzaTempo"), scoreLabel: "pt" },
    { id: "space_invaders", title: "Space Invaders", emoji: "👾", desc: t("arcade.eliminaGlialieni"), scoreLabel: "pt" },
  ];
}

export default function ArcadeScreen() {
  const t = useT();
  const GAMES = getGames(t);
  const insets = useSafeAreaInsets();
  const params = useLocalSearchParams<{ tab?: string; game?: string }>();
  const { suppressWidget } = useFloatingWidget();
  const [hubTab, setHubTab] = useState<HubTab>(
    params.tab === "leaderboard" ? "leaderboard" : params.tab === "hof" ? "hof" : "games"
  );
  const [activeGame, setActiveGame] = useState<GameId | null>(null);
  const [leaderboardGame, setLeaderboardGame] = useState<GameId>(
    (params.game as GameId | undefined) && GAMES.some((g) => g.id === params.game)
      ? (params.game as GameId)
      : "endless_biker"
  );
  const [gameKey, setGameKey] = useState(0);
  const [gameOver, setGameOver] = useState<{ score: number; prevBest: number } | null>(null);

  useEffect(() => {
    suppressWidget(!!activeGame);
    return () => { suppressWidget(false); };
  }, [activeGame, suppressWidget]);

  useEffect(() => {
    if (params.tab === "leaderboard") {
      setHubTab("leaderboard");
      if (params.game && GAMES.some((g) => g.id === params.game)) {
        setLeaderboardGame(params.game as GameId);
      }
    } else if (params.tab === "hof") {
      setHubTab("hof");
    }
  }, [params.tab, params.game, GAMES]);

  const { data: myScores } = useQuery<Record<string, number>>({
    queryKey: ["/api/arcade/my-scores"],
    refetchInterval: 120_000,
  });

  const { data: hofData } = useQuery<Record<GameId, HallOfFameEntry>>({
    queryKey: ["/api/arcade/hall-of-fame"],
    refetchInterval: 120_000,
  });

  const scoreMutation = useMutation({
    mutationFn: async ({ game, score }: { game: GameId; score: number }) => {
      await apiRequest("POST", "/api/arcade/score", { game, score });
    },
    onSuccess: (_, vars) => {
      queryClient.invalidateQueries({ queryKey: ["/api/arcade/my-scores"] });
      queryClient.invalidateQueries({ queryKey: [`/api/arcade/leaderboard/${vars.game}`] });
      queryClient.invalidateQueries({ queryKey: ["/api/arcade/hall-of-fame"] });
    },
  });

  const handleGameOver = useCallback((score: number) => {
    if (!activeGame) return;
    const personal = myScores?.[activeGame] ?? 0;
    setGameOver({ score, prevBest: personal });
    if (score > personal) {
      scoreMutation.mutate({ game: activeGame, score });
    }
  }, [activeGame, myScores, scoreMutation]);

  const handleReplay = useCallback(() => {
    setGameOver(null);
    scoreMutation.reset();
    setGameKey((k) => k + 1);
  }, [scoreMutation]);

  const handleExitGame = useCallback(() => {
    setGameOver(null);
    scoreMutation.reset();
    setActiveGame(null);
  }, [scoreMutation]);

  const renderGame = () => {
    if (!activeGame) return null;
    const props = { onGameOver: handleGameOver };
    switch (activeGame) {
      case "endless_biker": return <EndlessBiker key={gameKey} {...props} />;
      case "traffic_racer": return <TrafficRacer key={gameKey} {...props} />;
      case "wheelie": return <WheelieChallenge key={gameKey} {...props} />;
      case "tetris": return <Tetris key={gameKey} {...props} />;
      case "space_invaders": return <SpaceInvaders key={gameKey} {...props} />;
    }
  };

  const activeGameInfo = activeGame ? GAMES.find((g) => g.id === activeGame) ?? null : null;
  const activePersonal = activeGame ? (myScores?.[activeGame] ?? 0) : 0;
  const activeHofEntry = activeGame ? hofData?.[activeGame] : undefined;
  const activeCommunityRecord = activeHofEntry?.score ?? 0;

  return (
    <>
      <Modal
        visible={!!activeGame}
        animationType="none"
        statusBarTranslucent
        onRequestClose={handleExitGame}
      >
        <View style={{ flex: 1, backgroundColor: Colors.background }}>
          {activeGameInfo && (
            <ArcadeHeader
              activeGameInfo={activeGameInfo}
              activePersonal={activePersonal}
              activeCommunityRecord={activeCommunityRecord}
              onExit={handleExitGame}
              topInset={insets.top}
            />
          )}
          <View style={{ flex: 1 }}>
            {renderGame()}
          </View>
          {gameOver && activeGameInfo && (
            <GameOverModal
              score={gameOver.score}
              personalBest={gameOver.prevBest}
              isNewRecord={gameOver.score > gameOver.prevBest}
              onReplay={handleReplay}
              onClose={handleExitGame}
              scoreLabel={activeGameInfo.scoreLabel}
              isSaving={scoreMutation.isPending}
              isSaveError={scoreMutation.isError}
              onRetrySave={
                scoreMutation.isError && activeGame
                  ? () => scoreMutation.mutate({ game: activeGame, score: gameOver.score })
                  : undefined
              }
            />
          )}
        </View>
      </Modal>

      <View style={[styles.container, { paddingBottom: insets.bottom }]}>
        <View style={styles.tabSwitcher}>
          {([["games", "🕹️ Giochi"], ["leaderboard", "🏅 Classifiche"], ["hof", "🏆 Hall of Fame"]] as const).map(([key, label]) => (
            <Pressable
              key={key}
              style={[styles.tabBtn, hubTab === key && styles.tabBtnActive]}
              onPress={() => setHubTab(key)}
            >
              <Text style={[styles.tabBtnText, hubTab === key && styles.tabBtnTextActive]}>{label}</Text>
            </Pressable>
          ))}
        </View>

        {hubTab === "games" && (
          <ScrollView contentContainerStyle={styles.gameGrid} showsVerticalScrollIndicator={false}>
            {GAMES.map((g) => (
              <ArcadeGameCard
                key={g.id}
                game={g}
                personal={myScores?.[g.id] ?? 0}
                hofEntry={hofData?.[g.id]}
                onPress={setActiveGame}
              />
            ))}
          </ScrollView>
        )}

        {hubTab === "leaderboard" && (
          <View style={{ flex: 1 }}>
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.gameSelector}
            >
              {GAMES.map((g) => (
                <Pressable
                  key={g.id}
                  style={[styles.gameSelectorBtn, leaderboardGame === g.id && styles.gameSelectorBtnActive]}
                  onPress={() => setLeaderboardGame(g.id)}
                >
                  <Text style={styles.gameSelectorEmoji}>{g.emoji}</Text>
                  <Text style={[styles.gameSelectorText, leaderboardGame === g.id && styles.gameSelectorTextActive]}>
                    {g.title}
                  </Text>
                </Pressable>
              ))}
            </ScrollView>
            <ArcadeLeaderboard gameId={leaderboardGame} />
          </View>
        )}

        {hubTab === "hof" && <ArcadeHallOfFame games={GAMES} />}
      </View>
    </>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: Colors.background },
  tabSwitcher: {
    flexDirection: "row",
    borderBottomWidth: 1,
    borderBottomColor: Colors.border,
    backgroundColor: Colors.surface,
  },
  tabBtn: {
    flex: 1,
    paddingVertical: 12,
    alignItems: "center",
  },
  tabBtnActive: {
    borderBottomWidth: 2,
    borderBottomColor: Colors.accent,
  },
  tabBtnText: {
    fontSize: 11,
    fontFamily: "Inter_500Medium",
    color: Colors.textSecondary,
  },
  tabBtnTextActive: {
    color: Colors.accent,
  },
  gameGrid: {
    padding: 12,
    gap: 10,
  },
  gameSelector: {
    paddingHorizontal: 12,
    paddingVertical: 10,
    gap: 8,
  },
  gameSelectorBtn: {
    flexDirection: "row",
    alignItems: "center",
    gap: 6,
    paddingHorizontal: 12,
    paddingVertical: 8,
    borderRadius: 20,
    backgroundColor: Colors.surface,
    borderWidth: 1,
    borderColor: Colors.border,
  },
  gameSelectorBtnActive: {
    borderColor: Colors.accent,
    backgroundColor: Colors.accent + "20",
  },
  gameSelectorEmoji: { fontSize: 16 },
  gameSelectorText: { fontSize: 12, fontFamily: "Inter_500Medium", color: Colors.textSecondary },
  gameSelectorTextActive: { color: Colors.accent },
});

import React, { useState, useCallback } from "react";
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  Pressable,
  ActivityIndicator,
  Alert,
  RefreshControl,
} from "react-native";
import { KeyboardAvoidingView } from "react-native";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Ionicons } from "@expo/vector-icons";
import { InlineMiniPlayer } from "@/components/MiniPlayer";
import { useRouter } from "expo-router";
import { showImagePickerMenu } from "@/lib/image-picker-utils";

import Colors from "@/constants/colors";
import { useT } from "@/lib/language-context";
import { apiRequest, queryClient, getApiUrl } from "@/lib/query-client";

import { ContestEntryCard, ContestEntry } from "@/components/contest/ContestCard";
import { ContestLeaderboard } from "@/components/contest/ContestLeaderboard";
import { ContestRules } from "@/components/contest/ContestRules";
import { ContestHeader } from "@/components/contest/ContestHeader";
import { ContestUpload } from "@/components/contest/ContestUpload";

const GAP = 8;
const COLUMN_COUNT = 2;

interface ContestResponse {
  entries: ContestEntry[];
  weekNumber: number;
  year: number;
  votesUsed: number;
  maxVotesPerDay: number;
}

export default function ContestScreen() {
  const router = useRouter();
  const t = useT();
  const [showUpload, setShowUpload] = useState(false);
  const [caption, setCaption] = useState("");
  const [selectedImage, setSelectedImage] = useState<string | null>(null);

  const { data, isLoading, refetch } = useQuery<ContestResponse>({
    queryKey: ["/api/contest/entries"],
  });

  const deleteMutation = useMutation({
    mutationFn: async (entryId: string) => {
      await apiRequest("DELETE", `/api/contest/entries/${entryId}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/contest/entries"] });
    },
    onError: () => {
      Alert.alert("Errore", "Impossibile eliminare la foto");
    },
  });

  const voteMutation = useMutation({
    mutationFn: async (entryId: string) => {
      await apiRequest("POST", `/api/contest/entries/${entryId}/vote`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/contest/entries"] });
    },
    onError: (error: Error) => {
      const msg = error.message.includes(":")
        ? error.message.split(":").slice(1).join(":").trim()
        : error.message;
      try {
        const parsed = JSON.parse(msg);
        Alert.alert(t("common.error"), parsed.message || t("contest.cannotVote"));
      } catch {
        Alert.alert(t("common.error"), msg || t("contest.cannotVote"));
      }
    },
  });

  const uploadMutation = useMutation({
    mutationFn: async (data: { imageUri: string; caption: string }) => {
      const formData = new FormData();
      const filename = data.imageUri.split("/").pop() || "photo.jpg";
      const ext = /\.(\w+)$/.exec(filename);
      const mimeType = ext ? `image/${ext[1].toLowerCase()}` : "image/jpeg";

      formData.append("photo", { uri: data.imageUri, name: filename, type: mimeType } as any);

      if (data.caption) {
        formData.append("caption", data.caption);
      }

      const url = new URL("/api/contest/entries", getApiUrl());
      const res = await globalThis.fetch(url.toString(), {
        method: "POST",
        body: formData,
        credentials: "include",
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(text);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/contest/entries"] });
      setShowUpload(false);
      setCaption("");
      setSelectedImage(null);
    },
    onError: (error: Error) => {
      Alert.alert("Errore", "Impossibile caricare la foto");
    },
  });

  const handleDelete = useCallback(
    (entryId: string) => {
      Alert.alert(
        t("contest.deletePhoto"),
        t("contest.deletePhotoConfirm"),
        [
          { text: t("common.cancel"), style: "cancel" },
          {
            text: t("common.delete"),
            style: "destructive",
            onPress: () => deleteMutation.mutate(entryId),
          },
        ]
      );
    },
    [deleteMutation, t]
  );

  const handleVote = useCallback(
    (entryId: string) => {
      voteMutation.mutate(entryId);
    },
    [voteMutation]
  );

  const handlePickImage = useCallback(() => {
    showImagePickerMenu(
      (uri) => {
        setSelectedImage(uri);
        setShowUpload(true);
      },
      { aspect: [4, 3], quality: 0.8 }
    );
  }, []);

  const handleUpload = useCallback(() => {
    if (!selectedImage) return;
    uploadMutation.mutate({ imageUri: selectedImage, caption });
  }, [selectedImage, caption, uploadMutation]);

  const votesUsed = data?.votesUsed ?? 0;
  const votesRemaining = 10 - votesUsed;
  const votingDisabled = votesRemaining <= 0;

  const renderEntry = useCallback(
    ({ item }: { item: ContestEntry }) => (
      <ContestEntryCard
        entry={item}
        onVote={handleVote}
        onDelete={handleDelete}
        votingDisabled={votingDisabled}
      />
    ),
    [handleVote, handleDelete, votingDisabled]
  );

  if (isLoading) {
    return (
      <View style={[styles.container, styles.loading]}>
        <ActivityIndicator size="large" color={Colors.accent} />
      </View>
    );
  }

  return (
    <KeyboardAvoidingView behavior="padding" style={{ flex: 1 }}>
      <View style={styles.container}>
        <InlineMiniPlayer />
        <ContestRules />
        <ContestHeader votesRemaining={votesRemaining} />

        <ContestUpload
          selectedImage={selectedImage}
          caption={caption}
          setCaption={setCaption}
          onCancel={() => {
            setShowUpload(false);
            setSelectedImage(null);
            setCaption("");
          }}
          onUpload={handleUpload}
          isUploading={uploadMutation.isPending}
        />

        <FlatList
          data={data?.entries ?? []}
          renderItem={renderEntry}
          keyExtractor={(item) => item.id}
          numColumns={COLUMN_COUNT}
          contentContainerStyle={styles.list}
          columnWrapperStyle={styles.columnWrapper}
          showsVerticalScrollIndicator={false}
          scrollEnabled={true}
          refreshControl={
            <RefreshControl refreshing={false} onRefresh={refetch} tintColor={Colors.accent} />
          }
          ListEmptyComponent={
            <View style={styles.empty}>
              <Ionicons name="camera-outline" size={48} color={Colors.textSecondary} />
              <Text style={styles.emptyText}>{t("common.noResults")}</Text>
              <Text style={styles.emptySubtext}>
                Carica la prima foto della settimana!
              </Text>
            </View>
          }
          ListFooterComponent={<ContestLeaderboard />}
        />

        <Pressable
          style={[styles.fab, { bottom: 16 }]}
          onPress={handlePickImage}
        >
          <Ionicons name="camera" size={28} color={Colors.background} />
        </Pressable>
      </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.background,
  },
  loading: {
    justifyContent: "center",
    alignItems: "center",
  },
  list: {
    padding: 8,
    paddingBottom: 80,
  },
  columnWrapper: {
    gap: GAP,
  },
  empty: {
    alignItems: "center",
    paddingTop: 60,
    gap: 8,
  },
  emptyText: {
    fontSize: 16,
    fontFamily: "Inter_500Medium",
    color: Colors.textSecondary,
  },
  emptySubtext: {
    fontSize: 14,
    fontFamily: "Inter_400Regular",
    color: Colors.textSecondary,
  },
  fab: {
    position: "absolute",
    right: 20,
    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: Colors.accent,
    alignItems: "center",
    justifyContent: "center",
    elevation: 4,
  },
});

import React, { useState } from "react";
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  Pressable,
  ActivityIndicator,
  RefreshControl,
  Alert,
} from "react-native";
import { useQuery, useMutation } from "@tanstack/react-query";
import { MaterialCommunityIcons, Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useRouter } from "expo-router";

import Colors from "@/constants/colors";
import { useAuth } from "@/lib/auth-context";
import { apiRequest, queryClient } from "@/lib/query-client";
import { useT } from "@/lib/language-context";
import { motorcycleSchema } from "@shared/validators";

import { GarageHeader } from "@/components/garage/GarageHeader";
import { MotoCard } from "@/components/garage/MotoCard";
import { AddMotoForm } from "@/components/garage/AddMotoForm";
import { WishlistSection } from "@/components/garage/WishlistSection";

const MOTO_TYPES = [
  { value: "sportiva" },
  { value: "supersportiva" },
  { value: "custom" },
  { value: "harley" },
  { value: "touring" },
  { value: "naked" },
  { value: "enduro" },
  { value: "cafe_racer" },
  { value: "altro" },
] as const;

const RIDING_STYLES = [
  { value: "passeggio" },
  { value: "tranquilla" },
  { value: "allegra" },
  { value: "mozzafiato" },
] as const;

export default function GarageScreen() {
  const { user } = useAuth();
  const insets = useSafeAreaInsets();

  if (user?.userType === "zavorrina") {
    return <WishlistSection insets={insets} MOTO_TYPES={MOTO_TYPES} RIDING_STYLES={RIDING_STYLES} />;
  }

  return <GarageContent />;
}

function GarageContent() {
  const { user, isLoading: authIsLoading } = useAuth();
  const router = useRouter();
  const t = useT();
  const insets = useSafeAreaInsets();
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState({
    brand: "",
    model: "",
    displacement: "",
    motorcycleType: "",
    ridingStyle: "",
    isDefault: false,
    isForSale: false,
    saleDescription: "",
    motoDescription: "",
  });

  const { data: marketplaceData } = useQuery<{ enabled: boolean }>({
    queryKey: ["/api/settings/marketplace-enabled"],
  });
  const marketplaceEnabled = marketplaceData?.enabled !== false;

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["/api/motorcycles"],
    enabled: !!user,
    refetchOnMount: true,
  });

  const motorcycles = Array.isArray(data) ? data : [];

  const saveMutation = useMutation({
    mutationFn: async (motoData: any) => {
      const payload = {
        ...motoData,
        displacement: motoData.displacement ? parseInt(motoData.displacement, 10) : null,
      };
      let res: Response;
      if (editingId) {
        res = await apiRequest("PUT", `/api/motorcycles/${editingId}`, payload);
      } else {
        res = await apiRequest("POST", "/api/motorcycles", payload);
      }
      return res.json();
    },
    onSuccess: async (responseData: any) => {
      await queryClient.refetchQueries({ queryKey: ["/api/motorcycles"] });
      setShowForm(false);
      resetForm();

      if (responseData?.matches && responseData.matches.length > 0) {
        const matchInfo = responseData.matches
          .map((m: any) => `${m.zavarrinaNickname || "Zavorrina"} ${t("garage.lookingFor")} ${m.brand} ${m.model}`)
          .join("\n");
        Alert.alert("Here Comes Your Chance!!", matchInfo);
      }
    },
    onError: (err: any) => {
      Alert.alert(t("common.error"), err.message || t("garage.saveError"));
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      await apiRequest("DELETE", `/api/motorcycles/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/motorcycles"] });
    },
  });

  const resetForm = () => {
    setForm({ brand: "", model: "", displacement: "", motorcycleType: "", ridingStyle: "", isDefault: false, isForSale: false, saleDescription: "", motoDescription: "" });
    setEditingId(null);
  };

  const openAdd = () => {
    resetForm();
    setShowForm(true);
  };

  const openEdit = (moto: any) => {
    setEditingId(moto.id);
    setForm({
      brand: moto.brand || "",
      model: moto.model || "",
      displacement: moto.displacement ? String(moto.displacement) : "",
      motorcycleType: moto.motorcycleType || "",
      ridingStyle: moto.ridingStyle || "",
      isDefault: moto.isDefault || false,
      isForSale: moto.isForSale || false,
      saleDescription: moto.saleDescription || "",
      motoDescription: moto.motoDescription || "",
    });
    setShowForm(true);
  };

  const handleSave = () => {
    const parsed = motorcycleSchema.safeParse({
      ...form,
      displacement: form.displacement ? parseInt(form.displacement, 10) : undefined,
    });
    if (!parsed.success) {
      Alert.alert(t("common.error"), parsed.error.issues[0]?.message ?? t("garage.fillRequired"));
      return;
    }
    saveMutation.mutate(form);
  };

  const handleDelete = (id: string, displayName: string) => {
    Alert.alert(t("garage.deleteMoto"), `${t("garage.deleteMoto")} "${displayName}"?`, [
      { text: t("common.cancel"), style: "cancel" },
      { text: t("common.delete"), style: "destructive", onPress: () => deleteMutation.mutate(id) },
    ]);
  };

  const getMotoTypeLabel = (v: string) => t(`garage.motoType.${v}`) || v;
  const getStyleLabel = (v: string) => t(`garage.style.${v}`) || v;

  const getMotoDisplayName = (item: any) => {
    const parts = [item.brand, item.model].filter(Boolean);
    const name = parts.join(" ");
    if (item.displacement) {
      return `${name} (${item.displacement} cc)`;
    }
    return name;
  };

  if (!authIsLoading && user === null) {
    return (
      <View style={[styles.empty, { flex: 1, justifyContent: "center" }]}>
        <Ionicons name="lock-closed-outline" size={64} color={Colors.textSecondary} />
        <Text style={styles.emptyText}>{t("auth.sessionExpired")}</Text>
        <Pressable
          style={sessionExpiredBtn}
          onPress={() => router.replace("/(auth)/login")}
        >
          <Text style={sessionExpiredBtnText}>{t("auth.loginToContinue")}</Text>
        </Pressable>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      {(isLoading || authIsLoading) ? (
        <View style={styles.loading}>
          <ActivityIndicator size="large" color={Colors.accent} />
        </View>
      ) : (
        <>
          <GarageHeader 
            motorcyclesCount={motorcycles.length} 
            onAddPress={openAdd}
          />
          <FlatList
            data={motorcycles}
            renderItem={({ item }) => (
