    useCallback(() => {
      AsyncStorage.multiGet(["match_distance_mode", "match_distance_km"]).then(pairs => {
        const mode = pairs[0][1];
        const km = pairs[1][1];
        if (mode === "all" || mode === "km") setDistanceMode(mode as any);
        if (km) { setDistanceKm(km); setPendingKm(km); }
      }).catch(() => {});
    }, [])
  );

  useFocusEffect(
    useCallback(() => {
      if (activeTab !== "music") return;
      AsyncStorage.multiGet(["music_match_criteria", "music_match_logic", "music_match_min_songs"])
        .then(pairs => {
          const criteria = pairs[0][1] ?? "songs,genre";
          const minS = pairs[2][1] ?? "5";
          setMusicCriteria(criteria);
          setMusicMinSongs(parseInt(minS, 10) || 5);
        })
        .catch(() => {});
    }, [activeTab])
  );

  const { data: proposalMatches, isLoading: proposalLoading, refetch: proposalRefetch, isRefetching: proposalRefetching } = useQuery<any[]>({
    queryKey: ["/api/proposals/matches"],
    enabled: !!user,
    refetchInterval: 30000,
    refetchOnMount: true,
  });

  const { data: garageMatches, isLoading: garageLoading, refetch: garageRefetch, isRefetching: garageRefetching, isFetching: garageIsFetching } = useQuery<any[]>({
    queryKey: ["/api/proposals/garage-matches"],
    enabled: !!user,
    refetchInterval: 30000,
    refetchOnMount: true,
  });

  const { data: bikerMatches, isLoading: bikerLoading, refetch: bikerRefetch, isRefetching: bikerRefetching, isFetching: bikerIsFetching } = useQuery<any[]>({
    queryKey: ["/api/proposals/biker-matches"],
    enabled: !!user,
    refetchInterval: 30000,
    refetchOnMount: true,
  });

  const { data: blockedUsers, isLoading: blockedLoading, refetch: blockedRefetch, isRefetching: blockedRefetching } = useQuery<any[]>({
    queryKey: ["/api/users/blocked"],
    enabled: !!user,
    refetchInterval: 30000,
    refetchOnMount: true,
  });

  const { data: acceptedMatches, isLoading: acceptedLoading, refetch: acceptedRefetch, isRefetching: acceptedRefetching } = useQuery<any[]>({
    queryKey: ["/api/proposals/matches/accepted"],
    enabled: !!user,
    refetchInterval: 30000,
    refetchOnMount: true,
  });

  const { data: propProfileMatches, isLoading: propProfileLoading, refetch: propProfileRefetch, isRefetching: propProfileRefetching } = useQuery<any[]>({
    queryKey: ["/api/proposals/proposal-profile-matches"],
    enabled: !!user,
    refetchInterval: 30000,
    refetchOnMount: true,
  });

  const { data: lastfmStatus } = useQuery<{ connected: boolean; username?: string }>({
    queryKey: ["/api/music/lastfm/status"],
    enabled: !!user,
  });

  const { data: musicMatches, isLoading: musicLoading, refetch: musicRefetch, isRefetching: musicRefetching, error: musicError } = useQuery<any[]>({
    queryKey: ["/api/music/matches"],
    enabled: !!user && activeTab === "music" && lastfmStatus?.connected === true,
    refetchInterval: 60000,
  });

  const isServerBusy = musicError instanceof ServerBusyError;

  const acceptMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/matches/${matchId}/accept`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches"] });
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches/accepted"] });
      setPendingMatchId(null);
    },
    onError: () => setPendingMatchId(null),
  });

  const rejectMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/matches/${matchId}/reject`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches"] });
    },
  });

  const acceptGarageMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/garage-matches/${matchId}/accept`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/garage-matches"] });
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches/accepted"] });
      setPendingMatchId(null);
    },
    onError: () => setPendingMatchId(null),
  });

  const rejectGarageMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/garage-matches/${matchId}/reject`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/garage-matches"] });
    },
  });

  const acceptBikerMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/biker-matches/${matchId}/accept`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/biker-matches"] });
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches/accepted"] });
      setPendingMatchId(null);
    },
    onError: () => setPendingMatchId(null),
  });

  const rejectBikerMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/biker-matches/${matchId}/reject`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/biker-matches"] });
    },
  });

  const acceptPropProfileMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/proposal-profile-matches/${matchId}/accept`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/proposal-profile-matches"] });
      setPropProfilePendingId(null);
    },
    onError: () => setPropProfilePendingId(null),
  });

  const rejectPropProfileMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("POST", `/api/proposals/proposal-profile-matches/${matchId}/reject`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/proposal-profile-matches"] });
    },
  });

  const unblockMutation = useMutation({
    mutationFn: (blockedUserId: string) => apiRequest("DELETE", `/api/users/blocked/${blockedUserId}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/users/blocked"] });
      Alert.alert(t("common.success"), t("match.userUnblocked"));
    },
  });

  const startChatMutation = useMutation({
    mutationFn: (targetUserId: string) => apiRequest("POST", "/api/chat/conversations", { targetUserId }),
    onSuccess: (data) => {
      if ((data as any).id) {
        router.push(`/chat/${(data as any).id}` as any);
      }
    },
  });

  const blockFromMatchMutation = useMutation({
    mutationFn: (targetUserId: string) => apiRequest("POST", "/api/users/block", { targetUserId }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/biker-matches"] });
      queryClient.invalidateQueries({ queryKey: ["/api/users/blocked"] });
      Alert.alert(t("common.success"), t("match.userBlocked"));
    },
  });

  const removeGarageMatchMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("DELETE", `/api/proposals/garage-matches/${matchId}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches/accepted"] });
    },
  });

  const removeBikerMatchMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("DELETE", `/api/proposals/biker-matches/${matchId}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches/accepted"] });
    },
  });

  const removeProposalMatchMutation = useMutation({
    mutationFn: (matchId: string) => apiRequest("DELETE", `/api/proposals/matches/${matchId}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches/accepted"] });
    },
  });

  const resetAndRematchMutation = useMutation({
    mutationFn: () => apiRequest("POST", "/api/proposals/rematch", {
      distanceMode,
      distanceKm: parseInt(distanceKm, 10) || 50,
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/matches"] });
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/garage-matches"] });
      queryClient.invalidateQueries({ queryKey: ["/api/proposals/biker-matches"] });
    },
  });

  const handleResetAndRematch = useCallback(() => {
    const kmVal = parseInt(pendingKm, 10);
    if (distanceMode === "km" && (isNaN(kmVal) || kmVal <= 0)) {
      Alert.alert(t("common.error"), t("match.invalidKm"));
      return;
    }
    setDistanceKm(pendingKm);
    AsyncStorage.setItem("match_distance_km", pendingKm).catch(() => {});
    resetAndRematchMutation.mutate();
  }, [distanceMode, pendingKm, resetAndRematchMutation, t]);

  const confirmRemoveGarageMatch = useCallback((id: string) => {
    Alert.alert(t("common.confirm"), t("match.confirmRemoveMatch"), [
      { text: t("common.cancel"), style: "cancel" },
      { text: t("common.remove"), style: "destructive", onPress: () => removeGarageMatchMutation.mutate(id) },
    ]);
  }, [removeGarageMatchMutation, t]);

  const confirmRemoveBikerMatch = useCallback((id: string) => {
    Alert.alert(t("common.confirm"), t("match.confirmRemoveMatch"), [
      { text: t("common.cancel"), style: "cancel" },
      { text: t("common.remove"), style: "destructive", onPress: () => removeBikerMatchMutation.mutate(id) },
    ]);
  }, [removeBikerMatchMutation, t]);

  const confirmRemoveProposalMatch = useCallback((id: string) => {
    Alert.alert(t("common.confirm"), t("match.confirmRemoveMatch"), [
      { text: t("common.cancel"), style: "cancel" },
      { text: t("common.remove"), style: "destructive", onPress: () => removeProposalMatchMutation.mutate(id) },
    ]);
  }, [removeProposalMatchMutation, t]);

  const onRefresh = useCallback(() => {
    if (activeTab === "proposals") proposalRefetch();
    else if (activeTab === "zavorrine") garageRefetch();
    else if (activeTab === "biker") bikerRefetch();
    else if (activeTab === "blacklist") blockedRefetch();
    else if (activeTab === "music") musicRefetch();
    else if (activeTab === "accepted") acceptedRefetch();
    else if (activeTab === "propProfile") propProfileRefetch();
  }, [activeTab, proposalRefetch, garageRefetch, bikerRefetch, blockedRefetch, musicRefetch, acceptedRefetch, propProfileRefetch]);

  const handleUnblock = useCallback((blockedUserId: string) => {
    Alert.alert(t("common.confirm"), t("match.confirmUnblock"), [
      { text: t("common.cancel"), style: "cancel" },
      { text: t("match.unblock"), onPress: () => unblockMutation.mutate(blockedUserId) },
    ]);
  }, [unblockMutation, t]);

  const currentList = useMemo(() => {
    if (activeTab === "proposals") return proposalMatches?.filter(m => m.status === "pending") || [];
    if (activeTab === "zavorrine") return garageMatches?.filter(m => m.status === "new") || [];
    if (activeTab === "biker") return bikerMatches?.filter(m => m.status === "new") || [];
    if (activeTab === "blacklist") return blockedUsers || [];
    if (activeTab === "music") return musicMatches || [];
    if (activeTab === "propProfile") return propProfileMatches?.filter(m => m.status === "new") || [];
    if (activeTab === "accepted") {
      const g = (garageMatches?.filter(m => m.status === "accepted") || []).map(m => ({ ...m, _matchType: "garage" }));
      const b = (bikerMatches?.filter(m => m.status === "accepted") || []).map(m => ({ ...m, _matchType: "biker" }));
      const p = (proposalMatches?.filter(m => m.status === "accepted") || []).map(m => ({ ...m, _matchType: "proposal" }));
      const pp = (propProfileMatches?.filter(m => m.status === "accepted") || []).map(m => ({ ...m, _matchType: "propProfile" }));
      const acc = (acceptedMatches || []).map(m => ({ ...m, _matchType: "generic" }));
      return [...g, ...b, ...p, ...pp, ...acc].sort((a, b) => new Date(b.updatedAt || b.createdAt || 0).getTime() - new Date(a.updatedAt || a.createdAt || 0).getTime());
    }
    return [];
  }, [activeTab, proposalMatches, garageMatches, bikerMatches, blockedUsers, musicMatches, acceptedMatches, propProfileMatches]);

  const isLoading = proposalLoading || garageLoading || bikerLoading || blockedLoading || musicLoading || acceptedLoading || propProfileLoading;
  const isRefetching = proposalRefetching || garageRefetching || bikerRefetching || blockedRefetching || musicRefetching || acceptedRefetching || propProfileRefetching;

  const renderItem = useCallback(({ item }: { item: any }) => {
    if (activeTab === "blacklist") {
      return (
        <BlacklistCard item={item} onUnblock={handleUnblock} />
      );
    }

    if (activeTab === "music") {
      return (
        <MusicMatchCard item={item} onSendMessage={(userId) => startChatMutation.mutate(userId)} />
      );
    }

    if (activeTab === "propProfile") {
      const isBiker = item.bikerId === user?.id;
      const otherUserId = isBiker ? item.zavarrinaId : item.bikerId;
      return (
        <ProposalProfileMatchCard
          match={item}
          currentUserId={user?.id || ""}
          onAccept={() => {
            setPropProfilePendingId(item.id);
            acceptPropProfileMutation.mutate(item.id);
          }}
          onReject={() => rejectPropProfileMutation.mutate(item.id)}
          onChatPress={item.status === "accepted" ? () => startChatMutation.mutate(otherUserId) : undefined}
          isPending={propProfilePendingId === item.id}
          t={t}
          locale={locale}
        />
      );
    }

    if (activeTab === "accepted") {
      if (item._matchType === "biker") {
        const isBiker1 = item.biker1Id === user?.id;
        const otherUserId = isBiker1 ? item.biker2Id : item.biker1Id;
        return (
          <BikerBikerMatchCard
            match={item}
            currentUserId={user?.id || ""}
            onAccept={() => {}}
            onReject={() => {}}
            onBlock={() => {}}
            onChatPress={() => startChatMutation.mutate(otherUserId)}
            onRemove={() => confirmRemoveBikerMatch(item.id)}
            isPending={false}
            t={t}
            locale={locale}
          />
        );
      }
      if (item._matchType === "garage") {
        const isBiker = item.bikerId === user?.id;
        const otherUserId = isBiker ? item.zavarrinaId : item.bikerId;
        return (
          <GarageMatchCard
            match={item}
            currentUserId={user?.id || ""}
            onAccept={() => {}}
            onReject={() => {}}
            onChatPress={() => startChatMutation.mutate(otherUserId)}
            onRemove={() => confirmRemoveGarageMatch(item.id)}
            isPending={false}
            t={t}
            locale={locale}
          />
        );
      }
      if (item._matchType === "propProfile") {
        const otherUserId = item.bikerId === user?.id ? item.zavarrinaId : item.bikerId;
        return (
          <ProposalProfileMatchCard
            match={item}
            currentUserId={user?.id || ""}
            onAccept={() => {}}
            onReject={() => {}}
            onChatPress={() => startChatMutation.mutate(otherUserId)}
            isPending={false}
            t={t}
            locale={locale}
          />
        );
      }
      return (
        <MatchCardFull
          match={item}
          currentUserId={user?.id || ""}
          onAccept={() => {}}
          onReject={() => {}}
          onChatPress={item.conversationId ? () => router.push(`/chat/${item.conversationId}` as any) : undefined}
          onRemove={() => confirmRemoveProposalMatch(item.id)}
          isPending={false}
          t={t}
          locale={locale}
        />
      );
    }

    if (activeTab === "biker") {
      const isBiker1 = item.biker1Id === user?.id;
      const otherUserId = isBiker1 ? item.biker2Id : item.biker1Id;
      return (
        <BikerBikerMatchCard
          match={item}
          currentUserId={user?.id || ""}
          onAccept={() => {
            setPendingMatchId(item.id);
            acceptBikerMutation.mutate(item.id);
          }}
          onReject={() => rejectBikerMutation.mutate(item.id)}
          onBlock={() => {
            const nickname = (item.biker1Id === user?.id ? item.biker2Nickname : item.biker1Nickname) || t("match.thisUser");
            const msg = t("match.blockUserConfirmMsg").replace("{nickname}", nickname);
            Alert.alert(t("match.blockUserConfirmTitle"), msg, [
              { text: t("common.cancel"), style: "cancel" },
              { text: t("match.blockUser"), style: "destructive", onPress: () => blockFromMatchMutation.mutate(otherUserId) },
            ]);
          }}
          onChatPress={item.status === "accepted" ? () => startChatMutation.mutate(otherUserId) : undefined}
          onRemove={item.status === "accepted" ? () => confirmRemoveBikerMatch(item.id) : undefined}
          isPending={pendingMatchId === item.id}
          t={t}
          locale={locale}
        />
      );
    }
    if (activeTab === "zavorrine") {
      const isBiker = item.bikerId === user?.id;
      const otherUserId = isBiker ? item.zavarrinaId : item.bikerId;
      return (
        <GarageMatchCard
          match={item}
          currentUserId={user?.id || ""}
          onAccept={() => {
            setPendingMatchId(item.id);
            acceptGarageMutation.mutate(item.id);
          }}
          onReject={() => rejectGarageMutation.mutate(item.id)}
          onChatPress={item.status === "accepted" ? () => startChatMutation.mutate(otherUserId) : undefined}
          onRemove={item.status === "accepted" ? () => confirmRemoveGarageMatch(item.id) : undefined}
          isPending={pendingMatchId === item.id}
          t={t}
          locale={locale}
        />
      );
    }
    return (
      <MatchCardFull
        match={item}
        currentUserId={user?.id || ""}
        onAccept={() => {
          setPendingMatchId(item.id);
          acceptMutation.mutate(item.id);
        }}
        onReject={() => rejectMutation.mutate(item.id)}
        onChatPress={item.conversationId ? () => router.push(`/chat/${item.conversationId}` as any) : undefined}
        onRemove={item.status === "accepted" ? () => confirmRemoveProposalMatch(item.id) : undefined}
        isPending={pendingMatchId === item.id}
        t={t}
        locale={locale}
      />
    );
  }, [activeTab, user?.id, pendingMatchId, propProfilePendingId, acceptGarageMutation, rejectGarageMutation, acceptBikerMutation, rejectBikerMutation, blockFromMatchMutation, acceptMutation, rejectMutation, acceptPropProfileMutation, rejectPropProfileMutation, startChatMutation, confirmRemoveGarageMatch, confirmRemoveBikerMatch, confirmRemoveProposalMatch, handleUnblock, router, t, locale]);

  const newGarageMatches = useMemo(() => garageMatches?.filter(m => m.status === "new") || [], [garageMatches]);
  const newBikerMatches = useMemo(() => bikerMatches?.filter(m => m.status === "new") || [], [bikerMatches]);
  const newProposalMatches = useMemo(() => proposalMatches?.filter(m => m.status === "pending") || [], [proposalMatches]);
  const newPropProfileMatches = useMemo(() => propProfileMatches?.filter(m => m.status === "new") || [], [propProfileMatches]);

  const tabs: { key: TabKey; label: string; icon: keyof typeof Ionicons.glyphMap; count: number }[] = [
    { key: "zavorrine", label: t("match.tabZavorrine"), icon: "person", count: newGarageMatches.length },
    { key: "biker", label: t("match.tabBiker"), icon: "bicycle", count: newBikerMatches.length },
    { key: "proposals", label: t("match.tabProposals"), icon: "flash", count: newProposalMatches.length },
    { key: "propProfile", label: t("match.tabPropProfile"), icon: "location", count: newPropProfileMatches.length },
    { key: "music", label: t("match.tabMusic"), icon: "musical-notes", count: 0 },
    { key: "accepted", label: t("match.tabAccepted"), icon: "checkmark-circle", count: 0 },
    { key: "blacklist", label: t("match.tabBlacklist"), icon: "ban", count: 0 },
  ];

  const getEmptyIcon = (): keyof typeof Ionicons.glyphMap => {
    if (activeTab === "zavorrine") return "person-outline";
    if (activeTab === "biker") return "bicycle-outline";
    if (activeTab === "music") return "musical-notes-outline";
    if (activeTab === "accepted") return "checkmark-circle-outline";
    if (activeTab === "blacklist") return "ban-outline";
    if (activeTab === "propProfile") return "location-outline";
    return "flash-outline";
  };

  const getEmptyTitle = () => {
    if (activeTab === "zavorrine") return t("match.emptyZavorrinaTitle");
    if (activeTab === "biker") return t("match.emptyBikerTitle");
    if (activeTab === "music") return t("match.emptyMusicNoMatchTitle");
    if (activeTab === "accepted") return t("match.emptyAcceptedTitle");
    if (activeTab === "blacklist") return t("match.emptyBlacklistTitle");
    if (activeTab === "propProfile") return t("match.emptyPropProfileTitle");
    return t("match.emptyProposalsTitle");
  };

  const getEmptyDesc = () => {
    if (activeTab === "zavorrine") return t("match.emptyZavorrinaDesc");
    if (activeTab === "biker") return t("match.emptyBikerDesc");
    if (activeTab === "music") return t("match.emptyMusicNoMatchDesc");
    if (activeTab === "accepted") return t("match.emptyAcceptedDesc");
    if (activeTab === "blacklist") return t("match.emptyBlacklistDesc");
    if (activeTab === "propProfile") return t("match.emptyPropProfileDesc");
    return t("match.emptyProposalsDesc");
  };

  const isRematching = resetAndRematchMutation.isPending;
  const isAnyRefetching = garageIsFetching || bikerIsFetching || proposalRefetching;
  const myLat = myProfile?.latitude;
  const myLng = myProfile?.longitude;

  const kmLimit = parseInt(distanceKm, 10) || 50;

  return (
    <View style={[styles.container, { paddingTop: insets.top, backgroundColor: colors.background }]}>
      <InlineMiniPlayer />
      <MatchHeader title={t("match.title")} systemDesc={t("match.systemDesc")} />

      <MatchFiltersPanel 
        distanceMode={distanceMode}
        setDistanceMode={(mode) => {
          const wasKm = distanceMode === "km" && mode === "all";
          setDistanceMode(mode);
          AsyncStorage.multiSet([["match_distance_mode", mode], ["match_distance_km", distanceKm]]).catch(() => {});
          if (wasKm) resetAndRematchMutation.mutate();
        }}
        pendingKm={pendingKm}
        setPendingKm={setPendingKm}
        isRematching={isRematching}
        isAnyRefetching={isAnyRefetching}
        onApplyDistance={handleResetAndRematch}
        myLat={myLat}
        myLng={myLng}
      />

      <TabBar activeTab={activeTab} setActiveTab={setActiveTab} tabs={tabs} />

      <BikerInfoBanner visible={activeTab === "biker"} />

      <MusicCriteriaChip 
        visible={activeTab === "music" && lastfmStatus?.connected === true}
        musicCriteria={musicCriteria}
        musicMinSongs={musicMinSongs}
        distanceMode={distanceMode}
        kmLimit={kmLimit}
      />

      {activeTab === "music" && lastfmStatus?.connected !== true ? (
        <MatchEmptyState 
          icon="musical-notes-outline"
          title={t("match.emptyMusicTitle")}
          description={t("match.emptyMusicDesc")}
        />
      ) : (
        <MatchCardStack 
          currentList={currentList}
          renderItem={renderItem}
          isRefetching={isRefetching}
          onRefresh={onRefresh}
          isLoading={isLoading}
          isServerBusy={isServerBusy}
          activeTab={activeTab}
          getEmptyIcon={getEmptyIcon}
          getEmptyTitle={getEmptyTitle}
          getEmptyDesc={getEmptyDesc}
        />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.background,
  },
});

import React, { useState, useCallback, useEffect, useMemo } from "react";
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TouchableOpacity,
  ActivityIndicator,
  RefreshControl,
  Alert,
  BackHandler,
} from "react-native";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useRouter } from "expo-router";
import { apiRequest } from "@/lib/query-client";
import Colors from "@/constants/colors";
import { InlineMiniPlayer } from "@/components/MiniPlayer";
import { useT } from "@/lib/language-context";

// Local Components
import { MotoClubCard, Club, UserClub } from "@/components/motoclub/MotoClubCard";
import { MotoClubSearch } from "@/components/motoclub/MotoClubSearch";
import { FeaturedClubsSection } from "@/components/motoclub/FeaturedClubsSection";
import { MotoClubInvites, Invite } from "@/components/motoclub/MotoClubInvites";
import { MotoClubMarketplace, MarketplaceMoto } from "@/components/motoclub/MotoClubMarketplace";
import { InvitesBanner } from "@/components/motoclub/InvitesBanner";

export default function MotoclubScreen() {
  const t = useT();
  const insets = useSafeAreaInsets();
  const queryClient = useQueryClient();
  const router = useRouter();

  const [tab, setTab] = useState<"all" | "mine" | "market">("all");
  const [search, setSearch] = useState("");
  const [filterType, setFilterType] = useState<"" | "brand" | "model" | "custom">("");
  const [filterCountry, setFilterCountry] = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [showInvites, setShowInvites] = useState(false);

  useEffect(() => {
    if (!showInvites) return;
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      setShowInvites(false);
      return true;
    });
    return () => sub.remove();
  }, [showInvites]);

  const clubsUrl = useMemo(() => {
    const p = new URLSearchParams();
    if (search.trim()) p.append("search", search.trim());
    if (filterType) p.append("type", filterType);
    if (filterCountry) p.append("country", filterCountry);
    const qs = p.toString();
    return qs ? `/api/motoclubs?${qs}` : "/api/motoclubs";
  }, [search, filterType, filterCountry]);

  const { data: clubs = [], isLoading: loadingClubs, refetch: refetchClubs } = useQuery<Club[]>({
    queryKey: [clubsUrl],
  });

  const { data: myClubs = [], refetch: refetchMine } = useQuery<UserClub[]>({
    queryKey: ["/api/motoclubs/me/clubs"],
  });

  const { data: featured } = useQuery<Club | null>({
    queryKey: ["/api/motoclubs/featured"],
  });

  const { data: invites = [] } = useQuery<Invite[]>({
    queryKey: ["/api/motoclubs/invites"],
  });

  const { data: marketplaceData } = useQuery<{ enabled: boolean }>({
    queryKey: ["/api/settings/marketplace-enabled"],
  });
  const marketplaceEnabled = marketplaceData?.enabled !== false;

  const { data: motoclubCreationData } = useQuery<{ enabled: boolean }>({
    queryKey: ["/api/settings/motoclub-user-creation"],
  });
  const motoclubCreationEnabled = motoclubCreationData?.enabled === true;

  const { data: creationStatus } = useQuery<{ status: string } | null>({
    queryKey: ["/api/motoclubs/creation-request/status"],
    enabled: motoclubCreationEnabled,
  });
  const hasPendingRequest = creationStatus?.status === "pending";

  const { data: marketplaceMotos = [], refetch: refetchMarket } = useQuery<MarketplaceMoto[]>({
    queryKey: ["/api/motoclubs/marketplace"],
    enabled: marketplaceEnabled && tab === "market",
  });

  const pendingInvites = invites.filter((i) => i.status === "pending");

  const myClubIds = useMemo(() => new Set(myClubs.map((c) => c.id)), [myClubs]);
  const myClubMap = useMemo(() => new Map(myClubs.map((c) => [c.id, c])), [myClubs]);

  const invalidateClubLists = useCallback(() => {
    queryClient.invalidateQueries({
      predicate: (query) => {
        const key = query.queryKey[0];
        return typeof key === "string" && key.startsWith("/api/motoclubs");
      },
    });
  }, [queryClient]);

  const joinMut = useMutation({
    mutationFn: (clubId: string) =>
      apiRequest("POST", `/api/motoclubs/${clubId}/join`),
    onSuccess: invalidateClubLists,
  });

  const leaveMut = useMutation({
    mutationFn: (clubId: string) =>
      apiRequest("POST", `/api/motoclubs/${clubId}/leave`),
    onSuccess: invalidateClubLists,
  });

  const respondMut = useMutation({
    mutationFn: ({ id, action }: { id: string; action: "accept" | "reject" }) =>
      apiRequest("PUT", `/api/motoclubs/invites/${id}/respond`, {
        response: action === "accept" ? "accepted" : "declined",
      }),
    onSuccess: invalidateClubLists,
  });

  const syncGarageMut = useMutation({
    mutationFn: async () => {
      const res = await apiRequest("POST", "/api/motoclubs/sync-garage");
      return res.json() as Promise<{ joined: number; message: string }>;
    },
    onSuccess: (data) => {
      invalidateClubLists();
      Alert.alert(
        data.joined > 0 ? t("motoclub.clubsFound") : t("motoclub.noClub"),
        data.message
      );
    },
    onError: () => {
      Alert.alert(t("common.error"), t("motoclub.syncError"));
    },
  });

  const handleJoin = useCallback(
    (clubId: string) => {
      joinMut.mutate(clubId);
    },
    [joinMut]
  );

  const handleLeave = useCallback(
    (clubId: string, name: string) => {
      Alert.alert(t("motoclub.leaveTitle"), t("motoclub.leaveMsg").replace("{name}", name), [
        { text: t("common.cancel"), style: "cancel" },
        { text: t("motoclub.leaveConfirm"), style: "destructive", onPress: () => leaveMut.mutate(clubId) },
      ]);
    },
    [leaveMut, t]
  );

  const handleOpenChat = useCallback(
    (clubId: string, conversationId?: string | null) => {
      const url = conversationId
        ? `/motoclub/${clubId}?conversationId=${conversationId}`
        : `/motoclub/${clubId}`;
      router.push(url as any);
    },
    [router]
  );

  const displayedClubs = tab === "mine"
    ? clubs.filter((c) => myClubIds.has(c.id))
    : clubs;

  const topInset = insets.top;

  if (showInvites && pendingInvites.length > 0) {
    return (
      <View style={[styles.container, { paddingTop: topInset }]}>
        <MotoClubInvites
          pendingInvites={pendingInvites}
          clubs={clubs}
          onBack={() => setShowInvites(false)}
          onRespond={(id, action) => respondMut.mutate({ id, action })}
        />
      </View>
    );
  }

  return (
    <View style={[styles.container, { paddingTop: topInset }]}>
      <InlineMiniPlayer />
      <MotoClubSearch
        search={search}
        setSearch={setSearch}
        showFilters={showFilters}
        setShowFilters={setShowFilters}
        filterType={filterType}
        setFilterType={setFilterType}
        filterCountry={filterCountry}
        setFilterCountry={setFilterCountry}
        tab={tab}
        setTab={setTab}
        marketplaceEnabled={marketplaceEnabled}
      />

      {tab === "market" && marketplaceEnabled ? (
        <MotoClubMarketplace
          myClubs={myClubs}
          marketplaceMotos={marketplaceMotos}
          onRefresh={() => { refetchMarket(); }}
          bottomInset={insets.bottom}
        />
      ) : loadingClubs ? (
        <View style={styles.loader}>
          <ActivityIndicator color={Colors.accent} size="large" />
        </View>
      ) : (
        <FlatList
          data={displayedClubs}
          keyExtractor={(c) => c.id}
          contentContainerStyle={{ paddingBottom: 32 + insets.bottom }}
          refreshControl={
            <RefreshControl
              refreshing={false}
              onRefresh={() => { refetchClubs(); refetchMine(); }}
              tintColor={Colors.accent}
            />
          }
          ListHeaderComponent={
            <>
              <InvitesBanner
                count={pendingInvites.length}
                onPress={() => setShowInvites(true)}
              />
              {tab === "mine" && myClubs.length === 0 && (
                <TouchableOpacity
                  style={styles.syncBanner}
                  onPress={() => syncGarageMut.mutate()}
                  disabled={syncGarageMut.isPending}
                  activeOpacity={0.8}
                >
                  {syncGarageMut.isPending
                    ? <ActivityIndicator size="small" color={Colors.accent} />
                    : <Ionicons name="sync-outline" size={18} color={Colors.accent} />}
                  <Text style={styles.syncBannerText}>
                    {syncGarageMut.isPending ? t("motoclub.syncing") : t("motoclub.syncGarage")}
                  </Text>
                </TouchableOpacity>
              )}
              {tab === "all" && featured && !search && !filterType && !filterCountry && (
                <FeaturedClubsSection
                  club={featured}
                  myClubIds={myClubIds}
                  onJoin={handleJoin}
                />
              )}
            </>
          }
          ListEmptyComponent={
            <View style={styles.empty}>
              <Ionicons name="shield-outline" size={48} color={Colors.border} />
              <Text style={styles.emptyText}>
                {tab === "mine"
                  ? t("motoclub.noMineClub")
                  : t("motoclub.noClubFound")}
              </Text>
            </View>
          }
          renderItem={({ item }) => {
            const myData = myClubMap.get(item.id);
            return (
              <MotoClubCard
                club={item}
                myClubIds={myClubIds}
                onJoin={handleJoin}
                onLeave={handleLeave}
                onOpenChat={handleOpenChat}
                joinedAt={myData?.joinedAt}
                role={myData?.role}
                conversationId={myData?.conversationId}
              />
            );
          }}
        />
      )}

      {motoclubCreationEnabled && !hasPendingRequest && (
        <TouchableOpacity
          style={[styles.fab, { bottom: insets.bottom + 16 }]}
          onPress={() => router.push("/motoclub/create" as any)}
          activeOpacity={0.85}
        >
          <Ionicons name="add" size={26} color="#fff" />
        </TouchableOpacity>
      )}
      {motoclubCreationEnabled && hasPendingRequest && (
        <TouchableOpacity
          style={[styles.fab, { bottom: insets.bottom + 16, backgroundColor: Colors.warning }]}
          onPress={() => router.push("/motoclub/create" as any)}
          activeOpacity={0.85}
        >
          <Ionicons name="time" size={22} color="#fff" />
        </TouchableOpacity>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: Colors.background },
  loader: { flex: 1, alignItems: "center", justifyContent: "center" },
  syncBanner: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    backgroundColor: Colors.accent + "12",
    borderRadius: 12,
    marginHorizontal: 12,
    marginTop: 10,
    padding: 12,
    borderWidth: 1,
    borderColor: Colors.accent + "30",
  },
  syncBannerText: { flex: 1, fontSize: 13, color: Colors.accent, fontFamily: "Inter_500Medium" },
  empty: { alignItems: "center", justifyContent: "center", paddingVertical: 60, gap: 12 },
  emptyText: {
    fontSize: 14,
    color: Colors.textSecondary,
    textAlign: "center",
    fontFamily: "Inter_400Regular",
    lineHeight: 22,
  },
  fab: {
    position: "absolute",
    right: 20,
    width: 52,
    height: 52,
    borderRadius: 26,
    backgroundColor: Colors.accent,
    alignItems: "center",
    justifyContent: "center",
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 3 },
    shadowOpacity: 0.25,
    shadowRadius: 6,
    elevation: 6,
  },
});

import React, { useState, useCallback, useEffect } from "react";
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  FlatList,
  Image,
  TextInput,
  Modal,
} from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useLocalSearchParams, useRouter } from "expo-router";
import AsyncStorage from "@react-native-async-storage/async-storage";

import Colors from "@/constants/colors";
import { apiRequest, getApiUrl } from "@/lib/query-client";
import { InlineMiniPlayer } from "@/components/MiniPlayer";
import { useAuth } from "@/lib/auth-context";
import { useT } from "@/lib/language-context";
import { styles, lastfmBannerStyles } from "@/components/music/styles";

import {
  Tab,
  LASTFM_RED,
  SearchTrack,
  LibraryTrack,
  MusicMatch,
  SharedPlaylistEntry,
  ChatConversation,
} from "@/components/music/types";

import { BraniTab } from "@/components/music/BraniTab";
import { MatchTab } from "@/components/music/MatchTab";
import { SharedPlaylistsTab } from "@/components/music/SharedPlaylistsTab";
import { MusicRadioTab } from "@/components/music/MusicRadioTab";
import { TelefonoTab } from "@/components/music/TelefonoTab";
import { LastfmLoginModal } from "@/components/music/LastfmLoginModal";

export default function MusicScreen() {
  const t = useT();
  const insets = useSafeAreaInsets();
  const queryClient = useQueryClient();
  const { tab: tabParam, playlistId: playlistIdParam } = useLocalSearchParams<{ tab?: string; playlistId?: string }>();

  const [activeTab, setActiveTab] = useState<Tab>("brani");
  const [searchInput, setSearchInput] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [matchCriteria, setMatchCriteria] = useState<string[]>(["songs", "genre"]);
  const [matchMaxKm, setMatchMaxKm] = useState(100);
  const [matchLogic, setMatchLogic] = useState<"tutti" | "almeno_uno">("almeno_uno");
  const [minSongs, setMinSongs] = useState(5);
  const [playlistOverride, setPlaylistOverride] = useState<{ nickname: string; tracks: LibraryTrack[] } | null>(null);

  const [pendingAddId, setPendingAddId] = useState<string | null>(null);
  const [pendingRemoveId, setPendingRemoveId] = useState<string | null>(null);
  const [isConnecting, setIsConnecting] = useState(false);
  const [searchNeedsReconnect, setSearchNeedsReconnect] = useState(false);

  const [lastfmModalVisible, setLastfmModalVisible] = useState(false);
  const [sendModalVisible, setSendModalVisible] = useState(false);
  const [sendingToConv, setSendingToConv] = useState<string | null>(null);

  const { user: currentUser } = useAuth();
  const router = useRouter();

  const apiPrefix = "/api/lastfm";

  const statusQuery = useQuery<{ connected: boolean; displayName?: string; username?: string; trackCount: number }>({
    queryKey: [`${apiPrefix}/status`],
    staleTime: 60_000,
  });

  const conversationsQuery = useQuery<ChatConversation[]>({
    queryKey: ["/api/chat/conversations"],
    enabled: sendModalVisible,
    staleTime: 30_000,
  });

  const handleSendPlaylist = useCallback(async (conv: ChatConversation) => {
    const otherUser = conv.participants.find((p) => p.id !== currentUser?.id);
    if (!otherUser) return;
    setSendingToConv(conv.id);
    try {
      const res = await apiRequest("POST", `${apiPrefix}/share-playlist`, {
        toUserId: otherUser.id,
        conversationId: conv.id,
      });
      const body = await res.json();
      if (!res.ok) {
        const msg = (body as { message?: string }).message ?? t("music.error");
        if (msg.toLowerCase().includes("nessuna traccia") || msg.toLowerCase().includes("nessun brano")) {
          Alert.alert(t("music.emptyPlaylistTitle"), t("music.connectFirstMsg"));
        } else {
          Alert.alert(t("music.error"), msg);
        }
        return;
      }
      setSendModalVisible(false);
      router.push(`/chat/${conv.id}` as any);
    } catch {
      Alert.alert(t("music.error"), t("music.sendPlaylistError"));
    } finally {
      setSendingToConv(null);
    }
  }, [currentUser, router, apiPrefix, t]);

  useEffect(() => {
    if (tabParam === "ricevute" || tabParam === "match" || tabParam === "brani" || tabParam === "telefono") {
      setActiveTab(tabParam as Tab);
    }
  }, [tabParam]);

  useEffect(() => {
    if (!playlistIdParam) return;
    const numId = parseInt(playlistIdParam, 10);
    if (isNaN(numId)) return;
    const url = new URL(`${apiPrefix}/shared-playlists/${numId}`, getApiUrl());
    fetch(url.toString(), { credentials: "include" })
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then((data: { id: number; fromUser: { nickname: string }; tracks: Array<{ trackId: string; trackName: string; artistName: string; albumName?: string | null; imageUrl?: string | null }> }) => {
        const mapped: LibraryTrack[] = data.tracks.map((t, i) => ({
          id: i,
          lastfmTrackId: t.trackId,
          trackName: t.trackName,
          artistName: t.artistName,
          albumName: t.albumName ?? null,
          imageUrl: t.imageUrl ?? null,
          popularity: 0,
          addedAt: "",
        }));
        setPlaylistOverride({ nickname: data.fromUser.nickname, tracks: mapped });
        setActiveTab("brani");
      })
      .catch(() => {
        Alert.alert(t("music.playlistUnavailable"), t("music.playlistUnavailableMsg"));
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [playlistIdParam]);

  useEffect(() => {
    AsyncStorage.multiGet(["music_match_criteria", "music_match_logic", "music_match_min_songs"])
      .then(pairs => {
        const criteria = pairs[0][1];
        const logic = pairs[1][1];
        const minS = pairs[2][1];
        if (criteria) setMatchCriteria(criteria.split(",").filter(Boolean));
        if (logic === "tutti" || logic === "almeno_uno") setMatchLogic(logic as any);
        if (minS) setMinSongs(parseInt(minS, 10) || 5);
      })
      .catch(() => {});
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(searchInput.trim());
      setSearchNeedsReconnect(false);
    }, 400);
    return () => clearTimeout(timer);
  }, [searchInput]);

  const searchQuery = useQuery<{ tracks: SearchTrack[] }>({
    queryKey: [`${apiPrefix}/search`, debouncedQuery],
    queryFn: async () => {
      const url = new URL(`${apiPrefix}/search`, getApiUrl());
      url.searchParams.set("q", debouncedQuery);
      const res = await fetch(url.toString(), { credentials: "include" });
      if (!res.ok) {
        let msg = `${res.status}`;
        try {
          const body = await res.json();
          if (typeof body.message === "string") msg = body.message;
        } catch (e) {
          console.warn("[music] search error body parse:", e);
        }
        throw new Error(msg);
      }
      setSearchNeedsReconnect(false);
      return res.json();
    },
    enabled: debouncedQuery.length >= 2 && activeTab === "brani",
    staleTime: 30_000,
  });

  const tracksQuery = useQuery<{ tracks: LibraryTrack[] }>({
    queryKey: [`${apiPrefix}/tracks`],
  });

  const matchQuery = useQuery<{ matches: MusicMatch[] }>({
    queryKey: ["/api/match/music"],
    queryFn: async () => {
      const url = new URL("/api/match/music", getApiUrl());
      url.searchParams.set("criteria", matchCriteria.join(","));
      url.searchParams.set("maxKm", String(matchMaxKm));
      url.searchParams.set("logic", matchLogic === "tutti" ? "all" : "any");
      url.searchParams.set("minSongs", String(minSongs));
      const res = await fetch(url.toString(), { credentials: "include" });
      if (!res.ok) throw new Error(`${res.status}`);
      return res.json();
    },
    enabled: false,
  });

  const sharedPlaylistsQuery = useQuery<{ playlists: SharedPlaylistEntry[] }>({
    queryKey: [`${apiPrefix}/shared-playlists`],
    enabled: activeTab === "ricevute",
  });

  const addTrackMutation = useMutation({
    mutationFn: async (track: SearchTrack) => {
      setPendingAddId(track.lastfmTrackId);
      const res = await apiRequest("POST", `${apiPrefix}/tracks`, track);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`${apiPrefix}/tracks`] });
    },
    onError: (err: Error) => {
      Alert.alert(t("music.error"), err.message ?? t("music.addTrackError"));
    },
    onSettled: () => setPendingAddId(null),
  });

  const removeTrackMutation = useMutation({
    mutationFn: async (lastfmTrackId: string) => {
      setPendingRemoveId(lastfmTrackId);
      const res = await apiRequest("DELETE", `${apiPrefix}/tracks/${encodeURIComponent(lastfmTrackId)}`, {});
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`${apiPrefix}/tracks`] });
    },
    onError: (err: Error) => {
      Alert.alert(t("music.error"), err.message ?? t("music.removeTrackError2"));
    },
    onSettled: () => setPendingRemoveId(null),
  });

  const mergePlaylistMutation = useMutation({
    mutationFn: async (playlistId: number) => {
      const res = await apiRequest("POST", `${apiPrefix}/merge-playlist/${playlistId}`, {});
      return res.json() as Promise<{ newTracksAdded: number }>;
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: [`${apiPrefix}/shared-playlists`] });
      queryClient.invalidateQueries({ queryKey: [`${apiPrefix}/tracks`] });
      Alert.alert("Playlist Aggiunta!", `${data.newTracksAdded ?? 0} nuovi brani aggiunti alla tua Playlist.`);
    },
    onError: (err: Error) => {
      Alert.alert(t("music.error"), err.message);
    },
  });

  const disconnectMutation = useMutation({
    mutationFn: async () => {
      const res = await apiRequest("POST", `${apiPrefix}/disconnect`, {});
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`${apiPrefix}/status`] });
      queryClient.invalidateQueries({ queryKey: [`${apiPrefix}/tracks`] });
    },
    onError: (err: Error) => {
      Alert.alert(t("music.error"), err.message ?? "Impossibile disconnettere");
    },
  });

  const handleDisconnect = useCallback(() => {
    Alert.alert(
      t("music.disconnectTitle2"),
      t("music.disconnectMsg2"),
      [
        { text: t("common.cancel"), style: "cancel" },
        { text: t("music.disconnectBtn"), style: "destructive", onPress: () => disconnectMutation.mutate() },
      ]
    );
  }, [disconnectMutation, t]);

  const toggleCriteria = useCallback((c: string) => {
    setMatchCriteria((prev) => {
      const next = prev.includes(c) ? (prev.length > 1 ? prev.filter((x) => x !== c) : prev) : [...prev, c];
      AsyncStorage.setItem("music_match_criteria", next.join(",")).catch(() => {});
      return next;
    });
  }, []);

  const handleSetMatchLogic = useCallback((v: "tutti" | "almeno_uno") => {
    setMatchLogic(v);
    AsyncStorage.setItem("music_match_logic", v).catch(() => {});
  }, []);

  const handleSetMinSongs = useCallback((v: number) => {
    setMinSongs(v);
    AsyncStorage.setItem("music_match_min_songs", String(v)).catch(() => {});
  }, []);

  const savedIds = new Set((tracksQuery.data?.tracks ?? []).map((t) => t.lastfmTrackId));
  const topPadding = insets.top;
  const providerColor = LASTFM_RED;

  const isConnected = statusQuery.isLoading ? null : (statusQuery.data?.connected ?? false);
  const isLastfmConnected = isConnected === true;

  const tabItems = (["brani", "match", "ricevute", "radio", "telefono"] as Tab[]).map((tab) => (
    <TouchableOpacity
      key={tab}
      style={[styles.tabItem, activeTab === tab && styles.tabItemActive]}
      onPress={() => setActiveTab(tab)}
    >
      {tab === "radio" ? (
        <View style={{ flexDirection: "row", alignItems: "center", gap: 4 }}>
          <Ionicons name="radio-outline" size={12} color={activeTab === "radio" ? Colors.accent : Colors.textSecondary} />
          <Text style={[styles.tabText, activeTab === tab && styles.tabTextActive]}>Radio</Text>
        </View>
      ) : tab === "telefono" ? (
        <View style={{ flexDirection: "row", alignItems: "center", gap: 4 }}>
          <Ionicons name="phone-portrait-outline" size={12} color={activeTab === "telefono" ? Colors.accent : Colors.textSecondary} />
          <Text style={[styles.tabText, activeTab === tab && styles.tabTextActive]}>{t("music.tabTelefono")}</Text>
        </View>
      ) : (
        <Text style={[styles.tabText, activeTab === tab && styles.tabTextActive]}>
          {tab === "brani" ? t("music.tabBrani") : tab === "match" ? "Match" : t("music.tabRicevute")}
        </Text>
      )}
    </TouchableOpacity>
  ));

  return (
    <>
      <View style={[styles.container, { paddingTop: topPadding }]}>
        <InlineMiniPlayer />

        {!isLastfmConnected && (
          <View style={styles.header}>
            <View style={styles.headerLeft}>
              <Ionicons name="musical-notes" size={24} color={providerColor} />
              <Text style={styles.headerTitle}>Musica</Text>
            </View>
            <View style={styles.headerRight}>
              {statusQuery.data?.connected && (
                <Text style={styles.headerCount}>
                  {tracksQuery.data ? `${tracksQuery.data.tracks.length} brani` : ""}
                </Text>
              )}
            </View>
          </View>
        )}

        {isLastfmConnected ? (
          <View style={styles.compactHeader}>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ flex: 1 }} contentContainerStyle={styles.tabBarContent}>
              {tabItems}
            </ScrollView>
          </View>
        ) : (
          <>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.tabBar} contentContainerStyle={styles.tabBarContent}>
              {tabItems}
            </ScrollView>

            {isConnected === false && (
              <View style={lastfmBannerStyles.banner}>
                <Ionicons name="warning-outline" size={18} color="#92400e" style={{ marginRight: 8, flexShrink: 0 }} />
                <Text style={lastfmBannerStyles.text}>
                  {t("music.lastfmAuthWarning")}
                </Text>
              </View>
            )}
          </>
        )}

        {activeTab === "brani" && (
          <BraniTab
            provider="lastfm"
            isConnected={isConnected}
            isConnecting={isConnecting}
            onConnect={() => setLastfmModalVisible(true)}
            searchNeedsReconnect={searchNeedsReconnect}
            searchInput={searchInput}
            onSearchChange={setSearchInput}
            debouncedQuery={debouncedQuery}
            searchResults={searchQuery.data?.tracks ?? []}
            searchLoading={searchQuery.isLoading}
            searchError={searchQuery.isError && !searchNeedsReconnect ? ((searchQuery.error?.message && searchQuery.error.message.length > 5) ? searchQuery.error.message : "Errore nella ricerca. Riprova.") : null}
            library={tracksQuery.data?.tracks ?? []}
            libraryLoading={tracksQuery.isLoading}
            savedIds={savedIds}
            onAdd={(track) => addTrackMutation.mutate(track)}
            onRemove={(id) => removeTrackMutation.mutate(id)}
            pendingAddId={pendingAddId}
            pendingRemoveId={pendingRemoveId}
            onDisconnect={handleDisconnect}
            onShare={() => setSendModalVisible(true)}
            playlistOverride={playlistOverride}
            onResetPlaylist={() => setPlaylistOverride(null)}
          />
        )}
        {activeTab === "match" && (
          <MatchTab
            matches={matchQuery.data?.matches ?? []}
            isFetching={matchQuery.isFetching}
            hasData={matchQuery.data !== undefined}
            criteria={matchCriteria}
            onToggleCriteria={toggleCriteria}
            maxKm={matchMaxKm}
            onSetMaxKm={setMatchMaxKm}
            matchLogic={matchLogic}
            onSetMatchLogic={handleSetMatchLogic}
            minSongs={minSongs}
            onSetMinSongs={handleSetMinSongs}
            onSearch={() => matchQuery.refetch()}
          />
        )}
        {activeTab === "ricevute" && (
          <SharedPlaylistsTab
            playlists={sharedPlaylistsQuery.data?.playlists ?? []}
            isLoading={sharedPlaylistsQuery.isLoading}
            onMerge={(id) => mergePlaylistMutation.mutate(id)}
            isMerging={mergePlaylistMutation.isPending}
          />
        )}
        {activeTab === "radio" && <MusicRadioTab />}
        {activeTab === "telefono" && <TelefonoTab />}
      </View>

      <LastfmLoginModal
        visible={lastfmModalVisible}
        onClose={() => setLastfmModalVisible(false)}
      />

      {sendModalVisible && (
        <Modal
          visible={sendModalVisible}
          transparent
          animationType="slide"
          onRequestClose={() => !sendingToConv && setSendModalVisible(false)}
        >
          <View style={styles.sendModalOverlay}>
            <View style={styles.sendModalCard}>
              <View style={styles.sendModalHeader}>
                <Ionicons name="share-social" size={22} color={Colors.accent} />
                <Text style={styles.sendModalTitle}>Invia la mia musica</Text>
                <TouchableOpacity
                  onPress={() => setSendModalVisible(false)}
                  disabled={!!sendingToConv}
                  hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                >
                  <Ionicons name="close" size={22} color={Colors.textSecondary} />
                </TouchableOpacity>
              </View>
              <Text style={styles.sendModalSub}>Scegli una chat a cui inviare la tua Playlist</Text>
              {conversationsQuery.isLoading ? (
                <ActivityIndicator color={Colors.accent} style={{ marginVertical: 24 }} />
              ) : (conversationsQuery.data ?? []).length === 0 ? (
                <View style={{ alignItems: "center", paddingVertical: 24, gap: 8 }}>
                  <Ionicons name="chatbubbles-outline" size={36} color={Colors.textSecondary} />
                  <Text style={styles.sendModalEmpty}>Nessuna chat attiva. Inizia una conversazione prima.</Text>
                </View>
              ) : (
                <FlatList
                  data={conversationsQuery.data ?? []}
                  keyExtractor={(item) => item.id}
                  style={{ maxHeight: 340 }}
                  renderItem={({ item: conv }) => {
                    const otherUser = conv.participants.find((p) => p.id !== currentUser?.id);
                    if (!otherUser) return null;
                    const isSending = sendingToConv === conv.id;
                    return (
                      <TouchableOpacity
                        style={styles.sendConvRow}
                        onPress={() => handleSendPlaylist(conv)}
                        disabled={!!sendingToConv}
                        activeOpacity={0.7}
                      >
                        {otherUser.avatarUrl ? (
                          <Image source={{ uri: otherUser.avatarUrl }} style={styles.sendConvAvatar} />
                        ) : (
                          <View style={[styles.sendConvAvatar, styles.sendConvAvatarPlaceholder]}>
                            <Ionicons name="person" size={16} color={Colors.textSecondary} />
                          </View>
                        )}
                        <Text style={styles.sendConvName} numberOfLines={1}>{otherUser.nickname}</Text>
                        {isSending ? (
                          <ActivityIndicator size="small" color={Colors.accent} />
                        ) : (
                          <Ionicons name="chevron-forward" size={16} color={Colors.textSecondary} />
                        )}
                      </TouchableOpacity>
                    );
                  }}
                />
              )}
            </View>
          </View>
        </Modal>
      )}
    </>
  );
}

