      )}

      {/* ── SUMMARY MODAL ────────────────────────────────────────────────── */}
      <SummaryModal
        visible={state.summaryVisible}
        onClose={() => handlers.setSummaryVisible(false)}
        insets={insets}
        rideTitle={state.rideTitle}
