type Subscription = ReturnType<DeviceSensor<any>["addListener"]>;

export { SensorKey, SensorDefinition };

function nowHMS(): string {
  const d = new Date();
  const p = (n: number) => String(n).padStart(2, "0");
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

