  AdminFetchError,
  isAdminError,
  formatDuration,
  formatTimestamp,
  eventIcon,
  eventLabel,
  platformLabel,
  type SystemEvent,
  type SystemHealth,
  type RestartHistory,
  type NativeVersionConfigData,
} from "@/components/admin/system/systemUtils";


function outcomeMeta(o: UpdateOutcome, t: (key: string) => string): { label: string; color: string; icon: keyof typeof Ionicons.glyphMap } {
  if (o === "force") return { label: "Force update richiesto", color: "#FF4444", icon: "alert-circle" };
  if (o === "soft") return { label: "Soft update disponibile", color: "#FFAA00", icon: "arrow-up-circle" };
  return { label: t("admin.noUpdate"), color: "#44AA44", icon: "checkmark-circle" };
}

export default function SystemScreen() {
  const t = useT();
  const insets = useSafeAreaInsets();
  const navigation = useNavigation();
  const [backendUptimeSec, setBackendUptimeSec] = useState<number>(0);

  const [nativeAndroidLatest, setNativeAndroidLatest] = useState("");
  const [nativeAndroidMin, setNativeAndroidMin] = useState("");
  const [nativeAndroidUrl, setNativeAndroidUrl] = useState("");
  const [nativeIosLatest, setNativeIosLatest] = useState("");
  const [nativeIosMin, setNativeIosMin] = useState("");
  const [nativeIosUrl, setNativeIosUrl] = useState("");
  const [savingNative, setSavingNative] = useState(false);

  const { data: nativeVerData, refetch: refetchNativeVer, isFetching: isFetchingNativeVer } = useQuery<NativeVersionConfigData>({
    queryKey: ["/api/settings/native-version"],
  });

  const installedVersion = Constants.expoConfig?.version ?? "0.0.0";
  const installedPlatform: "android" | "ios" = Platform.OS === "ios" ? "ios" : "android";

  const checkOutcome: UpdateOutcome | null = useMemo(() => {
    if (!nativeVerData) return null;
    const cfg = installedPlatform === "android" ? nativeVerData.android : nativeVerData.ios;
    return evaluateUpdateOutcome(installedVersion, cfg.minVersion, cfg.latestVersion);
  }, [nativeVerData, installedPlatform, installedVersion]);

  const [isCleanupRunning, setIsCleanupRunning] = useState(false);
  const [isPurging, setIsPurging] = useState(false);
  const [purgeModalVisible, setPurgeModalVisible] = useState(false);
  const [purgeConfirmText, setPurgeConfirmText] = useState("");

  const handleCacheCleanup = useCallback(async () => {
    setIsCleanupRunning(true);
    try {
      await apiRequest("POST", "/api/admin/cache/cleanup");
      Alert.alert("Avviata", "Pulizia cache workspace avviata in background.");
    } catch (e: any) {
      if (e.status === 409) {
        Alert.alert("In corso", "Pulizia cache già in esecuzione, attendi.");
      } else {
        Alert.alert("Errore", "Impossibile avviare la pulizia della cache.");
      }
    } finally {
      setIsCleanupRunning(false);
    }
  }, []);

  const [isRechecking, setIsRechecking] = useState(false);
  const handleForceRecheck = useCallback(async () => {
    setIsRechecking(true);
    try {
      await Promise.all([refetchNativeVer(), forceRecheck()]);
    } finally {
      setIsRechecking(false);
    }
  }, [refetchNativeVer]);

  useEffect(() => {
    if (!nativeVerData) return;
    setNativeAndroidLatest(nativeVerData.android.latestVersion);
    setNativeAndroidMin(nativeVerData.android.minVersion);
    setNativeAndroidUrl(nativeVerData.android.storeUrl);
    setNativeIosLatest(nativeVerData.ios.latestVersion);
    setNativeIosMin(nativeVerData.ios.minVersion);
    setNativeIosUrl(nativeVerData.ios.storeUrl);
  }, [nativeVerData]);

  const saveNativeVersion = useCallback(async () => {
    setSavingNative(true);
    try {
      const res = await apiRequest("PUT", "/api/admin/settings/native-version", {
        android: { latestVersion: nativeAndroidLatest, minVersion: nativeAndroidMin, storeUrl: nativeAndroidUrl },
        ios: { latestVersion: nativeIosLatest, minVersion: nativeIosMin, storeUrl: nativeIosUrl },
      });
      Alert.alert("Salvato", "Configurazione versioni native aggiornata.");
    } catch (e: any) {
      Alert.alert("Errore", e.message || "Impossibile salvare la configurazione.");
    } finally {
      setSavingNative(false);
    }
  }, [nativeAndroidLatest, nativeAndroidMin, nativeAndroidUrl, nativeIosLatest, nativeIosMin, nativeIosUrl]);

  const router = useRouter();
  const { sessionExpired, logoutMutation, user } = useAuth();
  const isAdmin = user?.role === "admin";

  const executePurge = useCallback(async () => {
    if (purgeConfirmText.trim().toUpperCase() !== "PURGA") {
      Alert.alert("Conferma errata", "Devi scrivere esattamente PURGA per procedere.");
      return;
    }
    setPurgeModalVisible(false);
    setPurgeConfirmText("");
    setIsPurging(true);
    try {
      const purgeUrl = new URL("/api/admin/purge-non-admin-users", getApiUrl());
      const purgeRes = await fetch(purgeUrl.toString(), {
        method: "DELETE",
        headers: { "Content-Type": "application/json", "X-Confirm-Purge": "PURGE-CONFIRMED" },
        credentials: "include",
      });
      const body = await purgeRes.json();
      Alert.alert(
        "Purga completata",
        `Eliminati ${(body as any).deletedUsers} utenti non-admin.\nLe sessioni sono state invalidate.\nVerrai reindirizzato al login.`,
        [
          {
            text: "OK",
            onPress: async () => {
              try { await logoutMutation.mutateAsync(); } catch {
                // no-op: proceed to login even if logout fails
              }
              router.replace("/(auth)/login");
            },
          },
        ]
      );
    } catch (e: any) {
      Alert.alert("Errore", e.message || t("admin.serverError"));
    } finally {
      setIsPurging(false);
    }
  }, [purgeConfirmText, logoutMutation, router, t]);

  const handlePurgeNonAdminUsers = useCallback(() => {
    Alert.alert(
      t("admin.purgeDb"),
      t("admin.purgeConfirm"),
      [
        { text: t("common.cancel"), style: "cancel" },
        {
          text: t("common.continue"),
          style: "destructive",
          onPress: () => {
            setPurgeConfirmText("");
            setPurgeModalVisible(true);
          },
        },
      ]
    );
  }, [t]);

  const fetchSystemHealth = useCallback(async (signal?: AbortSignal): Promise<SystemHealth> => {
    const url = new URL("/api/admin/system-health", getApiUrl());
    const doFetch = () =>
      fetch(url.toString(), {
        headers: authFetchHeaders(),
        credentials: "include",
        signal,
      });

    let res: Response;
    try {
      res = await doFetch();
    } catch (e: unknown) {
      if (e instanceof Error && e.name === "AbortError") throw e;
      throw new AdminFetchError("network", "network_unavailable");
    }

    // ── 401: silent re-auth one-shot prima di dichiarare la sessione scaduta.
    // Caso tipico: cookie connect.sid stale dopo cold start, ma il Bearer
    // token in AsyncStorage è ancora valido. Se /api/auth/me risponde 200,
    // ritentiamo la fetch silenziosamente; se risponde 401, la sessione è
    // davvero scaduta e segnaliamo l'errore tipizzato.
    if (res.status === 401) {
      const stillValid = await silentAuthRecheck();
      if (stillValid) {
        try {
          res = await doFetch();
        } catch (e: unknown) {
          if (e instanceof Error && e.name === "AbortError") throw e;
          throw new AdminFetchError("network", "network_unavailable");
        }
      }
    }

    if (res.status === 401 || res.status === 403) {
      let reason: string | undefined;
      try {
        const body = (await res.json()) as { reason?: string };
        reason = body?.reason;
      } catch {
        // no-op: reason stays undefined
      }
      throw new AdminFetchError(
        res.status === 401 ? "session_expired" : "forbidden",
        res.status === 401 ? "session_expired" : "forbidden",
        res.status,
        reason,
      );
    }
    if (!res.ok) {
      throw new AdminFetchError("server_error", `server_${res.status}`, res.status);
    }
    return (await res.json()) as SystemHealth;
  }, []);

  const { data, isLoading, error, refetch, isFetching } = useQuery<SystemHealth, AdminFetchError>({
    queryKey: ["/api/admin/system-health"],
    queryFn: ({ signal }) => fetchSystemHealth(signal),
    refetchInterval: 30000,
    retry: (count, e) => {
      if (isAdminError(e) && (e.code === "session_expired" || e.code === "forbidden")) return false;
      return count < 2;
    },
  });

  const { data: restartHistory } = useQuery<RestartHistory>({
    queryKey: ["/api/admin/restart-history"],
    refetchInterval: 60000,
  });

  const mergedEvents = useMemo<SystemEvent[]>(() => {
    const backendEvents: SystemEvent[] = data?.events ?? [];
    return [...backendEvents].sort((a, b) => {
      const ta = new Date(a.timestamp).getTime();
      const tb = new Date(b.timestamp).getTime();
      if (isNaN(ta) && isNaN(tb)) return 0;
      if (isNaN(ta)) return 1;
      if (isNaN(tb)) return -1;
      return tb - ta;
    });
  }, [data?.events]);

  useEffect(() => {
    if (data) {
      setBackendUptimeSec(data.backendUptimeSec);
    }
  }, [data]);

  useEffect(() => {
    const interval = setInterval(() => {
      setBackendUptimeSec((prev) => prev + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const handleRefresh = useCallback(() => {
    refetch();
  }, [refetch]);

  useEffect(() => {
    navigation.setOptions({
      headerRight: () => (
        <TouchableOpacity onPress={handleRefresh} style={{ marginRight: 16 }}>
          {isFetching ? (
            <ActivityIndicator size="small" color={Colors.accent} />
          ) : (
            <Ionicons name="refresh" size={22} color={Colors.accent} />
          )}
        </TouchableOpacity>
      ),
    });
  }, [navigation, handleRefresh, isFetching]);

  const topPadding = 0;
  const bottomPadding = insets.bottom;

  if (isLoading) {
    return <SystemLoadingDisplay topPadding={topPadding} />;
  }

  if (error || !data) {
    const goToLogin = async () => {
      try { await logoutMutation.mutateAsync(); } catch {
        // no-op: proceed to login even if logout fails
      }
      router.replace("/(auth)/login");
    };

    return (
      <SystemErrorDisplay
        error={error}
        sessionExpired={sessionExpired}
        t={t}
        handleRefresh={handleRefresh}
        goToLogin={goToLogin}
        topPadding={topPadding}
      />
    );
  }

  return (
    <>
      <PurgeConfirmationModal
        visible={purgeModalVisible}
        purgeConfirmText={purgeConfirmText}
        setPurgeConfirmText={setPurgeConfirmText}
        onClose={() => { setPurgeModalVisible(false); setPurgeConfirmText(""); }}
        onExecute={executePurge}
        t={t}
      />

      <RecentEventsSection
        events={mergedEvents}
        t={t}
        topPadding={topPadding}
        bottomPadding={bottomPadding}
        ListHeaderComponent={
          <>
            <SystemStatusCard
              backendUptimeSec={backendUptimeSec}
              backendStartedAt={data.backendStartedAt}
              formatDuration={formatDuration}
              formatTimestamp={formatTimestamp}
            />

            <ServerRestartSection
              restartHistory={restartHistory}
              formatTimestamp={formatTimestamp}
            />

            <DatabaseSection
              isCleanupRunning={isCleanupRunning}
              onCacheCleanup={handleCacheCleanup}
              isPurging={isPurging}
              onPurgeNonAdminUsers={handlePurgeNonAdminUsers}
              t={t}
            />

            <NativeVersionConfig
              android={{
                latestVersion: nativeAndroidLatest,
                minVersion: nativeAndroidMin,
                storeUrl: nativeAndroidUrl,
              }}
              ios={{
                latestVersion: nativeIosLatest,
                minVersion: nativeIosMin,
                storeUrl: nativeIosUrl,
              }}
              setNativeAndroidLatest={setNativeAndroidLatest}
              setNativeAndroidMin={setNativeAndroidMin}
              setNativeAndroidUrl={setNativeAndroidUrl}
              setNativeIosLatest={setNativeIosLatest}
              setNativeIosMin={setNativeIosMin}
              setNativeIosUrl={setNativeIosUrl}
              savingNative={savingNative}
              saveNativeVersion={saveNativeVersion}
              isRechecking={isRechecking}
              handleForceRecheck={handleForceRecheck}
              checkOutcome={checkOutcome}
              outcomeMeta={outcomeMeta}
              t={t}
            />

          </>
        }
      />
    </>
  );
}

const styles = StyleSheet.create({
  center: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: Colors.background,
    gap: 12,
  },
  loadingText: {
    color: Colors.textMuted ?? "#888",
    fontFamily: "Inter_400Regular",
    fontSize: 14,
  },
  errorText: {
    color: "#FF4444",
    fontFamily: "Inter_500Medium",
    fontSize: 15,
    textAlign: "center",
  },
  retryBtn: {
    marginTop: 8,
    paddingHorizontal: 20,
    paddingVertical: 8,
    backgroundColor: Colors.accent,
    borderRadius: 8,
  },
  retryBtnText: {
    color: "#fff",
    fontFamily: "Inter_600SemiBold",
    fontSize: 14,
  },
});

import React, { useState, useCallback, useEffect, useMemo, useRef } from "react";
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  ActivityIndicator,
  Platform,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { MaterialCommunityIcons } from "@expo/vector-icons";
import * as FileSystem from "expo-file-system/legacy";
import * as Sharing from "expo-sharing";
import * as DocumentPicker from "expo-document-picker";
import { apiRequest, getApiUrl } from "@/lib/query-client";
import Colors from "@/constants/colors";
import { useT } from "@/lib/language-context";
import { StepCard, StepStatus } from "@/components/admin/traduzioni/StepCard";
import { LangCheckbox } from "@/components/admin/traduzioni/LangCheckbox";
import { TranslationFilters } from "@/components/admin/traduzioni/TranslationFilters";
import { TranslationTable } from "@/components/admin/traduzioni/TranslationTable";
import { CellState } from "@/components/admin/traduzioni/TranslationRow";

import { AiSection } from "@/components/admin/traduzioni/AiSection";
import { ExportSection } from "@/components/admin/traduzioni/ExportSection";
import { ImportSection } from "@/components/admin/traduzioni/ImportSection";
import { InfoBanner } from "@/components/admin/traduzioni/InfoBanner";
import { PrepareSection } from "@/components/admin/traduzioni/PrepareSection";
import { RestartSection } from "@/components/admin/traduzioni/RestartSection";
import { LiveTableSection } from "@/components/admin/traduzioni/LiveTableSection";
import { traduzioniStyles as styles } from "@/components/admin/traduzioni/styles";

const LANGS = [
  { code: "en", label: "EN — Inglese" },
  { code: "de", label: "DE — Tedesco" },
  { code: "es", label: "ES — Spagnolo" },
  { code: "fr", label: "FR — Francese" },
  { code: "el", label: "EL — Greco" },
  { code: "tr", label: "TR — Turco" },
];

const TABLE_LANGS = [
  { code: "en", label: "EN" },
  { code: "de", label: "DE" },
  { code: "es", label: "ES" },
  { code: "fr", label: "FR" },
  { code: "el", label: "EL" },
  { code: "tr", label: "TR" },
];

type TableRow = {
  key: string;
  position: string;
  it: string;
  [key: string]: string;
};

const COL_POSITION = 220;
const COL_IT = 180;
const COL_LANG = 170;

export default function TraduzioniScreen() {
  const t = useT();
  const insets = useSafeAreaInsets();

  const [activeLangs, setActiveLangs] = useState<Set<string>>(new Set(["en", "de", "es", "fr", "el", "tr"]));
  const [tableData, setTableData] = useState<TableRow[]>([]);
  const [loadingTable, setLoadingTable] = useState(false);
  const [tableError, setTableError] = useState("");
  const [editingCell, setEditingCell] = useState<{ key: string; lang: string } | null>(null);
  const [editDraft, setEditDraft] = useState("");
  const [cellStates, setCellStates] = useState<Record<string, CellState>>({});
  const [searchText, setSearchText] = useState("");
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [showMissingOnly, setShowMissingOnly] = useState(false);

  const loadTable = useCallback(async () => {
    setLoadingTable(true);
    setTableError("");
    try {
      const url = new URL("/api/admin/translations/table", getApiUrl());
      const resp = await fetch(url.toString(), { credentials: "include" });
      if (!resp.ok) throw new Error(`Errore ${resp.status}`);
      const data: TableRow[] = await resp.json();
      setTableData(data);
    } catch (e: unknown) {
      setTableError(e instanceof Error ? e.message : t("admin.loadError2"));
    } finally {
      setLoadingTable(false);
    }
  }, [t]);

  useEffect(() => {
    loadTable();
  }, [loadTable]);

  const toggleLang = useCallback((code: string) => {
    setActiveLangs((prev) => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code);
      else next.add(code);
      return next;
    });
  }, []);

  const handleStartEdit = useCallback((key: string, lang: string, currentValue: string) => {
    setEditingCell({ key, lang });
    setEditDraft(currentValue);
  }, []);

  const handleSave = useCallback(async (key: string, lang: string, value: string) => {
    const cellKey = `${key}:${lang}`;
    setEditingCell(null);

    if (!value.trim()) return;

    setCellStates((prev) => ({ ...prev, [cellKey]: "saving" }));
    try {
      const resp = await apiRequest("PATCH", "/api/admin/translations/key", { key, lang, value: value.trim() });
      if (!resp.ok) throw new Error(t("admin.saveError"));
      setTableData((prev) =>
        prev.map((row) =>
          row.key === key ? { ...row, [lang]: value.trim() } : row
        )
      );
      setCellStates((prev) => ({ ...prev, [cellKey]: "ok" }));
      setTimeout(() => {
        setCellStates((prev) => {
          const next = { ...prev };
          if (next[cellKey] === "ok") delete next[cellKey];
          return next;
        });
      }, 2500);
    } catch {
      setCellStates((prev) => ({ ...prev, [cellKey]: "error" }));
      setTimeout(() => {
        setCellStates((prev) => {
          const next = { ...prev };
          if (next[cellKey] === "error") delete next[cellKey];
          return next;
        });
      }, 3000);
    }
  }, [t]);

  const categories = useMemo(() => {
    const prefixSet = new Set<string>();
    tableData.forEach((row) => {
      const prefix = row.key.split(/[._]/)[0];
      if (prefix) prefixSet.add(prefix);
    });
    return Array.from(prefixSet).sort();
  }, [tableData]);

  const rowHasMissing = useCallback((row: TableRow) => {
    return TABLE_LANGS.some((l) => !((row[l.code] as string) ?? "").trim());
  }, []);

  const missingCount = useMemo(() => tableData.filter(rowHasMissing).length, [tableData, rowHasMissing]);

  const filteredData = useMemo(() => {
    const q = searchText.trim().toLowerCase();
    return tableData.filter((row) => {
      const matchesCategory = activeCategory ? row.key.startsWith(activeCategory + ".") || row.key.startsWith(activeCategory + "_") || row.key.split(/[._]/)[0] === activeCategory : true;
      if (!matchesCategory) return false;
      if (showMissingOnly && !rowHasMissing(row)) return false;
      if (!q) return true;
      return row.key.toLowerCase().includes(q) || row.it.toLowerCase().includes(q);
    });
  }, [tableData, searchText, activeCategory, showMissingOnly, rowHasMissing]);

  const activeLangList = TABLE_LANGS.filter((l) => activeLangs.has(l.code));
  const totalWidth = COL_POSITION + COL_IT + activeLangList.length * COL_LANG;

  const [prepareStatus, setPrepareStatus] = useState<StepStatus>("idle");
  const [prepareResult, setPrepareResult] = useState("");

  const [exportLangs, setExportLangs] = useState<string[]>(["en", "de", "es", "fr", "el", "tr"]);

  const [restartStatus, setRestartStatus] = useState<StepStatus>("idle");
  const [restartResult, setRestartResult] = useState("");

  const [docxLoading, setDocxLoading] = useState(false);
  const [docxResult, setDocxResult] = useState<{ ok: boolean; msg: string } | null>(null);

  const [importStatus, setImportStatus] = useState<StepStatus>("idle");
  const [importResult, setImportResult] = useState("");
  const [importFileName, setImportFileName] = useState<string>("");
  const webImportInputRef = useRef<any>(null);

  const [aiStatus, setAiStatus] = useState<StepStatus>("idle");
  const [aiResult, setAiResult] = useState("");
  const [aiSummary, setAiSummary] = useState<Record<string, number> | null>(null);

  async function handlePrepare() {
    setPrepareStatus("loading");
    setPrepareResult("");
    try {
      const resp = await apiRequest("POST", "/api/admin/translations/prepare", {});
      const data = await resp.json();
      setPrepareStatus("success");
      const langSummary = data.langCounts
        ? Object.entries(data.langCounts as Record<string, number>)
            .map(([l, n]) => `${l.toUpperCase()}: ${n}`)
            .join(", ")
        : "";
      setPrepareResult(
        `${data.count} stringhe IT` + (langSummary ? ` | Esistenti → ${langSummary}` : "")
      );
    } catch (e: any) {
      setPrepareStatus("error");
      setPrepareResult(e?.message || t("admin.prepareError"));
    }
  }

  function extractErrorMessage(e: unknown, fallback: string): string {
    if (e instanceof Error) return e.message || fallback;
    return fallback;
  }

  async function arrayBufferToBase64(buf: ArrayBuffer): Promise<string> {
    const bytes = new Uint8Array(buf);
    const CHUNK = 8192;
    let binary = "";
    for (let i = 0; i < bytes.length; i += CHUNK) {
      binary += String.fromCharCode(...Array.from(bytes.subarray(i, i + CHUNK)));
    }
    return btoa(binary);
  }

  async function parseBinaryErrorMessage(resp: Response): Promise<string> {
    try {
      const data: unknown = await resp.json();
      if (data && typeof data === "object" && "message" in data && typeof (data as { message: unknown }).message === "string") {
        return (data as { message: string }).message;
      }
    } catch {
      // no-op: return fallback message
    }
    return t("admin.downloadError");
  }

  async function handleDownloadDocx() {
    setDocxLoading(true);
    setDocxResult(null);
    try {
      const langs = exportLangs.length > 0 ? exportLangs : ["en", "de", "es", "fr", "el", "tr"];
      const url = new URL(
        `/api/admin/translations/download-docx?langs=${langs.join(",")}`,
        getApiUrl()
      );
      const resp = await fetch(url.toString(), { credentials: "include" });
      if (!resp.ok) throw new Error(await parseBinaryErrorMessage(resp));
      const arrayBuf = await resp.arrayBuffer();
      const base64 = await arrayBufferToBase64(arrayBuf);
      const filePath = `${FileSystem.cacheDirectory}BikerLink_Traduzioni.docx`;
      await FileSystem.writeAsStringAsync(filePath, base64, { encoding: "base64" });
      const canShare = await Sharing.isAvailableAsync();
      if (canShare) {
        await Sharing.shareAsync(filePath, {
          mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          dialogTitle: t("admin.saveWord"),
        });
        setDocxResult({ ok: true, msg: "File Word pronto da condividere" });
      } else {
        setDocxResult({ ok: false, msg: t("admin.sharingUnavailable") });
      }
    } catch (e: unknown) {
      setDocxResult({ ok: false, msg: extractErrorMessage(e, t("admin.wordDownloadError")) });
    } finally {
      setDocxLoading(false);
    }
  }

  async function handleRestart() {
    setRestartStatus("loading");
    setRestartResult("");
    try {
      await apiRequest("POST", "/api/admin/translations/restart", {});
      setRestartStatus("success");
      setRestartResult("Backend in riavvio...");
    } catch (e: any) {
      const msg: string = e?.message ?? "";
      const isConnectionDrop =
        msg.includes("Network request failed") ||
        msg.includes("Failed to fetch") ||
        msg.includes("NetworkError") ||
        msg.includes("503") ||
        msg.includes("502");
      if (isConnectionDrop) {
        setRestartStatus("success");
        setRestartResult("Backend in riavvio (connessione chiusa dal server)...");
      } else {
        setRestartStatus("error");
        setRestartResult(msg || t("admin.restartError"));
      }
    }
  }

  function toggleExportLang(code: string) {
    setExportLangs((prev) =>
      prev.includes(code) ? prev.filter((l) => l !== code) : [...prev, code]
    );
  }

  const DOCX_MIME =
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

  function base64ToArrayBuffer(base64: string): ArrayBuffer {
    const cleaned = base64.replace(/[^A-Za-z0-9+/=]/g, "");
    if (typeof globalThis.atob === "function") {
      const binary = globalThis.atob(cleaned);
      const len = binary.length;
      const buffer = new ArrayBuffer(len);
      const view = new Uint8Array(buffer);
      for (let i = 0; i < len; i++) view[i] = binary.charCodeAt(i);
      return buffer;
    }
    const BufferImpl = (globalThis as { Buffer?: { from: (s: string, e: string) => Uint8Array } })
      .Buffer;
    if (BufferImpl) {
      const buf = BufferImpl.from(cleaned, "base64");
      const out = new ArrayBuffer(buf.byteLength);
      new Uint8Array(out).set(buf);
      return out;
    }
    throw new Error("Decodifica base64 non disponibile in questo runtime");
  }

  async function uploadDocxFile(formData: FormData): Promise<void> {
    type ImportResponse = {
      ok?: boolean;
      langCounts?: Record<string, number>;
      message?: string;
    };
    const url = new URL("/api/admin/translations/import-docx", getApiUrl());
    const resp = await fetch(url.toString(), {
      method: "POST",
      credentials: "include",
      body: formData,
    });
    let payload: ImportResponse | null = null;
    try {
      const parsed: unknown = await resp.json();
      if (parsed && typeof parsed === "object") {
        payload = parsed as ImportResponse;
      }
    } catch {
      // no-op: payload stays null
    }
    if (!resp.ok || !payload?.ok) {
      const errMsg =
        (payload && typeof payload.message === "string" && payload.message) ||
        `Errore HTTP ${resp.status}`;
      throw new Error(errMsg);
    }
    const summary = payload.langCounts
      ? Object.entries(payload.langCounts)
          .map(([l, n]) => `${l.toUpperCase()}: ${n}`)
          .join(", ")
      : "";
    setImportStatus("success");
    setImportResult(
      summary ? `Stringhe aggiornate → ${summary}` : payload.message || "Import completato"
    );
  }

  async function handleWebFileSelected(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    setImportFileName(file.name);
    setImportStatus("loading");
    setImportResult("");
    try {
      const fd = new FormData();
      fd.append("file", file, file.name);
      await uploadDocxFile(fd);
    } catch (err: unknown) {
      setImportStatus("error");
      setImportResult(extractErrorMessage(err, t("admin.importError")));
    } finally {
      if (webImportInputRef.current) webImportInputRef.current.value = "";
    }
  }

  async function handlePickAndImportNative() {
    setImportStatus("loading");
    setImportResult("");
    try {
      const picked = await DocumentPicker.getDocumentAsync({
        type: [DOCX_MIME, "application/octet-stream", "*/*"],
        multiple: false,
        copyToCacheDirectory: true,
      });
      if (picked.canceled || !picked.assets || picked.assets.length === 0) {
        setImportStatus("idle");
        return;
      }
      const asset = picked.assets[0];
      const fileName = asset.name || "translations.docx";
      if (!/\.docx$/i.test(fileName)) {
        throw new Error(t("admin.selectDocxFile"));
      }
      setImportFileName(fileName);

      const base64 = await FileSystem.readAsStringAsync(asset.uri, {
        encoding: FileSystem.EncodingType.Base64,
      });
      const arrayBuffer = base64ToArrayBuffer(base64);
      const blob = new Blob([arrayBuffer], { type: DOCX_MIME });

      const fd = new FormData();
      fd.append("file", blob, fileName);
      await uploadDocxFile(fd);
    } catch (err: unknown) {
      setImportStatus("error");
      setImportResult(extractErrorMessage(err, t("admin.importError")));
    }
  }

  function handleImportPress() {
    if (importStatus === "loading") return;
    handlePickAndImportNative();
  }

  async function handleAiComplete() {
    setAiStatus("loading");
    setAiResult("");
    setAiSummary(null);
    try {
      const resp = await apiRequest("POST", "/api/admin/translations/ai-complete", {});
      const data = await resp.json();
      if (!resp.ok) throw new Error(data?.message || "Errore AI");
      setAiStatus("success");
      setAiResult(data.message || "Completamento AI riuscito");
      if (data.summary) setAiSummary(data.summary as Record<string, number>);
    } catch (e: any) {
      setAiStatus("error");
      setAiResult(e?.message || "Errore durante il completamento AI");
    }
  }

  return (
    <ScrollView
      style={styles.container}
      contentContainerStyle={[
        styles.content,
        { paddingBottom: insets.bottom + 24, paddingTop: 0 },
      ]}
    >
      <Text style={styles.pageDesc}>
        Esporta tutte le stringhe dell'app in Word, falle tradurre esternamente, poi importa il file
        tradotto direttamente da qui e riavvia il backend.
      </Text>

      <PrepareSection
        prepareStatus={prepareStatus}
        prepareResult={prepareResult}
        onPrepare={handlePrepare}
        t={t}
      />

      <ExportSection
        exportLangs={exportLangs}
        toggleExportLang={toggleExportLang}
        docxLoading={docxLoading}
        onDownload={handleDownloadDocx}
        docxResult={docxResult}
        t={t}
      />

      <ImportSection
        importStatus={importStatus}
        importFileName={importFileName}
        importResult={importResult}
        onImportPress={handleImportPress}
        t={t}
      />

      <AiSection
        aiStatus={aiStatus}
        handleAiComplete={handleAiComplete}
        aiResult={aiResult}
        aiSummary={aiSummary}
      />

      <RestartSection
        restartStatus={restartStatus}
        restartResult={restartResult}
        onRestart={handleRestart}
        t={t}
      />

      {restartStatus === "success" ? <InfoBanner /> : null}

      <LiveTableSection
        restartStatus={restartStatus}
        restartResult={restartResult}
        onRestartPress={handleRestart}
        activeLangs={activeLangs}
        toggleLang={toggleLang}
        searchText={searchText}
        setSearchText={setSearchText}
        categories={categories}
        activeCategory={activeCategory}
        setActiveCategory={setActiveCategory}
        showMissingOnly={showMissingOnly}
        setShowMissingOnly={setShowMissingOnly}
        missingCount={missingCount}
        filteredData={filteredData}
        tableData={tableData}
        loadingTable={loadingTable}
        loadTable={loadTable}
        tableError={tableError}
        editingCell={editingCell}
        editDraft={editDraft}
        cellStates={cellStates}
        rowHasMissing={rowHasMissing}
        handleSave={handleSave}
        handleStartEdit={handleStartEdit}
        setEditDraft={setEditDraft}
        activeLangList={activeLangList}
        totalWidth={totalWidth}
        COL_POSITION={COL_POSITION}
        COL_IT={COL_IT}
        COL_LANG={COL_LANG}
        t={t}
      />
    </ScrollView>
  );
}

import React, { useState, useEffect } from "react";
import { View, Text, StyleSheet, FlatList, Alert } from "react-native";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import Colors from "@/constants/colors";
import { apiRequest, queryClient, getApiUrl } from "@/lib/query-client";
import { useT } from "@/lib/language-context";

// Local components
import { AdminUser, UserCard } from "@/components/admin/users/UserCard";
import { UserFilters } from "@/components/admin/users/UserFilters";
import { UserSummary } from "@/components/admin/users/UserSummary";
import { UserDetailModal, UserStats, SessionsData, GeoZone } from "@/components/admin/users/UserDetailModal";
import { UserEditModal } from "@/components/admin/users/UserEditModal";
import { ZoneMapModal } from "@/components/admin/users/ZoneMapModal";

let MapView: React.ComponentType<Record<string, unknown>> | null = null;
let MapMarker: React.ComponentType<Record<string, unknown>> | null = null;
try {
  const maps = require("react-native-maps");
  MapView = maps.default as React.ComponentType<Record<string, unknown>>;
  MapMarker = maps.Marker as React.ComponentType<Record<string, unknown>>;
} catch {
  MapView = null;
  MapMarker = null;
}

const CURRENT_APP_VERSION = "1.0.0"; // Should be imported if available elsewhere

function formatDateIT(dateStr: string | null): string {
  if (!dateStr) return "Mai";
  const d = new Date(dateStr);
  return d.toLocaleDateString("it-IT", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

export default function AdminUsers() {
  const t = useT();
  const insets = useSafeAreaInsets();

  const [editModalVisible, setEditModalVisible] = useState(false);
  const [statsModalVisible, setStatsModalVisible] = useState(false);
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [editEmail, setEditEmail] = useState("");
  const [editPassword, setEditPassword] = useState("");
  const [searchText, setSearchText] = useState("");
  const [hideFake, setHideFake] = useState(true);

  // Geo-insight effimero
  const [fzEnabled, setFzEnabled] = useState(false);
  const [fzMapZone, setFzMapZone] = useState<GeoZone | null>(null);
  const [fzData, setFzData] = useState<GeoZone[]>([]);
  const [fzLoading, setFzLoading] = useState(false);
  const [fzError, setFzError] = useState(false);

  // Reset totale quando la scheda utente viene chiusa (dati ephemeri).
  useEffect(() => {
    if (!statsModalVisible) {
      setFzEnabled(false);
      setFzMapZone(null);
      setFzData([]);
      setFzLoading(false);
      setFzError(false);
    }
  }, [statsModalVisible]);

  // Quando il toggle viene attivato → fetch on-demand.
  useEffect(() => {
    if (!fzEnabled || !selectedUser) {
      setFzData([]);
      setFzLoading(false);
      setFzError(false);
      return;
    }
    let cancelled = false;
    setFzLoading(true);
    setFzError(false);
    (async () => {
      try {
        const url = new URL(`/api/admin/users/${selectedUser.id}/geo-insights`, getApiUrl());
        const res = await fetch(url.toString(), { credentials: "include" });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const json = (await res.json()) as GeoZone[];
        if (!cancelled) {
          setFzData(Array.isArray(json) ? json : []);
          setFzLoading(false);
        }
      } catch {
        if (!cancelled) {
          setFzError(true);
          setFzLoading(false);
          setFzData([]);
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [fzEnabled, selectedUser]);

  const { data: users = [], isLoading } = useQuery<AdminUser[]>({
    queryKey: ["/api/admin/users"],
  });

  const { data: summary } = useQuery<any>({
    queryKey: ["/api/admin/users/stats/summary"],
  });

  const statsQuery = useQuery<UserStats>({
    queryKey: ["/api/admin/users", selectedUser?.id, "stats"],
    enabled: statsModalVisible && !!selectedUser,
    queryFn: async () => {
      const url = new URL(`/api/admin/users/${selectedUser!.id}/stats`, getApiUrl());
      const res = await fetch(url.toString(), { credentials: "include" });
      if (!res.ok) throw new Error("Failed to fetch stats");
      return res.json();
    },
  });

  const statusMutation = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: string }) => {
      const res = await apiRequest("PUT", `/api/admin/users/${id}/status`, { status });
      return res.json();
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] }),
  });

  const roleMutation = useMutation({
    mutationFn: async ({ id, role }: { id: string; role: string }) => {
      const res = await apiRequest("PUT", `/api/admin/users/${id}/role`, { role });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users/stats/summary"] });
    },
  });

  const emailMutation = useMutation({
    mutationFn: async ({ id, email }: { id: string; email: string }) => {
      const res = await apiRequest("PUT", `/api/admin/users/${id}/email`, { email });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
      Alert.alert("Successo", "Email aggiornata");
    },
    onError: () => Alert.alert("Errore", "Impossibile aggiornare l'email"),
  });

  const passwordMutation = useMutation({
    mutationFn: async ({ id, password }: { id: string; password: string }) => {
      const res = await apiRequest("PUT", `/api/admin/users/${id}/password`, { password });
      return res.json();
    },
    onSuccess: () => {
      Alert.alert("Successo", "Password aggiornata");
      setEditPassword("");
    },
    onError: () => Alert.alert("Errore", "Impossibile aggiornare la password"),
  });

  const deleteMutation = useMutation({
    mutationFn: async ({ id }: { id: string }) => {
      const res = await apiRequest("DELETE", `/api/admin/users/${id}`);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users/stats/summary"] });
      Alert.alert("Successo", "Profilo eliminato");
    },
    onError: () => Alert.alert("Errore", "Impossibile eliminare il profilo"),
  });

  const primalMutation = useMutation({
    mutationFn: async ({ id, isPrimal }: { id: string; isPrimal: boolean }) => {
      const res = await apiRequest("PUT", `/api/admin/users/${id}/primal`, { isPrimal });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
    },
    onError: () => Alert.alert("Errore", "Impossibile aggiornare stato Primal"),
  });

  const clearLastfmMutation = useMutation({
    mutationFn: async ({ id }: { id: string }) => {
      const res = await apiRequest("DELETE", `/api/admin/users/${id}/lastfm`);
      return res.json() as Promise<{ message: string; deleted: { tracks: number; sessions: number; snapshots: number } }>;
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
      const { tracks, sessions, snapshots } = data.deleted;
      Alert.alert("Last.fm cancellato", `Rimossi: ${tracks} brani, ${sessions} sessioni, ${snapshots} snapshot`);
    },
    onError: () => Alert.alert("Errore", "Impossibile cancellare i dati Last.fm"),
  });

  const sessionsQuery = useQuery<SessionsData>({
    queryKey: ["/api/admin/users", selectedUser?.id, "sessions"],
    enabled: statsModalVisible && !!selectedUser,
    queryFn: async () => {
      const url = new URL(`/api/admin/users/${selectedUser!.id}/sessions`, getApiUrl());
      const res = await fetch(url.toString(), { credentials: "include" });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    },
  });

  const revokeSessionMutation = useMutation({
    mutationFn: async ({ userId, sid }: { userId: string; sid: string }) => {
      const cleanSid = sid.startsWith("…") ? sid.slice(1) : sid;
      const res = await apiRequest("DELETE", `/api/admin/users/${userId}/sessions/${encodeURIComponent(cleanSid)}`);
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error((body as { message?: string }).message ?? `HTTP ${res.status}`);
      }
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users", selectedUser?.id, "sessions"] });
    },
    onError: (err: Error) => Alert.alert("Errore revoca", err.message || "Impossibile revocare la sessione"),
  });

  const filteredUsers = users.filter((u) => {
    if (hideFake && u.isFake === true) return false;
    if (!searchText) return true;
    const q = searchText.toLowerCase();
    return u.nickname.toLowerCase().includes(q) || u.email.toLowerCase().includes(q) || (u.phone?.toLowerCase().includes(q) ?? false);
  });

  function openEditModal(user: AdminUser) {
    setSelectedUser(user);
    setEditEmail(user.email);
    setEditPassword("");
    setEditModalVisible(true);
  }

  function openStatsModal(user: AdminUser) {
    setSelectedUser(user);
    setStatsModalVisible(true);
  }

  function handleSaveEmail() {
    if (!selectedUser) return;
    if (!editEmail || !editEmail.includes("@")) {
      Alert.alert(t("common.error"), t("admin.emailRequired"));
      return;
    }
    emailMutation.mutate({ id: selectedUser.id, email: editEmail });
  }

  function handleSavePassword() {
    if (!selectedUser) return;
    if (!editPassword || editPassword.length < 6) {
      Alert.alert("Errore", "La password deve avere almeno 6 caratteri");
      return;
    }
    passwordMutation.mutate({ id: selectedUser.id, password: editPassword });
  }

  function handleStatusChange(user: AdminUser) {
    const options = ["active", "suspended", "blocked"].filter((s) => s !== user.status);
    Alert.alert("Cambia stato", `Utente: ${user.nickname}`, [
      ...options.map((status) => ({
        text: status.charAt(0).toUpperCase() + status.slice(1),
        onPress: () => statusMutation.mutate({ id: user.id, status }),
      })),
      { text: t("common.cancel"), style: "cancel" as const },
    ]);
  }

  function handleMakeModerator(user: AdminUser) {
    Alert.alert(
      "Rendi Moderatore",
      `Vuoi rendere ${user.nickname} un moderatore?`,
      [
        { text: t("common.cancel"), style: "cancel" as const },
        {
          text: t("common.confirm"),
          onPress: () => roleMutation.mutate({ id: user.id, role: "moderator" }),
        },
      ]
    );
  }

  function handleDeleteUser(user: AdminUser) {
    Alert.alert(
      t("admin.deleteProfile"),
      `Sei sicuro di voler eliminare il profilo di ${user.nickname}?`,
      [
        { text: t("common.cancel"), style: "cancel" as const },
        {
          text: t("admin.deleteUser"),
          style: "destructive" as const,
          onPress: () => {
            Alert.alert(
              t("admin.confirmDelete"),
              t("admin.irreversibleAction"),
              [
                { text: t("common.cancel"), style: "cancel" as const },
                {
                  text: t("admin.deleteDefinitely"),
                  style: "destructive" as const,
                  onPress: () => deleteMutation.mutate({ id: user.id }),
                },
              ]
            );
          },
        },
      ]
    );
  }

  function handleClearLastfm(user: AdminUser) {
    Alert.alert(
      "Clear Last.fm",
      `Cancellare tutti i dati Last.fm di ${user.nickname}? (brani, sessione, snapshot)`,
      [
        { text: t("common.cancel"), style: "cancel" as const },
        {
          text: "Cancella",
          style: "destructive" as const,
          onPress: () => clearLastfmMutation.mutate({ id: user.id }),
        },
      ]
    );
  }

  function getStatusColor(status: string) {
    switch (status) {
      case "active": return Colors.success;
      case "suspended": return Colors.warning;
      case "blocked": return Colors.error;
      default: return Colors.textSecondary;
    }
  }

  function getRoleColor(role: string) {
    switch (role) {
      case "admin": return Colors.accent;
      case "moderator": return Colors.maleIcon;
      default: return Colors.textSecondary;
    }
  }

  return (
    <View style={styles.container}>
      <FlatList
        data={filteredUsers}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <UserCard
            item={item}
            onOpenStats={openStatsModal}
            onOpenEdit={openEditModal}
            onStatusChange={handleStatusChange}
            onMakeModerator={handleMakeModerator}
            onClearLastfm={handleClearLastfm}
            onDeleteUser={handleDeleteUser}
            onTogglePrimal={(id, isPrimal) => primalMutation.mutate({ id, isPrimal })}
            isLastfmPending={clearLastfmMutation.isPending}
            currentAppVersion={CURRENT_APP_VERSION}
          />
        )}
        ListHeaderComponent={
          <>
            <UserSummary summary={summary} />
            <UserFilters
              searchText={searchText}
              onSearchChange={setSearchText}
              hideFake={hideFake}
              onToggleHideFake={() => setHideFake(!hideFake)}
              t={t}
            />
          </>
        }
        contentContainerStyle={{ padding: 16, paddingTop: 0 }}
        ListEmptyComponent={
          <Text style={styles.emptyText}>
            {isLoading ? "Caricamento utenti..." : "Nessun utente trovato"}
          </Text>
        }
      />

      <UserDetailModal
        visible={statsModalVisible}
        onClose={() => setStatsModalVisible(false)}
        user={selectedUser}
        stats={statsQuery.data}
        isLoadingStats={statsQuery.isLoading}
        fzEnabled={fzEnabled}
        setFzEnabled={setFzEnabled}
        fzData={fzData}
        fzLoading={fzLoading}
        fzError={fzError}
        onZonePress={setFzMapZone}
        sessions={sessionsQuery.data}
        onRevokeSession={(sid) => selectedUser && revokeSessionMutation.mutate({ userId: selectedUser.id, sid })}
        t={t}
        formatDateIT={formatDateIT}
        getRoleColor={getRoleColor}
        getStatusColor={getStatusColor}
      />

      <UserEditModal
        visible={editModalVisible}
        onClose={() => setEditModalVisible(false)}
        user={selectedUser}
        editEmail={editEmail}
        setEditEmail={setEditEmail}
        editPassword={editPassword}
        setEditPassword={setEditPassword}
        onSaveEmail={handleSaveEmail}
        onSavePassword={handleSavePassword}
        onStatusChange={handleStatusChange}
        onMakeModerator={handleMakeModerator}
        onDeleteUser={handleDeleteUser}
        getStatusColor={getStatusColor}
      />

      <ZoneMapModal
        zone={fzMapZone}
        onClose={() => setFzMapZone(null)}
        MapView={MapView}
        MapMarker={MapMarker}
        insets={insets}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: Colors.background },
  emptyText: { fontFamily: "Inter_400Regular", fontSize: 14, color: Colors.textSecondary, textAlign: "center", marginTop: 40 },
});

import React, { useState } from "react";
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, ActivityIndicator, FlatList, Switch } from "react-native";
import { useQuery } from "@tanstack/react-query";
import { MaterialCommunityIcons, Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import Colors from "@/constants/colors";
import { getApiUrl } from "@/lib/query-client";

type Summary = {
  views: { today: number; last7d: number; last30d: number; total: number };
  uniqueVisitors: { today: number; last7d: number; last30d: number; total: number };
  registrations: { last30d: number; total: number };
  logins: { last30d: number; total: number };
  generatedAt: string;
};

type Visit = {
  id: string;
  visitorId: string;
  userId: string | null;
  userNickname: string | null;
  event: "view" | "register" | "login";
  path: string;
  referrer: string | null;
  userAgent: string | null;
  ipPrefix: string | null;
  lang: string | null;
  country: string | null;
  createdAt: string;
};

type VisitsResponse = { total: number; limit: number; offset: number; visits: Visit[] };

const PAGE_SIZE = 50;

function fmtDate(iso: string): string {
  try {
    return new Date(iso).toLocaleString("it-IT", {
      day: "2-digit", month: "2-digit", year: "2-digit", hour: "2-digit", minute: "2-digit",
    });
  } catch {
    return iso;
  }
}

function eventColor(ev: string): string {
  if (ev === "register") return "#22C55E";
  if (ev === "login") return "#3b82f6";
  return Colors.textSecondary;
}

export default function VisitatoriAdminScreen() {
  const insets = useSafeAreaInsets();
  const [page, setPage] = useState(0);
  const [eventFilter, setEventFilter] = useState<"" | "view" | "register" | "login">("");
  const [loggedOnly, setLoggedOnly] = useState(false);

  const summaryQ = useQuery<Summary>({
    queryKey: ["/api/admin/site-visits/summary"],
    queryFn: async () => {
      const res = await fetch(new URL("/api/admin/site-visits/summary", getApiUrl()).toString(), {
        credentials: "include",
      });
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    },
  });

  const visitsQ = useQuery<VisitsResponse>({
    queryKey: ["/api/admin/site-visits", page, eventFilter, loggedOnly],
    queryFn: async () => {
      const url = new URL("/api/admin/site-visits", getApiUrl());
      url.searchParams.set("limit", String(PAGE_SIZE));
      url.searchParams.set("offset", String(page * PAGE_SIZE));
      if (eventFilter) url.searchParams.set("event", eventFilter);
      if (loggedOnly) url.searchParams.set("loggedOnly", "1");
      const res = await fetch(url.toString(), { credentials: "include" });
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    },
  });

  const total = visitsQ.data?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  function StatCard({ value, label, sub }: { value: string | number; label: string; sub?: string }) {
    return (
      <View style={styles.statCard}>
        <Text style={styles.statValue}>{String(value)}</Text>
        <Text style={styles.statLabel}>{label}</Text>
        {sub ? <Text style={styles.statSub}>{sub}</Text> : null}
      </View>
    );
  }

  function FilterChip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) {
    return (
      <TouchableOpacity onPress={onPress} style={[styles.chip, active && styles.chipActive]}>
        <Text style={[styles.chipText, active && styles.chipTextActive]}>{label}</Text>
      </TouchableOpacity>
    );
  }

  function renderVisit({ item }: { item: Visit }) {
    return (
      <View style={styles.row}>
        <View style={styles.rowHead}>
          <View style={[styles.evtBadge, { backgroundColor: eventColor(item.event) + "33", borderColor: eventColor(item.event) }]}>
            <Text style={[styles.evtBadgeText, { color: eventColor(item.event) }]}>{item.event.toUpperCase()}</Text>
          </View>
          <Text style={styles.rowDate}>{fmtDate(item.createdAt)}</Text>
        </View>
        <Text style={styles.rowPath} numberOfLines={1}>{item.path}</Text>
        <View style={styles.rowMeta}>
          {item.userNickname ? (
            <Text style={styles.metaUser}>
              <Ionicons name="person" size={11} color={Colors.accent} /> {item.userNickname}
            </Text>
          ) : (
            <Text style={styles.metaAnon}>anonimo</Text>
          )}
          {item.country ? <Text style={styles.metaText}>🌐 {item.country}</Text> : null}
          {item.lang ? <Text style={styles.metaText}>{item.lang}</Text> : null}
          {item.ipPrefix ? <Text style={styles.metaText}>IP {item.ipPrefix}</Text> : null}
        </View>
        {item.referrer ? <Text style={styles.metaRef} numberOfLines={1}>← {item.referrer}</Text> : null}
        {item.userAgent ? <Text style={styles.metaUa} numberOfLines={1}>{item.userAgent}</Text> : null}
      </View>
    );
  }

  function ListHeader() {
    return (
      <View>
        <View style={styles.statsGrid}>
          {summaryQ.isLoading ? (
            <ActivityIndicator color={Colors.accent} style={{ margin: 24 }} />
          ) : summaryQ.data ? (
            <>
              <StatCard value={summaryQ.data.views.today} label="Visite oggi" sub={`${summaryQ.data.uniqueVisitors.today} unici`} />
              <StatCard value={summaryQ.data.views.last7d} label="Ultimi 7gg" sub={`${summaryQ.data.uniqueVisitors.last7d} unici`} />
              <StatCard value={summaryQ.data.views.last30d} label="Ultimi 30gg" sub={`${summaryQ.data.uniqueVisitors.last30d} unici`} />
              <StatCard value={summaryQ.data.views.total} label="Totale" sub={`${summaryQ.data.uniqueVisitors.total} unici`} />
              <StatCard value={summaryQ.data.registrations.last30d} label="Reg. 30gg" sub={`Tot: ${summaryQ.data.registrations.total}`} />
              <StatCard value={summaryQ.data.logins.last30d} label="Login 30gg" sub={`Tot: ${summaryQ.data.logins.total}`} />
            </>
          ) : (
            <Text style={styles.errorText}>Errore caricamento riepilogo</Text>
          )}
        </View>

        <Text style={styles.sectionTitle}>Filtri</Text>
        <View style={styles.filtersRow}>
          <FilterChip label="Tutti" active={eventFilter === ""} onPress={() => { setEventFilter(""); setPage(0); }} />
          <FilterChip label="Visite" active={eventFilter === "view"} onPress={() => { setEventFilter("view"); setPage(0); }} />
          <FilterChip label="Registrazioni" active={eventFilter === "register"} onPress={() => { setEventFilter("register"); setPage(0); }} />
          <FilterChip label="Login" active={eventFilter === "login"} onPress={() => { setEventFilter("login"); setPage(0); }} />
        </View>
        <View style={styles.switchRow}>
          <Text style={styles.switchLabel}>Solo utenti loggati</Text>
          <Switch
            value={loggedOnly}
            onValueChange={(v) => { setLoggedOnly(v); setPage(0); }}
            trackColor={{ false: Colors.surface, true: Colors.accent }}
            thumbColor="#fff"
          />
        </View>

        <View style={styles.listHeader}>
          <Text style={styles.sectionTitle}>Ultime visite ({total})</Text>
        </View>
      </View>
    );
  }

  function ListFooter() {
    if (visitsQ.isLoading) return <ActivityIndicator color={Colors.accent} style={{ margin: 24 }} />;
    return (
      <View style={[styles.pager, { paddingBottom: insets.bottom + 24 }]}>
        <TouchableOpacity
          onPress={() => setPage(Math.max(0, page - 1))}
          disabled={page === 0}
          style={[styles.pagerBtn, page === 0 && styles.pagerBtnDisabled]}
        >
          <MaterialCommunityIcons name="chevron-left" size={20} color={Colors.text} />
          <Text style={styles.pagerBtnText}>Prev</Text>
        </TouchableOpacity>
        <Text style={styles.pagerInfo}>Pagina {page + 1} / {totalPages}</Text>
        <TouchableOpacity
          onPress={() => setPage(Math.min(totalPages - 1, page + 1))}
          disabled={page + 1 >= totalPages}
          style={[styles.pagerBtn, (page + 1 >= totalPages) && styles.pagerBtnDisabled]}
        >
          <Text style={styles.pagerBtnText}>Next</Text>
          <MaterialCommunityIcons name="chevron-right" size={20} color={Colors.text} />
        </TouchableOpacity>
      </View>
    );
  }

  return (
    <FlatList
      style={styles.container}
      data={visitsQ.data?.visits ?? []}
      keyExtractor={(item) => item.id}
      renderItem={renderVisit}
      ListHeaderComponent={ListHeader}
      ListFooterComponent={ListFooter}
      ListEmptyComponent={!visitsQ.isLoading ? (
        <Text style={styles.empty}>Nessuna visita trovata.</Text>
      ) : null}
      contentContainerStyle={{ padding: 16 }}
    />
  );
}

