    justifyContent: "center",
    gap: 6,
    backgroundColor: Colors.surface,
    borderRadius: 12,
    paddingVertical: 14,
    borderWidth: 1,
    borderColor: Colors.accent + "44",
    marginBottom: 10,
  },
  toggleBtnText: { fontFamily: "Inter_600SemiBold", fontSize: 14, color: Colors.accent },
});

import React, { useState, useCallback, useRef } from "react";
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  TextInput,
  ScrollView,
  ActivityIndicator,

  Alert,
  FlatList,
} from "react-native";
import { useRouter } from "expo-router";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import * as Location from "expo-location";
import Colors from "@/constants/colors";
import { getApiUrl, apiRequest } from "@/lib/query-client";
import LeafletPickerMap from "@/components/LeafletPickerMap";
import { t } from "@/lib/i18n";

type Club = { id: string; name: string; clubType: string };
type UserResult = { id: string; nickname: string; userType: string };

const STEPS = ["Tipo", "Posizione", "Inviti", "Riepilogo"];

export default function CreateMotoclub() {
  const router = useRouter();
  const insets = useSafeAreaInsets();

  const [step, setStep] = useState(0);
  const [clubName, setClubName] = useState("");
  const [parentType, setParentType] = useState<"main" | "sub">("main");
  const [parentClubId, setParentClubId] = useState<string | null>(null);
  const [parentClubName, setParentClubName] = useState<string>("");

  const [mapRegion, setMapRegion] = useState({
    latitude: 45.4642,
    longitude: 9.19,
    latitudeDelta: 5,
    longitudeDelta: 5,
  });
  const [pin, setPin] = useState<{ latitude: number; longitude: number } | null>(null);
  const [loadingLocation, setLoadingLocation] = useState(false);

  const [useRadius, setUseRadius] = useState(false);
  const [radiusKm, setRadiusKm] = useState("25");
  const [useManual, setUseManual] = useState(false);
  const [userSearch, setUserSearch] = useState("");
  const [selectedUsers, setSelectedUsers] = useState<UserResult[]>([]);
  const [searchFocused, setSearchFocused] = useState(false);

  const [submitted, setSubmitted] = useState(false);

  const searchTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [debouncedSearch, setDebouncedSearch] = useState("");

  const { data: clubs = [] } = useQuery<Club[]>({
    queryKey: ["/api/motoclubs"],
  });

  const { data: searchResults = [] } = useQuery<UserResult[]>({
    queryKey: [`/api/users/search?q=${encodeURIComponent(debouncedSearch)}`],
    enabled: debouncedSearch.length >= 2,
  });

  const handleSearchChange = useCallback((text: string) => {
    setUserSearch(text);
    if (searchTimeout.current) clearTimeout(searchTimeout.current);
    searchTimeout.current = setTimeout(() => setDebouncedSearch(text), 400);
  }, []);

  const handleGetLocation = async () => {
    setLoadingLocation(true);
    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== "granted") {
        Alert.alert("Permesso negato", "Abilita la localizzazione nelle impostazioni");
        return;
      }
      const loc = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced });
      const { latitude, longitude } = loc.coords;
      setPin({ latitude, longitude });
      setMapRegion({ latitude, longitude, latitudeDelta: 0.5, longitudeDelta: 0.5 });
    } catch {
      Alert.alert("Errore", "Impossibile ottenere la posizione");
    } finally {
      setLoadingLocation(false);
    }
  };

  const submitMutation = useMutation({
    mutationFn: async () => {
      const baseUrl = getApiUrl();
      const url = new URL("/api/motoclubs/creation-request", baseUrl);
      const body: Record<string, unknown> = {
        name: clubName.trim(),
        parentClubId: parentType === "sub" ? parentClubId : undefined,
        latitude: pin?.latitude,
        longitude: pin?.longitude,
        inviteRadiusKm: useRadius ? parseInt(radiusKm, 10) : undefined,
        inviteUserIds: useManual ? selectedUsers.map((u) => u.id) : undefined,
      };
      const res = await globalThis.fetch(url.toString(), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
        credentials: "include",
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ message: t("motoclub.createError") }));
        throw new Error(err.message);
      }
      return res.json();
    },
    onSuccess: () => setSubmitted(true),
    onError: (e: Error) => Alert.alert("Errore", e.message),
  });

  const canNext = () => {
    if (step === 0) return clubName.trim().length >= 2 && (parentType === "main" || !!parentClubId);
    if (step === 1) return true;
    if (step === 2) return true;
    return false;
  };

  const toggleUser = (u: UserResult) => {
    setSelectedUsers((prev) =>
      prev.find((x) => x.id === u.id) ? prev.filter((x) => x.id !== u.id) : [...prev, u]
    );
  };

  if (submitted) {
    return (
      <View style={[styles.container, { paddingTop: insets.top }]}>
        <View style={styles.successBox}>
          <Ionicons name="checkmark-circle" size={64} color={Colors.success} />
          <Text style={styles.successTitle}>Richiesta inviata!</Text>
          <Text style={styles.successDesc}>
            {t("motoclub.approvalNotif")}
          </Text>
          <TouchableOpacity style={styles.doneBtn} onPress={() => router.back()}>
            <Text style={styles.doneBtnText}>Torna ai Clubs</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  return (
    <View style={[styles.container, { paddingTop: insets.top }]}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => (step === 0 ? router.back() : setStep((s) => s - 1))} style={styles.backBtn}>
          <Ionicons name="chevron-back" size={24} color={Colors.text} />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Nuovo Club</Text>
        <View style={{ width: 40 }} />
      </View>

      <View style={styles.stepsRow}>
        {STEPS.map((label, i) => (
          <View key={i} style={styles.stepItem}>
            <View style={[styles.stepDot, i <= step && styles.stepDotActive]}>
              {i < step ? (
                <Ionicons name="checkmark" size={14} color="#fff" />
              ) : (
                <Text style={[styles.stepNum, i === step && styles.stepNumActive]}>{i + 1}</Text>
              )}
            </View>
            {i < STEPS.length - 1 && <View style={[styles.stepLine, i < step && styles.stepLineActive]} />}
          </View>
        ))}
      </View>
      <Text style={styles.stepLabel}>{STEPS[step]}</Text>

      {step === 0 && (
        <ScrollView style={styles.body} contentContainerStyle={styles.bodyContent}>
          <Text style={styles.fieldLabel}>Tipo di motoclub</Text>
          <TouchableOpacity
            style={[styles.radioRow, parentType === "main" && styles.radioRowSelected]}
            onPress={() => { setParentType("main"); setParentClubId(null); }}
          >
            <View style={[styles.radioCircle, parentType === "main" && styles.radioCircleSelected]}>
              {parentType === "main" && <View style={styles.radioInner} />}
            </View>
            <Text style={styles.radioLabel}>Elenco principale</Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.radioRow, parentType === "sub" && styles.radioRowSelected]}
            onPress={() => setParentType("sub")}
          >
            <View style={[styles.radioCircle, parentType === "sub" && styles.radioCircleSelected]}>
              {parentType === "sub" && <View style={styles.radioInner} />}
            </View>
            <Text style={styles.radioLabel}>Sotto un altro motoclub</Text>
          </TouchableOpacity>

          {parentType === "sub" && (
            <View style={styles.parentPickerBox}>
              <Text style={styles.fieldLabel}>Seleziona motoclub padre</Text>
              <ScrollView style={styles.parentList} nestedScrollEnabled>
                {clubs.filter((c) => c.clubType !== "custom" || c.id !== parentClubId).map((c) => (
                  <TouchableOpacity
                    key={c.id}
                    style={[styles.parentItem, parentClubId === c.id && styles.parentItemSelected]}
                    onPress={() => { setParentClubId(c.id); setParentClubName(c.name); }}
                  >
                    <Text style={[styles.parentItemText, parentClubId === c.id && { color: Colors.accent }]}>
                      {c.name}
                    </Text>
                    {parentClubId === c.id && <Ionicons name="checkmark" size={16} color={Colors.accent} />}
                  </TouchableOpacity>
                ))}
                {clubs.length === 0 && <Text style={styles.emptyText}>Nessun club disponibile</Text>}
              </ScrollView>
            </View>
          )}

          <Text style={[styles.fieldLabel, { marginTop: 20 }]}>Nome del nuovo motoclub</Text>
          <TextInput
            style={styles.textInput}
            value={clubName}
            onChangeText={setClubName}
            placeholder="Es. Bikers Roma Nord"
            placeholderTextColor={Colors.textSecondary}
            maxLength={100}
          />
        </ScrollView>
      )}

      {step === 1 && (
        <View style={styles.body}>
          <Text style={styles.fieldDesc}>
            Tocca la mappa per posizionare il pin del tuo motoclub.
          </Text>
          <View style={styles.map}>
            <LeafletPickerMap
              initialLat={mapRegion.latitude}
              initialLng={mapRegion.longitude}
              initialZoom={6}
              selectedCoord={pin ? { lat: pin.latitude, lng: pin.longitude } : null}
              onCoordPicked={(coord) => setPin(coord)}
            />
          </View>
          <TouchableOpacity style={styles.locationBtn} onPress={handleGetLocation} disabled={loadingLocation}>
            {loadingLocation ? (
              <ActivityIndicator size="small" color={Colors.accent} />
            ) : (
              <Ionicons name="navigate" size={16} color={Colors.accent} />
            )}
            <Text style={styles.locationBtnText}>Usa la mia posizione attuale</Text>
          </TouchableOpacity>
          {pin && (
            <Text style={styles.coordText}>
              Posizione: {pin.latitude.toFixed(4)}, {pin.longitude.toFixed(4)}
            </Text>
          )}
          {!pin && <Text style={styles.noCoordText}>Nessuna posizione selezionata (opzionale)</Text>}
        </View>
      )}

      {step === 2 && (
        <ScrollView style={styles.body} contentContainerStyle={styles.bodyContent}>
          <Text style={styles.sectionTitle}>Inviti automatici</Text>

          <TouchableOpacity style={styles.checkRow} onPress={() => setUseRadius((v) => !v)}>
            <View style={[styles.checkbox, useRadius && styles.checkboxChecked]}>
              {useRadius && <Ionicons name="checkmark" size={14} color="#fff" />}
            </View>
            <Text style={styles.checkLabel}>Per raggio geografico</Text>
          </TouchableOpacity>
          {useRadius && (
            <View style={styles.radiusRow}>
              <Text style={styles.radiusLabel}>Utenti entro</Text>
              <TextInput
                style={styles.radiusInput}
                value={radiusKm}
                onChangeText={setRadiusKm}
                keyboardType="number-pad"
                maxLength={4}
                selectTextOnFocus
              />
              <Text style={styles.radiusLabel}>km dalla posizione del club</Text>
            </View>
          )}

          <TouchableOpacity style={[styles.checkRow, { marginTop: 16 }]} onPress={() => setUseManual((v) => !v)}>
            <View style={[styles.checkbox, useManual && styles.checkboxChecked]}>
              {useManual && <Ionicons name="checkmark" size={14} color="#fff" />}
            </View>
            <Text style={styles.checkLabel}>Selezione manuale per nickname</Text>
          </TouchableOpacity>

          {useManual && (
            <View>
              <TextInput
                style={[styles.textInput, { marginTop: 10 }]}
                value={userSearch}
                onChangeText={handleSearchChange}
                placeholder={t("motoclub.searchNickname")}
                placeholderTextColor={Colors.textSecondary}
                onFocus={() => setSearchFocused(true)}
                onBlur={() => setTimeout(() => setSearchFocused(false), 150)}
              />
              {searchFocused && debouncedSearch.length >= 2 && searchResults.length > 0 && (
                <View style={styles.searchDropdown}>
                  {searchResults.filter((u) => !selectedUsers.find((s) => s.id === u.id)).slice(0, 8).map((u) => (
                    <TouchableOpacity key={u.id} style={styles.searchItem} onPress={() => { toggleUser(u); setUserSearch(""); setDebouncedSearch(""); }}>
                      <Ionicons name="person" size={16} color={Colors.textSecondary} />
                      <Text style={styles.searchItemText}>{u.nickname}</Text>
                      <Ionicons name="add-circle" size={18} color={Colors.accent} />
                    </TouchableOpacity>
                  ))}
                </View>
              )}
              {selectedUsers.length > 0 && (
                <View style={styles.selectedUsersBox}>
                  <Text style={styles.selectedUsersTitle}>Selezionati ({selectedUsers.length})</Text>
                  {selectedUsers.map((u) => (
                    <View key={u.id} style={styles.selectedUserRow}>
                      <Ionicons name="person" size={14} color={Colors.accent} />
                      <Text style={styles.selectedUserName}>{u.nickname}</Text>
                      <TouchableOpacity onPress={() => toggleUser(u)}>
                        <Ionicons name="close-circle" size={18} color={Colors.accentRed} />
                      </TouchableOpacity>
                    </View>
                  ))}
                </View>
              )}
            </View>
          )}

          {!useRadius && !useManual && (
            <Text style={styles.noInviteText}>Nessun invito automatico. Puoi invitare membri in seguito.</Text>
          )}
        </ScrollView>
      )}

      {step === 3 && (
        <ScrollView style={styles.body} contentContainerStyle={styles.bodyContent}>
          <Text style={styles.sectionTitle}>Riepilogo richiesta</Text>

          <View style={styles.summaryCard}>
            <View style={styles.summaryRow}>
              <Ionicons name="people-circle" size={20} color={Colors.accent} />
              <Text style={styles.summaryLabel}>Nome</Text>
              <Text style={styles.summaryValue}>{clubName}</Text>
            </View>
            <View style={styles.summaryRow}>
              <Ionicons name="list" size={20} color={Colors.accent} />
              <Text style={styles.summaryLabel}>Tipo</Text>
              <Text style={styles.summaryValue}>
                {parentType === "main" ? "Elenco principale" : `Sub-club di "${parentClubName}"`}
              </Text>
            </View>
            <View style={styles.summaryRow}>
              <Ionicons name="location" size={20} color={Colors.accent} />
              <Text style={styles.summaryLabel}>Posizione</Text>
              <Text style={styles.summaryValue}>
                {pin ? `${pin.latitude.toFixed(3)}, ${pin.longitude.toFixed(3)}` : "Non impostata"}
              </Text>
            </View>
            {useRadius && (
              <View style={styles.summaryRow}>
                <Ionicons name="radio-button-on" size={20} color={Colors.accent} />
                <Text style={styles.summaryLabel}>Raggio inviti</Text>
                <Text style={styles.summaryValue}>{radiusKm} km</Text>
              </View>
            )}
            {useManual && selectedUsers.length > 0 && (
              <View style={styles.summaryRow}>
                <Ionicons name="people" size={20} color={Colors.accent} />
                <Text style={styles.summaryLabel}>Inviti manuali</Text>
                <Text style={styles.summaryValue}>{selectedUsers.length} utenti</Text>
              </View>
            )}
          </View>

          <Text style={styles.summaryNote}>
            {t("motoclub.requestSentDesc")}
          </Text>

          <TouchableOpacity
            style={[styles.submitBtn, submitMutation.isPending && { opacity: 0.6 }]}
            onPress={() => submitMutation.mutate()}
            disabled={submitMutation.isPending}
          >
            {submitMutation.isPending ? (
              <ActivityIndicator size="small" color="#fff" />
            ) : (
              <>
                <Ionicons name="paper-plane" size={18} color="#fff" />
                <Text style={styles.submitBtnText}>Invia Richiesta</Text>
              </>
            )}
          </TouchableOpacity>
        </ScrollView>
      )}

      {step < 3 && (
        <View style={[styles.footer, { paddingBottom: insets.bottom + 12 }]}>
          <TouchableOpacity
            style={[styles.nextBtn, !canNext() && { opacity: 0.4 }]}
            onPress={() => setStep((s) => s + 1)}
            disabled={!canNext()}
          >
            <Text style={styles.nextBtnText}>
              {step === 2 ? "Vai al Riepilogo" : "Avanti"}
            </Text>
            <Ionicons name="chevron-forward" size={18} color="#fff" />
          </TouchableOpacity>
        </View>
      )}
    </View>
  );
}

