          )}

          {/* Pulsanti */}
          <View style={emailStatusStyles.btnRow}>
            <TouchableOpacity
              style={[emailStatusStyles.btn, emailStatusStyles.btnPrimary, testing && { opacity: 0.6 }]}
              onPress={handleTest}
