export function useCoordHistoryState(isAdmin: boolean, t: (k: string) => string, coordHistoryExpanded: boolean) {
  const { data: coordHistorySettings, refetch: refetchCoordHistory } = useQuery<{
    enabled: boolean; interval: number; maxRecords: number; mode: string; selectedUsers: string[];
  }>({
    queryKey: ["/api/admin/coordinate-history/settings"],
    enabled: isAdmin,
  });
  const { data: coordHistoryStats } = useQuery<{
    totalRecords: number; trackedUsers: number; oldestRecord: string | null; newestRecord: string | null;
  }>({
    queryKey: ["/api/admin/coordinate-history/stats"],
    enabled: isAdmin,
  });
  const [chIntervalInput, setChIntervalInput] = useState("");
  const [chMaxRecordsInput, setChMaxRecordsInput] = useState("");

  useEffect(() => {
    if (coordHistorySettings?.interval != null && chIntervalInput === "") {
      setChIntervalInput(String(coordHistorySettings.interval));
    }
    if (coordHistorySettings?.maxRecords != null && chMaxRecordsInput === "") {
      setChMaxRecordsInput(String(coordHistorySettings.maxRecords));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [coordHistorySettings]);

  const coordHistoryMutation = useMutation({
    mutationFn: async (body: Record<string, any>) => {
      const url = new URL("/api/admin/coordinate-history/settings", getApiUrl());
      const res = await fetch(url.toString(), {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
        credentials: "include",
      });
      if (!res.ok) throw new Error(t("admin.settingsUpdateError"));
      return res.json();
    },
    onSuccess: () => {
      refetchCoordHistory();
      queryClient.invalidateQueries({ queryKey: ["/api/admin/coordinate-history/stats"] });
    },
    onError: (e: Error) => Alert.alert("Errore", e.message),
  });

  const [chUserSearch, setChUserSearch] = useState("");
  const { data: chSearchResults } = useQuery<Array<{ id: string; nickname: string; userType: string }>>({
    queryKey: ["/api/users/search", chUserSearch],
    enabled: coordHistoryExpanded && coordHistorySettings?.mode === "selected" && chUserSearch.length >= 2,
  });

  return {
    coordHistorySettings,
    refetchCoordHistory,
    coordHistoryStats,
    chIntervalInput,
    setChIntervalInput,
    chMaxRecordsInput,
    setChMaxRecordsInput,
    coordHistoryMutation,
    chUserSearch,
    setChUserSearch,
    chSearchResults,
  };
}

import { useQuery, useMutation } from "@tanstack/react-query";
import { useState } from "react";
import { Alert } from "react-native";
import { getApiUrl, queryClient, apiRequest } from "@/lib/query-client";

export function useMatchingState(t: (k: string) => string) {
  const [matchingCountries, setMatchingCountries] = useState<string[]>([]);
  const [matchingTriggerFeedback, setMatchingTriggerFeedback] = useState<string | null>(null);

  const { data: autoMatchData } = useQuery<{ enabled: boolean }>({
    queryKey: ["/api/settings/auto-matching"],
  });
  const autoMatchEnabled = autoMatchData?.enabled !== false;

  const { data: matchPrefVisibleData } = useQuery<{ visible: boolean }>({
    queryKey: ["/api/match-preferences/gate"],
  });
  const matchPrefVisibleEnabled = matchPrefVisibleData?.visible === true;

  const matchPrefVisibleMutation = useMutation({
    mutationFn: async (visible: boolean) => {
      const baseUrl = getApiUrl();
      const url = new URL("/api/admin/settings/match_preferences_visible", baseUrl);
      const res = await fetch(url.toString(), {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ value: visible ? "true" : "false" }),
        credentials: "include",
      });
      if (!res.ok) throw new Error(await res.text());
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/match-preferences/gate"] });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/settings"] });
    },
    onError: (e: Error) => Alert.alert("Errore", e.message),
  });

  const autoMatchMutation = useMutation({
    mutationFn: async (enabled: boolean) => {
      const baseUrl = getApiUrl();
      const url = new URL("/api/admin/settings/auto_matching", baseUrl);
      const res = await fetch(url.toString(), {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ value: enabled ? "true" : "false" }),
        credentials: "include",
      });
      if (!res.ok) throw new Error(await res.text());
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/settings/auto-matching"] });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/settings"] });
    },
    onError: (e: Error) => Alert.alert("Errore", e.message),
  });

  const triggerMatchingMutation = useMutation({
    mutationFn: async (data: { force?: boolean; country?: string }) => {
      const res = await apiRequest("POST", "/api/admin/matching/trigger", data);
      return res;
    },
    onSuccess: (data) => {
      setMatchingTriggerFeedback(`${t("admin.matchingTriggered")}: ${(data as any).count} ${t("admin.matchesCreated")}`);
      setTimeout(() => setMatchingTriggerFeedback(null), 5000);
    },
    onError: (e: Error) => Alert.alert("Errore", e.message),
  });

  return {
    matchingCountries,
    setMatchingCountries,
    matchingTriggerFeedback,
    setMatchingTriggerFeedback,
    autoMatchEnabled,
    autoMatchMutation,
    matchPrefVisibleEnabled,
    matchPrefVisibleMutation,
    triggerMatchingMutation,
  };
}

import { useQuery, useMutation } from "@tanstack/react-query";
import { Alert } from "react-native";
import { getApiUrl, queryClient } from "@/lib/query-client";

export function useToggleSettings(t: (k: string) => string, setProtectedToggle: (v: any) => void, setProtectedPassword: (v: string) => void) {
  const disableFeatureMutation = useMutation({
    mutationFn: async (key: string) => {
      const baseUrl = getApiUrl();
      const url = new URL("/api/admin/settings/disable-feature", baseUrl);
      const res = await fetch(url.toString(), {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ key }),
        credentials: "include",
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ message: t("admin.genericError2") }));
        throw new Error(err.message);
      }
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/settings/ads-enabled"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/syneco-branding"] });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/settings"] });
    },
    onError: (error: Error) => {
      Alert.alert("Errore", error.message);
    },
  });

  const protectedToggleMutation = useMutation({
    mutationFn: async ({ key, value, adminPassword }: { key: string; value: string; adminPassword?: string }) => {
      const baseUrl = getApiUrl();
      const url = new URL("/api/admin/settings/toggle-protected", baseUrl);
      const res = await fetch(url.toString(), {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ key, value, adminPassword }),
        credentials: "include",
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ message: t("admin.genericError2") }));
        throw new Error(err.message);
      }
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/settings/email-verification"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/syneco-branding"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/ads-enabled"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/donation"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/gps-required"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/marketplace-enabled"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/ghost-mode-enabled"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/phone-field-enabled"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/user-available-on-login"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/primal-user"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/floating-widget"] });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/all"] });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/settings"] });
      setProtectedToggle(null);
      setProtectedPassword("");
    },
    onError: (error: Error) => {
      Alert.alert("Errore", error.message);
    },
  });

  return {
    disableFeatureMutation,
    protectedToggleMutation,
  };
}

import React from "react";
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Switch,
  ActivityIndicator,
  Platform,
} from "react-native";
import { Ionicons, MaterialIcons } from "@expo/vector-icons";
import Colors from "@/constants/colors";

interface MotionStatus {
  enabled: boolean;
  totalFakeUsers: number;
  movingNow: number;
  restingNow: number;
  lastCycleAt: string | null;
  totalCycles: number;
  speedDistribution?: { city: number; highway: number; mountain: number };
  averageSpeedKph?: number;
}

interface BboxData {
  latMin: number;
  latMax: number;
  lngMin: number;
  lngMax: number;
  enabled: boolean;
}

interface StregattaActionsProps {
  chatbotEnabled: boolean;
  onToggleChatbot: (val: boolean) => void;
  allEnabled: boolean;
  onToggleAll: (val: boolean) => void;
  motionStatus: MotionStatus | null;
  onToggleMotion: (val: boolean) => void;
  isTogglingMotion: boolean;
  bboxData: BboxData | null;
  onToggleBbox: (val: boolean) => void;
  isTogglingBbox: boolean;
  onMassSeed: () => void;
  onWakeAll: () => void;
  onDistribute: () => void;
  onForceMatching: () => void;
  onResetMatches: () => void;
  onDeleteAll: () => void;
  onCreateNew: () => void;
  isMassSeedRunning: boolean;
  massSeedCreated: number;
  massSeedTotal: number;
  massSeedError: string | null;
  isWakingAll: boolean;
  isDistributing: boolean;
  isForcingMatching: boolean;
  isResettingMatches: boolean;
  totalCount: number;
  t: (key: string) => string;
}

export function StregattaActions({
  chatbotEnabled,
  onToggleChatbot,
  allEnabled,
  onToggleAll,
  motionStatus,
  onToggleMotion,
  isTogglingMotion,
  bboxData,
  onToggleBbox,
  isTogglingBbox,
  onMassSeed,
  onWakeAll,
  onDistribute,
  onForceMatching,
  onResetMatches,
  onDeleteAll,
  onCreateNew,
  isMassSeedRunning,
  massSeedCreated,
  massSeedTotal,
  massSeedError,
  isWakingAll,
  isDistributing,
  isForcingMatching,
  isResettingMatches,
  totalCount,
  t,
}: StregattaActionsProps) {
  const motionEnabled = motionStatus?.enabled ?? false;
  const bboxEnabled = bboxData?.enabled ?? true;

  const formatLastCycle = (iso: string | null): string => {
    if (!iso) return "Mai";
    const d = new Date(iso);
    return d.toLocaleTimeString("it-IT", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
  };

  return (
    <View style={styles.container}>
      <View style={styles.controlsCard}>
        <View style={styles.controlRow}>
          <View style={styles.controlInfo}>
            <Ionicons name="chatbubble-ellipses" size={24} color={Colors.accent} />
            <Text style={styles.controlLabel}>Stregatti Chatbot</Text>
          </View>
          <Switch
            value={chatbotEnabled}
            onValueChange={onToggleChatbot}
            trackColor={{ false: "#767577", true: Colors.accent }}
            thumbColor={Platform.OS === "ios" ? "#fff" : chatbotEnabled ? "#fff" : "#f4f3f4"}
          />
        </View>
        <Text style={styles.controlDesc}>
          Se attivo, gli stregatti risponderanno automaticamente usando l'IA.
        </Text>

        <View style={styles.controlDivider} />

        <View style={styles.controlRow}>
          <View style={styles.controlInfo}>
            <Ionicons name="people" size={24} color={Colors.accent} />
            <Text style={styles.controlLabel}>Visibilità Globale</Text>
          </View>
          <Switch
            value={allEnabled}
            onValueChange={onToggleAll}
            trackColor={{ false: "#767577", true: Colors.accent }}
            thumbColor={Platform.OS === "ios" ? "#fff" : allEnabled ? "#fff" : "#f4f3f4"}
          />
        </View>
        <Text style={styles.controlDesc}>
          Nascondi o mostra tutti gli stregatti contemporaneamente.
        </Text>

        <View style={styles.controlDivider} />

        <View style={styles.controlRow}>
          <View style={styles.controlInfo}>
            <Ionicons name="navigate" size={24} color={Colors.accent} />
            <Text style={styles.controlLabel}>Falli muovere</Text>
          </View>
          {isTogglingMotion ? (
            <ActivityIndicator size="small" color={Colors.accent} />
          ) : (
            <Switch
              value={motionEnabled}
              onValueChange={onToggleMotion}
              trackColor={{ false: "#767577", true: Colors.accent }}
              thumbColor={Platform.OS === "ios" ? "#fff" : motionEnabled ? "#fff" : "#f4f3f4"}
            />
          )}
        </View>
        <Text style={styles.controlDesc}>
          Simula spostamenti GPS realistici (giri brevi + trasferimenti lunghi, comitive).
        </Text>

        {motionStatus && (
          <View style={styles.motionStats}>
            <View style={styles.motionStatRow}>
              <Ionicons name="radio-button-on" size={12} color={motionEnabled ? "#4CAF50" : Colors.textSecondary} />
              <Text style={[styles.motionStatText, motionEnabled && { color: "#4CAF50" }]}>
                {motionStatus.movingNow} / {motionStatus.totalFakeUsers} in moto
              </Text>
            </View>
            {motionEnabled && motionStatus.averageSpeedKph != null && motionStatus.averageSpeedKph > 0 && (
              <View style={styles.motionStatRow}>
                <Ionicons name="speedometer-outline" size={12} color={Colors.textSecondary} />
                <Text style={styles.motionStatText}>
                  Velocità media: {motionStatus.averageSpeedKph} km/h
                </Text>
              </View>
            )}
            {motionEnabled && motionStatus.speedDistribution && motionStatus.movingNow > 0 && (
              <View style={styles.speedDistRow}>
                <View style={[styles.speedChip, { backgroundColor: "#4A90D9" }]}>
                  <Text style={styles.speedChipText}>🏙 {motionStatus.speedDistribution.city}</Text>
                </View>
                <View style={[styles.speedChip, { backgroundColor: "#E53935" }]}>
                  <Text style={styles.speedChipText}>🛣 {motionStatus.speedDistribution.highway}</Text>
                </View>
                <View style={[styles.speedChip, { backgroundColor: "#43A047" }]}>
                  <Text style={styles.speedChipText}>⛰ {motionStatus.speedDistribution.mountain}</Text>
                </View>
              </View>
            )}
            <View style={styles.motionStatRow}>
              <Ionicons name="time-outline" size={12} color={Colors.textSecondary} />
              <Text style={styles.motionStatText}>
                Ultimo ciclo: {formatLastCycle(motionStatus.lastCycleAt)}
              </Text>
            </View>
            <View style={styles.motionStatRow}>
              <Ionicons name="refresh-outline" size={12} color={Colors.textSecondary} />
              <Text style={styles.motionStatText}>
                Cicli totali: {motionStatus.totalCycles}
              </Text>
            </View>
          </View>
        )}

        <View style={styles.controlDivider} />

        <View style={styles.controlRow}>
          <View style={styles.controlInfo}>
            <Ionicons name="map" size={24} color={Colors.accent} />
            <Text style={styles.controlLabel}>Zona Europa</Text>
          </View>
          {isTogglingBbox ? (
            <ActivityIndicator size="small" color={Colors.accent} />
          ) : (
            <Switch
              value={bboxEnabled}
              onValueChange={onToggleBbox}
              trackColor={{ false: "#767577", true: Colors.accent }}
              thumbColor={Platform.OS === "ios" ? "#fff" : bboxEnabled ? "#fff" : "#f4f3f4"}
            />
          )}
        </View>
        <Text style={styles.controlDesc}>
          Confina i rider nel territorio europeo. Se escono dal confine, invertono la direzione.
        </Text>
        {bboxData && (
          <View style={styles.bboxInfo}>
            <Text style={styles.bboxInfoText}>
              Lat {bboxData.latMin}°–{bboxData.latMax}°  ·  Lng {bboxData.lngMin}°–{bboxData.lngMax}°
            </Text>
          </View>
        )}
      </View>

      <View style={styles.gridContainer}>
        <TouchableOpacity style={styles.actionBtn} onPress={onCreateNew}>
          <Ionicons name="person-add" size={22} color={Colors.accent} />
          <Text style={styles.actionBtnText}>Nuovo</Text>
        </TouchableOpacity>

        <TouchableOpacity style={styles.actionBtn} onPress={onWakeAll} disabled={isWakingAll}>
          {isWakingAll ? (
            <ActivityIndicator size="small" color={Colors.accent} />
          ) : (
            <>
              <MaterialIcons name="bolt" size={22} color={Colors.accent} />
              <Text style={styles.actionBtnText}>Sveglia</Text>
            </>
          )}
        </TouchableOpacity>

        <TouchableOpacity style={styles.actionBtn} onPress={onDistribute} disabled={isDistributing}>
          {isDistributing ? (
            <ActivityIndicator size="small" color={Colors.accent} />
          ) : (
            <>
              <MaterialIcons name="account-balance" size={22} color={Colors.accent} />
              <Text style={styles.actionBtnText}>Club</Text>
            </>
          )}
        </TouchableOpacity>

        <TouchableOpacity style={styles.actionBtn} onPress={onMassSeed} disabled={isMassSeedRunning}>
          {isMassSeedRunning ? (
            <View style={{ alignItems: "center" }}>
              <ActivityIndicator size="small" color={Colors.accent} />
              <Text style={{ fontSize: 9, color: Colors.accent }}>{massSeedCreated}</Text>
            </View>
          ) : (
            <>
              <MaterialIcons name="group-add" size={22} color={Colors.accent} />
              <Text style={styles.actionBtnText}>Massive</Text>
            </>
          )}
        </TouchableOpacity>
      </View>

      <View style={[styles.gridContainer, { marginTop: 12 }]}>
        <TouchableOpacity style={styles.actionBtn} onPress={onForceMatching} disabled={isForcingMatching}>
          {isForcingMatching ? (
            <ActivityIndicator size="small" color={Colors.accent} />
          ) : (
            <>
              <Ionicons name="heart" size={22} color={Colors.accent} />
              <Text style={styles.actionBtnText}>Match</Text>
            </>
          )}
        </TouchableOpacity>
        <TouchableOpacity style={styles.actionBtn} onPress={onResetMatches} disabled={isResettingMatches}>
          {isResettingMatches ? (
            <ActivityIndicator size="small" color={Colors.accent} />
          ) : (
            <>
              <Ionicons name="heart-dislike" size={22} color={Colors.accent} />
              <Text style={styles.actionBtnText}>Reset Match</Text>
            </>
          )}
        </TouchableOpacity>
      </View>

      {isMassSeedRunning && (
        <View style={styles.seedStatus}>
          <Text style={styles.seedStatusText}>
            Creazione in corso: {massSeedCreated} / {massSeedTotal}
          </Text>
        </View>
      )}

      {!!massSeedError && (
        <View style={styles.errorBanner}>
          <Text style={styles.errorText}>{massSeedError}</Text>
        </View>
      )}

      <TouchableOpacity style={styles.deleteAllBtn} onPress={onDeleteAll}>
        <Ionicons name="trash" size={20} color="#fff" />
        <Text style={styles.deleteAllBtnText}>Elimina tutti ({totalCount})</Text>
      </TouchableOpacity>
    </View>
  );
}

