  profileViews: number;
  chatRequests: number;
  chatMessages: number;
}

interface StregattaCardProps {
  user: FakeUser;
  onToggleAvailable: (id: string) => void;
  onToggleOnline: (id: string) => void;
  onDelete: (id: string, nickname: string) => void;
