  onToggleAvailable,
  onToggleOnline,
  onDelete,
  onOpenChat,
  isTogglingAvailable,
  isTogglingOnline,
  isDeleting,
}: StregattaCardProps) {
  const isAvailable = user.profile?.isAvailable ?? false;
  const isOnline = user.lastLoginAt ? (new Date().getTime() - new Date(user.lastLoginAt).getTime() < 5 * 60 * 1000) : false;

  return (
    <View style={styles.card}>
