export const RouteMapSection: React.FC<RouteMapSectionProps> = ({
  plannerMapHtml,
  webviewRef,
  onMapTap,
  isApproxRoute,
  calculating,
}) => {
  const colors = useColors();
  const s = styles(colors);

  return (
    <View style={s.section}>
      <Text style={s.sectionLabel}>Mappa percorso</Text>
