import React, { useEffect, useRef } from "react";
import { AppState, Platform } from "react-native";
import * as Location from "expo-location";
import { useAuth } from "@/lib/auth-context";
import { useLocationGate } from "@/lib/location-context";
import { queryClient, apiRequest } from "@/lib/query-client";
import { sendStartupBeacon } from "@/lib/startup-beacon";
import { isTrackingActive, registerLayoutWatcherCallbacks } from "@/lib/tracking-active";
import { initCrashLogger, resetCrashLogger, markClean } from "@/lib/crash-logger";
import {
  startBackgroundLocationTask,
  stopBackgroundLocationTask,
  isBackgroundLocationSupported,
} from "@/lib/background-location-task";
import Constants from "expo-constants";

const HEARTBEAT_INTERVAL_MS = 2 * 60 * 1000;

async function sendHeartbeat() {
  try {
    const appVersion = Constants.expoConfig?.version ?? "0.0.0";
    const platform = Platform.OS;
    await apiRequest("POST", "/api/auth/heartbeat", { appVersion, platform });
  } catch {
    // no-op: ignore heartbeat failures
  }
}

export function AppStateHandler() {
  const { user } = useAuth();
  const { hasBackgroundPermission } = useLocationGate();
  const appStateRef = useRef(AppState.currentState);
  const heartbeatTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const locationWatcherRef = useRef<Location.LocationSubscription | null>(null);
  const nativeWatcherStartingRef = useRef(false);

  useEffect(() => {
    if (hasBackgroundPermission && locationWatcherRef.current) {
      locationWatcherRef.current.remove();
      locationWatcherRef.current = null;
    }
  }, [hasBackgroundPermission]);

  useEffect(() => {
    if (!user) return;

    let cancelled = false;

    async function startNativeWatcher() {
      if (locationWatcherRef.current) return;
      if (hasBackgroundPermission) return;
      if (nativeWatcherStartingRef.current) {
        sendStartupBeacon("watch_position_concurrent_blocked");
        return;
      }
      nativeWatcherStartingRef.current = true;
      try {
        sendStartupBeacon("gps_check_start");
        const { status } = await Location.getForegroundPermissionsAsync();
        if (status !== "granted" || cancelled) return;
        if (isTrackingActive()) return;
        sendStartupBeacon("watch_position_start");
        let cbFired = false;
        locationWatcherRef.current = await Location.watchPositionAsync(
          {
            accuracy: Location.Accuracy.Balanced,
            timeInterval: 30000,
            distanceInterval: 20,
          },
          async (loc) => {
            if (!cbFired) {
              cbFired = true;
              sendStartupBeacon("watch_position_callback");
            }
            try {
              await apiRequest("PUT", "/api/users/location", {
                latitude: loc.coords.latitude,
                longitude: loc.coords.longitude,
              });
            } catch {
              // no-op: ignore location update failures in foreground watcher
            }
          }
        );
      } catch {
        // no-op: ignore GPS permission or watcher failures
      } finally {
        nativeWatcherStartingRef.current = false;
      }
    }

    function stopNativeWatcher() {
      if (locationWatcherRef.current) {
        locationWatcherRef.current.remove();
        locationWatcherRef.current = null;
      }
    }

    registerLayoutWatcherCallbacks(stopNativeWatcher, () => {
      if (!locationWatcherRef.current && !hasBackgroundPermission) {
        startNativeWatcher();
      }
    });

    queryClient.prefetchQuery({ queryKey: ["/api/settings/music-provider"], staleTime: 120_000 }).catch(() => {});
    queryClient.prefetchQuery({ queryKey: ["/api/lastfm/status"], staleTime: 60_000 }).catch(() => {});

    initCrashLogger(user.id).catch(() => {});

    sendHeartbeat();
    heartbeatTimerRef.current = setInterval(sendHeartbeat, HEARTBEAT_INTERVAL_MS);

    sendStartupBeacon("app_state_handler_mount");
    startNativeWatcher();

    const subscription = AppState.addEventListener("change", (nextAppState) => {
      const prev = appStateRef.current;

      if (nextAppState.match(/inactive|background/) && prev === "active") {
        apiRequest("POST", "/api/users/app-close").catch(() => {});
      }

      if (prev.match(/inactive|background/) && nextAppState === "active") {
        sendHeartbeat();
        queryClient.invalidateQueries({ queryKey: ["/api/users/profile"] });
        queryClient.invalidateQueries({ queryKey: ["/api/users/online-count"] });
        queryClient.invalidateQueries({ queryKey: ["/api/users/biker-available-count"] });
        queryClient.invalidateQueries({ queryKey: ["/api/users/zavorrine-available-count"] });
        queryClient.invalidateQueries({ queryKey: ["/api/users/biker-available-list"] });
        queryClient.invalidateQueries({ queryKey: ["/api/users/zavorrine-available-list"] });

        if (!locationWatcherRef.current && !hasBackgroundPermission) {
          startNativeWatcher();
        }
      }

      appStateRef.current = nextAppState;
    });

    return () => {
      cancelled = true;
      subscription.remove();
      if (heartbeatTimerRef.current) clearInterval(heartbeatTimerRef.current);
      stopNativeWatcher();
      markClean().catch(() => {});
      resetCrashLogger();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  useEffect(() => {
    if (!user || !hasBackgroundPermission) {
      stopBackgroundLocationTask().catch(() => {});
      return;
    }

    async function maybeStartBgTask() {
      try {
        const supported = await isBackgroundLocationSupported();
        if (!supported) return;

        let intervalSeconds = 30;
        let notificationText = "BikerLink: {motivo} — posizione attiva in background";
        try {
          const domain = process.env.EXPO_PUBLIC_DOMAIN || "biker-link.replit.app";
          const res = await fetch(`https://${domain}/api/admin/settings/bg-location`, {
            credentials: "include",
          });
          if (res.ok) {
            const settings = await res.json();
            if (settings.enabled === false) return;
            intervalSeconds = settings.intervalSeconds || 30;
            notificationText = settings.notificationText || notificationText;
          }
        } catch {
          // no-op: use default settings if fetch fails
        }

        await startBackgroundLocationTask(intervalSeconds, notificationText);
        sendStartupBeacon("bg_location_task_started");
      } catch {
        // no-op: ignore background task start failures
      }
    }

    maybeStartBgTask();
  }, [user, hasBackgroundPermission]);

  return null;
}

import React, { useEffect, useRef } from "react";
import { Linking, Platform } from "react-native";
import { useRouter, useRootNavigationState } from "expo-router";

let Notifications: typeof import("expo-notifications") | null = null;
try {
  Notifications = require("expo-notifications");
} catch {
  // no-op: expo-notifications is optional or missing
}

function navigateFromNotifData(data: { type?: string; unreadChat?: number } | undefined, router: ReturnType<typeof useRouter>) {
  if (data?.type === "match") {
    router.push("/(tabs)/match");
    return;
  }
  if (data?.type !== "background_badge") return;
  if ((data?.unreadChat ?? 0) > 0) {
    router.push("/(tabs)/chat");
  } else {
    router.push("/notifications");
  }
}

function parseDeepLink(url: string): { type?: string; unreadChat?: number } | null {
  try {
    if (!url.startsWith("bikerlink://")) return null;
    const parsed = new URL(url);
    const type = parsed.searchParams.get("type") ?? undefined;
    const unreadChatStr = parsed.searchParams.get("unreadChat");
    const unreadChat = unreadChatStr != null ? parseInt(unreadChatStr, 10) : undefined;
    if (!type) return null;
    return { type, unreadChat };
  } catch {
    return null;
  }
}

export function BackgroundNotificationHandler() {
  const router = useRouter();
  const navState = useRootNavigationState();
  const isNavReady = !!(navState?.key);
  const pendingNavRef = useRef<{ type?: string; unreadChat?: number } | null>(null);
  const isNavReadyRef = useRef(isNavReady);

  useEffect(() => {
    isNavReadyRef.current = isNavReady;
  }, [isNavReady]);

  useEffect(() => {
    if (!isNavReady) return;
    if (pendingNavRef.current) {
      const data = pendingNavRef.current;
      pendingNavRef.current = null;
      navigateFromNotifData(data, router);
    }
  }, [isNavReady, router]);

  useEffect(() => {
    function handleNavData(data: { type?: string; unreadChat?: number } | undefined) {
      if (!data) return;
      if (isNavReadyRef.current) {
        navigateFromNotifData(data, router);
      } else {
        pendingNavRef.current = data;
      }
    }

    if (Notifications) {
      (async () => {
        try {
          const lastResponse = await Notifications.getLastNotificationResponseAsync();
          if (lastResponse) {
            const data = lastResponse.notification.request.content.data as { type?: string; unreadChat?: number } | undefined;
            handleNavData(data);
          }
        } catch {
          // no-op: ignore failures to get last notification response
        }
      })();
    }

    Linking.getInitialURL().then((url) => {
      if (!url) return;
      const parsed = parseDeepLink(url);
      if (parsed) handleNavData(parsed);
    }).catch(() => {});

    let notifSub: { remove: () => void } | null = null;
    if (Notifications) {
      try {
        notifSub = Notifications.addNotificationResponseReceivedListener((response) => {
          const data = response.notification.request.content.data as { type?: string; unreadChat?: number } | undefined;
          handleNavData(data);
        });
      } catch {
        // no-op: ignore listener registration failures
      }
    }

    const linkingSub = Linking.addEventListener("url", ({ url }) => {
      const parsed = parseDeepLink(url);
      if (parsed) navigateFromNotifData(parsed, router);
    });

    return () => {
      notifSub?.remove();
      linkingSub.remove();
    };
  }, [router]);

  return null;
}

import React, { useEffect } from "react";
import { Platform } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useAuth } from "@/lib/auth-context";
import { apiRequest } from "@/lib/query-client";
import { PUSH_NOTIFICATIONS_ENABLED_KEY } from "@/lib/push-prefs";

let Notifications: typeof import("expo-notifications") | null = null;
try {
  Notifications = require("expo-notifications");
} catch {
  // no-op: expo-notifications is optional or missing
}

export function PushTokenRegistrar() {
  const { user } = useAuth();

  useEffect(() => {
    if (!user || !Notifications) return;

    (async () => {
      try {
        // Check server-side master toggle first (survives reinstalls),
        // then fall back to local AsyncStorage for instant offline response.
        let pushEnabled = true;
        try {
          const profileResp = await apiRequest("GET", "/api/users/profile");
          const profileData = await profileResp.json() as { pushNotificationsEnabled?: boolean };
          if (profileData?.pushNotificationsEnabled === false) {
            pushEnabled = false;
          }
        } catch {
          // If server unreachable, fall back to local pref
          const localPref = await AsyncStorage.getItem(PUSH_NOTIFICATIONS_ENABLED_KEY);
          if (localPref === "false") pushEnabled = false;
        }

        if (!pushEnabled) {
          try {
            await apiRequest("PUT", "/api/users/me/push-token", { token: null });
          } catch {
            // no-op: ignore failures when clearing token
          }
          return;
        }

        if (Platform.OS === "android") {
          await Notifications.setNotificationChannelAsync("matches", {
            name: "Match notifications",
            importance: Notifications.AndroidImportance.HIGH,
            sound: "default",
            vibrationPattern: [0, 250, 250, 250],
          });
        }

        const { status: existing } = await Notifications.getPermissionsAsync();
        let finalStatus = existing;
        if (existing !== "granted") {
          const { status } = await Notifications.requestPermissionsAsync();
          finalStatus = status;
        }
        if (finalStatus !== "granted") return;

        const tokenData = await Notifications.getExpoPushTokenAsync();
        const token = tokenData.data;
        if (!token) return;

        await apiRequest("PUT", "/api/users/me/push-token", { token });
      } catch {
        // no-op: ignore push token registration failures
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  return null;
}

