export default function UserProposals({ proposals, detailLoading, onClose }: Props) {
  const t = useT();
  const router = useRouter();

  if (proposals.length > 0) {
    return (
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>{t("home.rideProposals")}</Text>
        {proposals.map((p) => (
          <Pressable
            key={p.id}
