}

export function EditLocation({
  country,
  setCountry,
  showCountryPicker,
  setShowCountryPicker,
  region,
  setRegion,
  showRegionPicker,
  setShowRegionPicker,
}: EditLocationProps) {
  const t = useT();

  return (
    <View style={styles.fieldGroup}>
      <Text style={styles.groupTitle}>Paese</Text>
      <View style={styles.field}>
        <TouchableOpacity
          style={styles.selectInput}
          onPress={() => {
            setShowCountryPicker(!showCountryPicker);
            setShowRegionPicker(false);
          }}
          activeOpacity={0.7}
        >
          <Text
            style={[
              styles.selectText,
              !country && { color: Colors.textSecondary },
            ]}
          >
            {country
              ? `${EUROPEAN_COUNTRIES.find((c) => c.code === country)?.flag} ${
                  EUROPEAN_COUNTRIES.find((c) => c.code === country)?.name
                }`
              : "Seleziona paese"}
          </Text>
          <Feather
            name={showCountryPicker ? "chevron-up" : "chevron-down"}
            size={18}
            color={Colors.textSecondary}
          />
        </TouchableOpacity>
        {showCountryPicker && (
          <View style={styles.pickerList}>
            <ScrollView
              style={{ maxHeight: 200 }}
              nestedScrollEnabled
              showsVerticalScrollIndicator
            >
              {EUROPEAN_COUNTRIES.map((c) => (
                <TouchableOpacity
                  key={c.code}
                  style={[
                    styles.pickerItem,
                    country === c.code && styles.pickerItemSelected,
                  ]}
                  onPress={() => {
                    setCountry(c.code);
                    setRegion("");
                    setShowCountryPicker(false);
                  }}
                >
                  <Text
                    style={[
                      styles.pickerItemText,
                      country === c.code && styles.pickerItemTextSelected,
                    ]}
                  >
                    {c.flag} {c.name}
                  </Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
          </View>
        )}
      </View>

      {country && (
        <View style={styles.field}>
          <Text style={styles.fieldLabel}>{t("auth.region")}</Text>
          <TouchableOpacity
            style={styles.selectInput}
            onPress={() => {
              setShowRegionPicker(!showRegionPicker);
              setShowCountryPicker(false);
            }}
            activeOpacity={0.7}
          >
            <Text
              style={[
                styles.selectText,
                !region && { color: Colors.textSecondary },
              ]}
            >
              {region || t("profile.selectRegion")}
            </Text>
            <Feather
              name={showRegionPicker ? "chevron-up" : "chevron-down"}
              size={18}
              color={Colors.textSecondary}
            />
          </TouchableOpacity>
          {showRegionPicker && (
            <View style={styles.pickerList}>
              <ScrollView
                style={{ maxHeight: 200 }}
                nestedScrollEnabled
                showsVerticalScrollIndicator
              >
                {getRegionsForCountry(country).map((r) => (
                  <TouchableOpacity
                    key={r.name}
                    style={[
                      styles.pickerItem,
                      region === r.name && styles.pickerItemSelected,
                    ]}
                    onPress={() => {
                      setRegion(r.name);
                      setShowRegionPicker(false);
                    }}
                  >
                    <Text
                      style={[
                        styles.pickerItemText,
                        region === r.name && styles.pickerItemTextSelected,
                      ]}
                    >
                      {r.name}
                    </Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
            </View>
          )}
        </View>
      )}
    </View>
  );
}

