                    styles.motoCard,
                    selectedWishlistMotoId === m.id && styles.motoCardSelected,
                  ]}
                  onPress={() => setSelectedWishlistMotoId(m.id)}
                >
                  <MaterialCommunityIcons
                    name="motorbike"
                    size={24}
                    color={selectedWishlistMotoId === m.id ? Colors.accent : Colors.textSecondary}
