            <Text style={{ color: "#fff", fontFamily: "Inter_700Bold" }}>
              Conferma
            </Text>
          </Pressable>
        </View>
        <LeafletPickerMap
          initialLat={coord.latitude}
          initialLng={coord.longitude}
          initialZoom={12}
          selectedCoord={{ lat: coord.latitude, lng: coord.longitude }}
