              fontFamily: "Inter_500Medium",
              color: Colors.text,
              fontSize: 13,
              marginTop: 4,
            }}
          >
            {`${coord.latitude.toFixed(5)}, ${coord.longitude.toFixed(5)}`}
          </Text>
        </View>
      </View>
    </Modal>
  );
}

