import React, { useState, useMemo } from "react";
import {
  View,
  Text,
  Modal,
  TouchableOpacity,
  ActivityIndicator,
  Alert,
} from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { WebView } from "react-native-webview";
import * as FileSystem from "expo-file-system/legacy";
import * as Sharing from "expo-sharing";
import Colors from "@/constants/colors";
import { useT } from "@/lib/language-context";
import { getApiUrl, authFetchHeaders } from "@/lib/query-client";
import { formatDistance, formatSpeed } from "@/lib/units";
import { DistanceUnit, SpeedUnit } from "@/lib/units-context";
import { formatHMS, buildLeafletPostRideHtml } from "./tracking-utils";

interface RouteMapModalProps {
  visible: boolean;
  onClose: () => void;
  onCloseAll: () => void;
  points: Array<{ lat: number; lng: number }>;
  tileUrl: string;
  tileMaxZoom: number;
  totalKm: number;
  maxSpeed: number;
  totalMs: number;
  distanceUnit: DistanceUnit;
  speedUnit: SpeedUnit;
  insets: { top: number; bottom: number };
  loading?: boolean;
  routeId?: string | null;
}

export function RouteMapModal({
  visible, onClose, onCloseAll, points, tileUrl, tileMaxZoom,
  totalKm, maxSpeed, totalMs, distanceUnit, speedUnit, insets, loading, routeId,
}: RouteMapModalProps) {
  const t = useT();
  const [isExporting, setIsExporting] = useState(false);

  const handleExportGpx = async () => {
    if (!routeId || isExporting) return;
    setIsExporting(true);
    try {
      const url = new URL(`/api/routes/${routeId}/export.gpx`, getApiUrl()).href;
      const resp = await fetch(url, { headers: authFetchHeaders(), credentials: "include" });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const gpxText = await resp.text();
      const safeName = routeId.replace(/[^a-zA-Z0-9_\-]/g, "_").slice(0, 60);
      const fileUri = `${FileSystem.cacheDirectory}${safeName}.gpx`;
      await FileSystem.writeAsStringAsync(fileUri, gpxText, {
        encoding: FileSystem.EncodingType.UTF8,
      });
      const canShare = await Sharing.isAvailableAsync();
      if (canShare) {
        await Sharing.shareAsync(fileUri, {
          mimeType: "application/gpx+xml",
          dialogTitle: t("tracking.exportGpx"),
          UTI: "com.topografix.gpx",
        });
      } else {
        Alert.alert("GPX", fileUri);
      }
    } catch (err) {
      console.warn("[BikerLink] GPX export error:", err);
      Alert.alert(t("common.error"), t("tracking.exportGpxError"));
    } finally {
      setIsExporting(false);
    }
  };

  const html = useMemo(
    () => buildLeafletPostRideHtml(tileUrl, tileMaxZoom, Colors.accent, points),
    [tileUrl, tileMaxZoom, points]
  );

  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      <View style={{ flex: 1, backgroundColor: Colors.background }}>
        {/* Header */}
        <View style={{
          paddingTop: insets.top + 12,
          paddingBottom: 12,
          paddingHorizontal: 16,
          flexDirection: "row",
          alignItems: "center",
          backgroundColor: Colors.surface,
          borderBottomWidth: 1,
          borderBottomColor: Colors.border,
        }}>
          <Ionicons name="map-outline" size={20} color={Colors.accent} />
          <Text style={{
            flex: 1,
            marginLeft: 8,
            fontFamily: "Inter_600SemiBold",
            fontSize: 16,
            color: Colors.text,
          }}>{t("tracking.myRoute")}</Text>
          <TouchableOpacity onPress={onClose} hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}>
            <Ionicons name="close" size={24} color={Colors.textSecondary} />
          </TouchableOpacity>
        </View>

        {/* Map */}
        <View style={{ flex: 1 }}>
          {loading ? (
            <View style={{ flex: 1, alignItems: "center", justifyContent: "center", backgroundColor: "#1a1a1a" }}>
              <ActivityIndicator size="large" color={Colors.accent} />
              <Text style={{ fontFamily: "Inter_400Regular", fontSize: 14, color: Colors.textSecondary, marginTop: 12 }}>
                {t("tracking.loadingRoute")}
              </Text>
            </View>
          ) : points.length === 0 ? (
            <View style={{ flex: 1, alignItems: "center", justifyContent: "center", backgroundColor: "#1a1a1a" }}>
              <Ionicons name="map-outline" size={48} color={Colors.textSecondary} />
              <Text style={{ fontFamily: "Inter_600SemiBold", fontSize: 15, color: Colors.textSecondary, marginTop: 12 }}>
                {t("tracking.noRoute")}
              </Text>
              <Text style={{ fontFamily: "Inter_400Regular", fontSize: 13, color: Colors.textSecondary, marginTop: 4, textAlign: "center", paddingHorizontal: 32 }}>
                {t("tracking.noGpsPoints")}
              </Text>
            </View>
          ) : (
            <WebView
              source={{ html, baseUrl: "" }}
              style={{ flex: 1, backgroundColor: "#1a1a1a" }}
              javaScriptEnabled
              domStorageEnabled
              originWhitelist={["https://*", "http://*", "about:*"]}
              scrollEnabled={false}
              bounces={false}
              overScrollMode="never"
              cacheEnabled={false}
            />
          )}
        </View>

        {/* Stats bar + actions */}
        <View style={{
          backgroundColor: Colors.surface,
          borderTopWidth: 1,
          borderTopColor: Colors.border,
          paddingBottom: insets.bottom + 8,
        }}>
          <View style={{
            flexDirection: "row",
            justifyContent: "space-around",
            paddingVertical: 14,
            paddingHorizontal: 16,
          }}>
            {[
              { icon: "navigate-outline" as const, label: t("tracking.distance"), value: formatDistance(totalKm, distanceUnit, 2) },
              { icon: "flash" as const, label: t("tracking.maxSpeed"), value: formatSpeed(maxSpeed, speedUnit, 1) },
              { icon: "time-outline" as const, label: t("tracking.duration"), value: formatHMS(totalMs) },
            ].map((s) => (
              <View key={s.label} style={{ alignItems: "center", flex: 1 }}>
                <Ionicons name={s.icon} size={18} color={Colors.accent} />
                <Text style={{ fontFamily: "Inter_700Bold", fontSize: 14, color: Colors.text, marginTop: 2 }}>{s.value}</Text>
                <Text style={{ fontFamily: "Inter_400Regular", fontSize: 11, color: Colors.textSecondary }}>{s.label}</Text>
              </View>
            ))}
          </View>
          <View style={{ flexDirection: "row", gap: 10, paddingHorizontal: 16, paddingBottom: 4 }}>
            <TouchableOpacity
              onPress={onClose}
              activeOpacity={0.8}
              style={{
                flex: 1,
                alignItems: "center",
                justifyContent: "center",
                paddingVertical: 12,
                borderRadius: 12,
                backgroundColor: Colors.surfaceLight,
              }}
            >
              <Text style={{ fontFamily: "Inter_600SemiBold", fontSize: 14, color: Colors.textSecondary }}>
                {t("tracking.backToRide")}
              </Text>
            </TouchableOpacity>
            {!!routeId && (
              <TouchableOpacity
                onPress={handleExportGpx}
                activeOpacity={0.8}
                style={{
                  flex: 1,
                  alignItems: "center",
                  justifyContent: "center",
                  paddingVertical: 12,
                  borderRadius: 12,
                  backgroundColor: Colors.surfaceLight,
                  opacity: isExporting ? 0.5 : 1,
                }}
                disabled={isExporting}
              >
                {isExporting ? (
                  <ActivityIndicator size="small" color={Colors.accent} />
                ) : (
                  <>
                    <Ionicons name="download-outline" size={18} color={Colors.accent} style={{ marginBottom: 2 }} />
                    <Text style={{ fontFamily: "Inter_600SemiBold", fontSize: 14, color: Colors.accent }}>
                      GPX
                    </Text>
                  </>
                )}
              </TouchableOpacity>
            )}
          </View>
        </View>
      </View>
    </Modal>
  );
}

import React from "react";
import { View, Text } from "react-native";
import { MountAxisCalibration } from "@/components/MountCalibWizard";
import { useColors } from "@/hooks/useColors";

interface SensorOverlayPanelProps {
  currentG: number;
  currentLateralG: number;
  currentTiltDeg: number;
  maxAccelG: number;
  mountAxisCalib: MountAxisCalibration | null;
  sensorsEnabled: boolean;
  colors: any;
  styles: {
    sensorOverlayPanel: object;
    sensorOverlayItem: object;
    sensorOverlayValue: object;
    sensorOverlayLabel: object;
    sensorOverlaySep: object;
  };
  t: (key: string) => string;
}

export function SensorOverlayPanel({
  currentG,
  currentLateralG,
  currentTiltDeg,
  maxAccelG,
  mountAxisCalib,
  sensorsEnabled,
  colors,
  styles: s,
  t,
}: SensorOverlayPanelProps) {
  const isCalibrated = mountAxisCalib !== null;
  return (
    <View style={[s.sensorOverlayPanel, { flexDirection: "column" as const, alignItems: "stretch" as const }]}>
      <View style={{ flexDirection: "row" as const, alignItems: "center" as const, justifyContent: "space-around" as const }}>
        <View style={s.sensorOverlayItem}>
          <Text style={[s.sensorOverlayValue, currentG > 0.05 ? { color: colors.success } : currentG < -0.05 ? { color: colors.accentRed } : {}]}>
            {currentG >= 0 ? "+" : ""}{currentG.toFixed(2)}
          </Text>
          <Text style={s.sensorOverlayLabel}>{t("tracking.gLong")}</Text>
        </View>
        <View style={s.sensorOverlaySep} />
        <View style={s.sensorOverlayItem}>
          <Text style={s.sensorOverlayValue}>
            {currentLateralG.toFixed(2)}
          </Text>
          <Text style={s.sensorOverlayLabel}>{t("tracking.gLateral")}</Text>
        </View>
        <View style={s.sensorOverlaySep} />
        <View style={s.sensorOverlayItem}>
          <Text style={[s.sensorOverlayValue, { color: currentTiltDeg < -2 ? colors.accentRed : currentTiltDeg > 2 ? colors.success : colors.accent }]}>
            {currentTiltDeg.toFixed(1)}°
          </Text>
          <Text style={s.sensorOverlayLabel}>{t("tracking.tiltLive")}</Text>
          {/* Tilt arc gauge — mirrors the same ±2° dead-band as the text color */}
          <View style={{ width: 44, height: 4, backgroundColor: colors.border, borderRadius: 2, marginTop: 4, overflow: "hidden" as const }}>
            <View style={{
              width: Math.min(Math.abs(currentTiltDeg) / 60, 1) * 44,
              height: 4,
              backgroundColor: currentTiltDeg < -2 ? colors.accentRed : currentTiltDeg > 2 ? colors.success : colors.accent,
              borderRadius: 2,
            }} />
          </View>
        </View>
        <View style={s.sensorOverlaySep} />
        <View style={s.sensorOverlayItem}>
          <Text style={[s.sensorOverlayValue, { color: colors.accentRed }]}>
            {maxAccelG.toFixed(2)}
          </Text>
          <Text style={s.sensorOverlayLabel}>{t("tracking.gMaxAccel")}</Text>
        </View>
      </View>
      <View style={{ alignItems: "center" as const, marginTop: 7 }}>
        <View style={{
          flexDirection: "row" as const,
          alignItems: "center" as const,
          backgroundColor: isCalibrated ? colors.success + "22" : colors.warning + "22",
          borderRadius: 20,
          paddingHorizontal: 10,
          paddingVertical: 3,
          borderWidth: 1,
          borderColor: isCalibrated ? colors.success + "60" : colors.warning + "55",
        }}>
          <Text style={{
            fontSize: 10,
            fontFamily: "Inter_500Medium" as const,
            color: isCalibrated ? colors.success : colors.warning,
            letterSpacing: 0.2,
          }}>
            {isCalibrated
              ? `${t("tracking.mountCalib.calibratedBadge")} · ${mountAxisCalib.longAxis.toUpperCase()}/${mountAxisCalib.latAxis.toUpperCase()}`
              : t("tracking.mountCalib.chipDefault")}
          </Text>
        </View>
      </View>
    </View>
  );
}

