  handlePause,
  handleStop,
  gpsLost,
  isFermo,
  accuracyTier,
  currentSpeed,
  speedUnit,
  is0100Enabled,
  currentCoord,
  mapCoords,
  setMapModalVisible,
  profile,
  sensorsEnabled,
  isCalibrating,
  currentG,
  currentLateralG,
  currentTiltDeg,
  maxAccelG,
  mountAxisCalib,
  totalMs,
  netMs,
  maxSpeed,
  totalKm,
  distanceUnit,
  displayIdleMs,
  avgSpeedKmh,
  maxAltitude,
  maxDecelG,
  maxTiltDeg,
  handleRecalibrate,
  sprintPhase,
  discardSprintAttempt,
  sprint0to100Ms,
  isNewRecord,
  recordAnim,
  showSensorOverlay,
  setShowSensorOverlay,
