        >
          <View style={styles.speedMetaRow}>
            <View style={styles.fermoRow}>
              <View
                style={[
                  styles.fermoDot,
                  {
                    backgroundColor: isFermo
                      ? Colors.success
                      : Colors.textSecondary,
                  },
