            currentG={currentG}
            currentLateralG={currentLateralG}
            currentTiltDeg={currentTiltDeg}
            maxAccelG={maxAccelG}
            mountAxisCalib={mountAxisCalib}
            sensorsEnabled={sensorsEnabled}
            colors={Colors}
            styles={styles}
            t={t}
          />
