              {sensorsEnabled && !isCalibrating && (sprintGoFired || sprintPhase !== "waiting") && (
                <StatCard
                  icon="compass-outline"
                  color={Colors.accent}
                  value={`${maxTiltDeg.toFixed(1)}°`}
                  label={t("tracking.tiltMax")}
