  isAuthenticated: boolean;
};

export function useMapFilters({ user, isAuthenticated }: UseMapFiltersProps) {
  const [filterBiker, setFilterBiker] = useState(true);
  const [filterZavorrina, setFilterZavorrina] = useState(true);
  const [filterClubs, setFilterClubs] = useState(false);
  const [filterEvents, setFilterEvents] = useState(true);
  const [filtersLoaded, setFiltersLoaded] = useState(false);

  const serverFiltersAppliedRef = useRef(false);
  const lastAppliedUserIdRef = useRef<string | null>(null);

  useEffect(() => {
    const currentId = user?.id ?? null;
    if (lastAppliedUserIdRef.current !== currentId) {
      lastAppliedUserIdRef.current = currentId;
      serverFiltersAppliedRef.current = false;
    }
  }, [user?.id]);

  useEffect(() => {
    (async () => {
      try {
        const stored = await AsyncStorage.getItem("map_filters");
        if (stored) {
          const parsed = JSON.parse(stored);
          if (typeof parsed.biker === "boolean") setFilterBiker(parsed.biker);
          if (typeof parsed.zavorrina === "boolean") setFilterZavorrina(parsed.zavorrina);
          if (typeof parsed.clubs === "boolean") setFilterClubs(parsed.clubs);
          if (typeof parsed.events === "boolean") setFilterEvents(parsed.events);
        }
      } catch {
        // no-op: ignore storage read or JSON parsing failures
      }
      setFiltersLoaded(true);
    })();
  }, []);

  useEffect(() => {
    if (!filtersLoaded) return;
    if (serverFiltersAppliedRef.current) return;
    if (!user) return;
    if (!("mapFilters" in user)) return;
    serverFiltersAppliedRef.current = true;
    const serverFilters = (user as any).mapFilters as MapFiltersPrefs | null;
    if (serverFilters && typeof serverFilters === "object") {
      const nextBiker = typeof serverFilters.biker === "boolean" ? serverFilters.biker : filterBiker;
      const nextZav = typeof serverFilters.zavorrina === "boolean" ? serverFilters.zavorrina : filterZavorrina;
      const nextClubs = typeof serverFilters.clubs === "boolean" ? serverFilters.clubs : filterClubs;
      const nextEvents = typeof serverFilters.events === "boolean" ? serverFilters.events : filterEvents;
      setFilterBiker(nextBiker);
      setFilterZavorrina(nextZav);
      setFilterClubs(nextClubs);
      setFilterEvents(nextEvents);
      AsyncStorage.setItem(
        "map_filters",
        JSON.stringify({ biker: nextBiker, zavorrina: nextZav, clubs: nextClubs, events: nextEvents })
      ).catch(() => {
        // no-op: ignore storage write failures
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filtersLoaded, user]);

  const persistMapFilters = useCallback(
    (payload: { biker: boolean; zavorrina: boolean; clubs: boolean; events: boolean }) => {
      AsyncStorage.setItem("map_filters", JSON.stringify(payload)).catch(() => {
        // no-op: ignore storage write failures
      });
      serverFiltersAppliedRef.current = true;
      if (!isAuthenticated) return;
      apiRequest("PUT", "/api/users/me", { mapFilters: payload }).catch(() => {
        // no-op: ignore server update failures for map filters
      });
    },
    [isAuthenticated]
  );

  const toggleFilterBiker = useCallback(() => {
    setFilterBiker((prev) => {
      const next = !prev;
      persistMapFilters({ biker: next, zavorrina: filterZavorrina, clubs: filterClubs, events: filterEvents });
      return next;
    });
  }, [persistMapFilters, filterZavorrina, filterClubs, filterEvents]);

  const toggleFilterZavorrina = useCallback(() => {
    setFilterZavorrina((prev) => {
      const next = !prev;
      persistMapFilters({ biker: filterBiker, zavorrina: next, clubs: filterClubs, events: filterEvents });
      return next;
    });
  }, [persistMapFilters, filterBiker, filterClubs, filterEvents]);

  const toggleFilterClubs = useCallback(() => {
    setFilterClubs((prev) => {
      const next = !prev;
      persistMapFilters({ biker: filterBiker, zavorrina: filterZavorrina, clubs: next, events: filterEvents });
      return next;
    });
  }, [persistMapFilters, filterBiker, filterZavorrina, filterEvents]);

  const toggleFilterEvents = useCallback(() => {
    setFilterEvents((prev) => {
      const next = !prev;
      persistMapFilters({ biker: filterBiker, zavorrina: filterZavorrina, clubs: filterClubs, events: next });
      return next;
    });
  }, [persistMapFilters, filterBiker, filterZavorrina, filterClubs]);

  return {
    filterBiker,
    filterZavorrina,
    filterClubs,
    filterEvents,
    filtersLoaded,
    toggleFilterBiker,
    toggleFilterZavorrina,
    toggleFilterClubs,
    toggleFilterEvents,
  };
}

import { useState, useRef, useEffect, useCallback } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/lib/auth-context";
import { apiRequest } from "@/lib/query-client";

const SEEN_KEY = "bikerlink:seenMatchIds";
const INIT_KEY_PREFIX = "bikerlink:matchAlertInit:v1:";
const MAX_SEEN_IDS = 500;

const ALL_SOURCES = ["garage", "biker", "proposals"] as const;
type SourceKey = typeof ALL_SOURCES[number];

interface MatchItem {
  id: string | number;
  createdAt?: string | Date | null;
}

function namespacedId(source: string, id: string | number): string {
  return `${source}:${id}`;
}

function updateServerSeenTimestamp(): void {
  apiRequest("PUT", "/api/users/me/match-seen", {}).catch(() => {
    // no-op: ignore server update failures for match seen status
  });
}

function isAfterBaseline(item: MatchItem, baseline: Date): boolean {
  if (!item.createdAt) return false;
  const itemTime = new Date(item.createdAt as string).getTime();
  return itemTime > baseline.getTime();
}

export function useNewMatchAlert() {
  const { user } = useAuth();
  const userId = user?.id ?? null;
  const serverLastSeenAt = (user as any)?.lastSeenMatchAt as string | null | undefined;

  const [visible, setVisible] = useState(false);
  const [seenLoaded, setSeenLoaded] = useState(false);
  const seenRef = useRef<Set<string>>(new Set());
  const initializedSources = useRef<Set<string>>(new Set());
  const prevUserIdRef = useRef<string | null>(null);
  const serverSyncPendingRef = useRef(false);
  const serverSyncedRef = useRef(false);

  useEffect(() => {
    if (prevUserIdRef.current === userId) return;

    seenRef.current = new Set();
    initializedSources.current = new Set();
    setVisible(false);
    setSeenLoaded(false);
    serverSyncPendingRef.current = false;
    serverSyncedRef.current = false;
    prevUserIdRef.current = userId;

    if (!userId) return;

    const seenKey = SEEN_KEY;
    const initKey = `${INIT_KEY_PREFIX}${userId}`;

    Promise.all([
      AsyncStorage.getItem(seenKey),
      AsyncStorage.getItem(initKey),
    ])
      .then(([rawSeen, rawInit]) => {
        let loadedSeen: string[] = [];
        let loadedInit: string[] = [];

        if (rawSeen) {
          try {
            loadedSeen = JSON.parse(rawSeen) as string[];
          } catch {
            // no-op: ignore JSON parsing failures for seen match IDs
          }
        }
        if (rawInit) {
          try {
            loadedInit = JSON.parse(rawInit) as string[];
          } catch {
            // no-op: ignore JSON parsing failures for initialized sources
          }
        }

        if (loadedInit.length > 0 && loadedSeen.length === 0) {
          AsyncStorage.removeItem(initKey).catch(() => {
            // no-op: ignore storage removal failures
          });
          loadedInit = [];
        }

        seenRef.current = new Set(loadedSeen);
        loadedInit.forEach((s) => initializedSources.current.add(s));
        setSeenLoaded(true);
      })
      .catch(() => {
        setSeenLoaded(true);
      });
  }, [userId]);

  const persistSeen = useCallback(() => {
    AsyncStorage.setItem(SEEN_KEY, JSON.stringify([...seenRef.current])).catch(() => {
      // no-op: ignore storage write failures
    });
  }, []);

  const persistInit = useCallback(() => {
    if (!userId) return;
    AsyncStorage.setItem(
      `${INIT_KEY_PREFIX}${userId}`,
      JSON.stringify([...initializedSources.current])
    ).catch(() => {
      // no-op: ignore storage write failures
    });
  }, [userId]);

  const maybeSyncToServer = useCallback(() => {
    if (serverSyncedRef.current) return;
    serverSyncedRef.current = true;
    updateServerSeenTimestamp();
  }, []);

  const addSeen = useCallback((ids: string[]) => {
    ids.forEach((id) => seenRef.current.add(id));
    if (seenRef.current.size > MAX_SEEN_IDS) {
      const trimmed = [...seenRef.current];
      seenRef.current = new Set(trimmed.slice(trimmed.length - MAX_SEEN_IDS));
    }
    persistSeen();
  }, [persistSeen]);

  const markSourceInitialized = useCallback((sourceKey: string) => {
    initializedSources.current.add(sourceKey);
    persistInit();
    const allDone = ALL_SOURCES.every((s) => initializedSources.current.has(s));
    if (allDone) {
      maybeSyncToServer();
    }
  }, [persistInit, maybeSyncToServer]);

  const processSource = useCallback((sourceKey: string, items: MatchItem[] | undefined) => {
    if (!seenLoaded || !items) return;
    const ids = items.map((m) => namespacedId(sourceKey, m.id));

    if (!initializedSources.current.has(sourceKey)) {
      if (serverLastSeenAt) {
        const baseline = new Date(serverLastSeenAt);
        const newItems = items.filter((m) => isAfterBaseline(m, baseline));
        const oldItems = items.filter((m) => !isAfterBaseline(m, baseline));

        const oldIds = oldItems.map((m) => namespacedId(sourceKey, m.id));
        addSeen(oldIds);

        markSourceInitialized(sourceKey);

        const newIds = newItems
          .map((m) => namespacedId(sourceKey, m.id))
          .filter((id) => !seenRef.current.has(id));
        if (newIds.length > 0) {
          addSeen(newIds);
          setVisible(true);
          maybeSyncToServer();
        }
      } else {
        addSeen(ids);
        markSourceInitialized(sourceKey);
      }
      return;
    }

    const newIds = ids.filter((id) => !seenRef.current.has(id));
    if (newIds.length > 0) {
      addSeen(newIds);
      setVisible(true);
      maybeSyncToServer();
    }
  }, [seenLoaded, serverLastSeenAt, addSeen, markSourceInitialized, maybeSyncToServer]);

  const enabled = !!userId && seenLoaded;

  const { data: garageData } = useQuery<MatchItem[]>({
    queryKey: ["/api/proposals/garage-matches"],
    refetchInterval: 30000,
    enabled,
  });

  const { data: bikerData } = useQuery<MatchItem[]>({
    queryKey: ["/api/proposals/biker-matches"],
    refetchInterval: 30000,
    enabled,
  });

  const { data: proposalData } = useQuery<MatchItem[]>({
    queryKey: ["/api/proposals/matches"],
    refetchInterval: 30000,
    enabled,
  });

  useEffect(() => {
    processSource("garage", garageData);
  }, [garageData, processSource]);

  useEffect(() => {
    processSource("biker", bikerData);
  }, [bikerData, processSource]);

  useEffect(() => {
    processSource("proposals", proposalData);
  }, [proposalData, processSource]);

  const dismiss = useCallback(() => {
    setVisible(false);
    maybeSyncToServer();
  }, [maybeSyncToServer]);

  return { visible, dismiss };
}

import { useState, useEffect, useCallback, useRef } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";
import {
  loadIndex,
  downloadTilesForRoute,
  deleteTilesForRoute,
  calcBoundingBox,
  estimateDownload,
  tilesBaseDirPath,
  type OfflineRouteEntry,
  type DownloadEstimate,
} from "@/lib/offline-tiles";

export type OfflineStatus = "none" | "downloading" | "available" | "error";

export interface UseOfflineTilesResult {
  status: OfflineStatus;
  progress: number;
  total: number;
  estimate: DownloadEstimate | null;
  entry: OfflineRouteEntry | null;
  offlineTileBasePath: string | null;
  startDownload: () => Promise<void>;
  cancelDownload: () => void;
  deleteOffline: () => Promise<void>;
}

export function useOfflineTiles(
  routeId: string | undefined,
  routeTitle: string,
  points: Array<{ lat: number; lng: number }>
): UseOfflineTilesResult {
  const [status, setStatus] = useState<OfflineStatus>("none");
  const [progress, setProgress] = useState(0);
  const [total, setTotal] = useState(0);
  const [entry, setEntry] = useState<OfflineRouteEntry | null>(null);
  const [estimate, setEstimate] = useState<DownloadEstimate | null>(null);
  const cancelRef = useRef({ cancelled: false });

  useEffect(() => {
    if (!routeId) return;
    (async () => {
      const index = await loadIndex();
      const e = index[routeId] ?? null;
      setEntry(e);
      setStatus(e ? "available" : "none");
    })();
  }, [routeId]);

  useEffect(() => {
    if (!points.length || status !== "none") return;
    const bbox = calcBoundingBox(points);
    setEstimate(estimateDownload(bbox));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [points.length, status]);

  const startDownload = useCallback(async () => {
    if (!routeId || !points.length) return;
    cancelRef.current = { cancelled: false };
    setStatus("downloading");
    setProgress(0);
    try {
      await downloadTilesForRoute(
        routeId,
        routeTitle,
        points,
        (dl, tot) => {
          setProgress(dl);
          setTotal(tot);
        },
        cancelRef.current
      );
      if (!cancelRef.current.cancelled) {
        const index = await loadIndex();
        const e = index[routeId] ?? null;
        setEntry(e);
        setStatus("available");
        setEstimate(null);
      } else {
        setStatus("none");
        setProgress(0);
        setTotal(0);
      }
    } catch {
      setStatus("error");
    }
  }, [routeId, routeTitle, points]);

  const cancelDownload = useCallback(() => {
    cancelRef.current.cancelled = true;
    setStatus("none");
    setProgress(0);
    setTotal(0);
  }, []);

  const deleteOffline = useCallback(async () => {
    if (!routeId) return;
    await deleteTilesForRoute(routeId);
    setEntry(null);
    setStatus("none");
    const bbox = calcBoundingBox(points);
    setEstimate(estimateDownload(bbox));
  }, [routeId, points]);

  const offlineTileBasePath =
    status === "available" ? tilesBaseDirPath() : null;

  return {
    status,
    progress,
    total,
    estimate,
    entry,
    offlineTileBasePath,
    startDownload,
    cancelDownload,
    deleteOffline,
  };
}

import { useState, useEffect, useCallback, useRef } from "react";
import { Alert } from "react-native";
import * as Location from "expo-location";
import { useMutation, useQuery } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/query-client";
import { useAuth } from "@/lib/auth-context";
import { useT } from "@/lib/language-context";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { MapTarget } from "@/components/ready/FakeZoneCoordPanel";

export function useReadyState() {
  const { user } = useAuth();
  const t = useT();

  const [infoModalVisible, setInfoModalVisible] = useState(false);
  const [showSosModal, setShowSosModal] = useState(false);
  const [sosReason, setSosReason] = useState("");
  const [sosRadiusKm, setSosRadiusKm] = useState(10);
  const [customRadius, setCustomRadius] = useState("");
  const [location, setLocation] = useState<{ latitude: number; longitude: number } | null>(null);
  const [toastMsg, setToastMsg] = useState<string | null>(null);
  const toastTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [privacyExpanded, setPrivacyExpanded] = useState(false);
  const [gpsPrecisionExpanded, setGpsPrecisionExpanded] = useState(false);

  const [positionFuzz, setPositionFuzz] = useState(false);
  const [positionFuzzKm, setPositionFuzzKm] = useState(1);
  const [fakeHomeEnabled, setFakeHomeEnabled] = useState(false);
  const [homeLatitude, setHomeLatitude] = useState<number | null>(null);
  const [homeLongitude, setHomeLongitude] = useState<number | null>(null);
  const [fakeHomeLatitude, setFakeHomeLatitude] = useState<number | null>(null);
  const [fakeHomeLongitude, setFakeHomeLongitude] = useState<number | null>(null);
  const [fakeHomeRadius, setFakeHomeRadius] = useState(2);
  const [fakeWorkEnabled, setFakeWorkEnabled] = useState(false);
  const [workLatitude, setWorkLatitude] = useState<number | null>(null);
  const [workLongitude, setWorkLongitude] = useState<number | null>(null);
  const [fakeWorkLatitude, setFakeWorkLatitude] = useState<number | null>(null);
  const [fakeWorkLongitude, setFakeWorkLongitude] = useState<number | null>(null);
  const [fakeWorkRadius, setFakeWorkRadius] = useState(2);
  const [fakeWhateverEnabled, setFakeWhateverEnabled] = useState(false);
  const [whateverLatitude, setWhateverLatitude] = useState<number | null>(null);
  const [whateverLongitude, setWhateverLongitude] = useState<number | null>(null);
  const [fakeWhateverLatitude, setFakeWhateverLatitude] = useState<number | null>(null);
  const [fakeWhateverLongitude, setFakeWhateverLongitude] = useState<number | null>(null);
  const [fakeWhateverRadius, setFakeWhateverRadius] = useState(2);
  const [gpsPrecision, setGpsPrecision] = useState("balanced");

  const [mapPickerVisible, setMapPickerVisible] = useState(false);
  const [mapPickerTarget, setMapPickerTarget] = useState<MapTarget>("homeReal");
  const [mapPickerCoord, setMapPickerCoord] = useState({ latitude: 41.9, longitude: 12.5 });

  useEffect(() => {
    return () => {
      if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    async function initLocation() {
      try {
        const { status } = await Location.requestForegroundPermissionsAsync();
        if (status === "granted" && !cancelled) {
          const loc = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced });
          if (!cancelled) setLocation({ latitude: loc.coords.latitude, longitude: loc.coords.longitude });
        }
      } catch (err) {
        console.warn("[ready] Location init fallita:", err);
      }
    }
    initLocation();
    return () => { cancelled = true; };
  }, []);

  const { data, isLoading } = useQuery({
    queryKey: ["/api/users/profile"],
  });

  const { data: meData } = useQuery({
    queryKey: ["/api/users/me"],
    enabled: !!user,
  });

  const { data: ghostSettingData } = useQuery<{ enabled: boolean }>({
    queryKey: ["/api/settings/ghost-mode-enabled"],
  });
  const ghostModeFeatureEnabled = ghostSettingData?.enabled === true;

  const isAvailable = (data as any)?.isAvailable || false;
  const isGhostMode = (data as any)?.ghostMode || false;

  const meProfile = (meData as any)?.profile;
  const hideFromMap = meProfile?.hideFromMap ?? false;
  const offlineRandomize = meProfile?.offlinePositionRandomize !== false;

  useEffect(() => {
    const p = (meData as any)?.profile;
    if (!p) return;
    setPositionFuzz(p.positionFuzz ?? false);
    setPositionFuzzKm(p.positionFuzzKm ?? 1);
    setFakeHomeEnabled(p.fakeHomeEnabled ?? false);
    setHomeLatitude(p.homeLatitude ?? null);
    setHomeLongitude(p.homeLongitude ?? null);
    setFakeHomeLatitude(p.fakeHomeLatitude ?? null);
    setFakeHomeLongitude(p.fakeHomeLongitude ?? null);
    setFakeHomeRadius(p.fakeHomeRadius ?? 2);
    setFakeWorkEnabled(p.fakeWorkEnabled ?? false);
    setWorkLatitude(p.workLatitude ?? null);
    setWorkLongitude(p.workLongitude ?? null);
    setFakeWorkLatitude(p.fakeWorkLatitude ?? null);
    setFakeWorkLongitude(p.fakeWorkLongitude ?? null);
    setFakeWorkRadius(p.fakeWorkRadius ?? 2);
    setFakeWhateverEnabled(p.fakeWhateverEnabled ?? false);
    setWhateverLatitude(p.whateverLatitude ?? null);
    setWhateverLongitude(p.whateverLongitude ?? null);
    setFakeWhateverLatitude(p.fakeWhateverLatitude ?? null);
    setFakeWhateverLongitude(p.fakeWhateverLongitude ?? null);
    setFakeWhateverRadius(p.fakeWhateverRadius ?? 2);
    setGpsPrecision(p.gpsPrecision ?? "balanced");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [(meData as any)?.profile]);

  const invalidateOnlineQueries = () => {
    queryClient.invalidateQueries({ queryKey: ["/api/users/profile"] });
    queryClient.invalidateQueries({ queryKey: ["/api/users/biker-available-count"] });
    queryClient.invalidateQueries({ queryKey: ["/api/users/zavorrine-available-count"] });
    queryClient.invalidateQueries({ queryKey: ["/api/users/online-count"] });
    queryClient.invalidateQueries({ queryKey: ["/api/users/biker-available-list"] });
    queryClient.invalidateQueries({ queryKey: ["/api/users/zavorrine-available-list"] });
    queryClient.invalidateQueries({ queryKey: ["/api/users/online-list"] });
    queryClient.invalidateQueries({ queryKey: ["/api/users/nearby"] });
  };

  const showToast = (msg: string) => {
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    setToastMsg(msg);
    toastTimerRef.current = setTimeout(() => setToastMsg(null), 2500);
  };

  const toggleMutation = useMutation({
    mutationFn: async (newVal: boolean) => {
      await apiRequest("PUT", "/api/users/profile/dynamic", {
        isAvailable: newVal,
      });
      return newVal;
    },
    onSuccess: (_data: boolean, variables: boolean) => {
      invalidateOnlineQueries();
      showToast(variables ? t("ready.nowAvailable") : t("ready.noLongerAvailable"));
    },
    onError: () => {
      Alert.alert(t("common.error"), t("ready.toggleError"));
    },
  });

  const ghostMutation = useMutation({
    mutationFn: async (enabled: boolean) => {
      await apiRequest("PUT", "/api/users/me/ghost-mode", { enabled });
      return enabled;
    },
    onSuccess: (enabled: boolean) => {
      invalidateOnlineQueries();
      queryClient.invalidateQueries({ queryKey: ["/api/users/me"] });
      AsyncStorage.setItem("user_ghost_mode", enabled ? "true" : "false").catch(() => {
        // no-op: ignore storage write failures
      });
    },
    onError: () => {
      Alert.alert(t("common.error"), t("ride.ghostModeNotAvailable"));
    },
  });

  const repushLocation = useCallback(async () => {
    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== "granted") return;
      const loc =
        (await Location.getLastKnownPositionAsync()) ??
        (await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced }));
      if (loc) {
        await apiRequest("PUT", "/api/users/location", {
          latitude: loc.coords.latitude,
          longitude: loc.coords.longitude,
        });
      }
    } catch {
      // no-op: ignore location update failures in repushLocation
    }
  }, []);

  const privacyMutation = useMutation({
    mutationFn: async (payload: Record<string, unknown>) => {
      await apiRequest("PUT", "/api/users/me/privacy", payload);
    },
    onSuccess: (_: unknown, variables: Record<string, unknown>) => {
      invalidateOnlineQueries();
      queryClient.invalidateQueries({ queryKey: ["/api/users/me"] });
      if (
        variables.positionFuzz === true ||
        variables.fakeHomeEnabled === true ||
        variables.fakeWorkEnabled === true ||
        variables.fakeWhateverEnabled === true
      ) {
        repushLocation();
      }
    },
    onError: (_err: Error, variables: Record<string, unknown>) => {
      if (variables.positionFuzz !== undefined) setPositionFuzz(!variables.positionFuzz);
      if (variables.fakeHomeEnabled !== undefined) setFakeHomeEnabled(!variables.fakeHomeEnabled);
      if (variables.fakeWorkEnabled !== undefined) setFakeWorkEnabled(!variables.fakeWorkEnabled);
      if (variables.fakeWhateverEnabled !== undefined) setFakeWhateverEnabled(!variables.fakeWhateverEnabled);
      Alert.alert(t("common.error"), t("ready.toggleError"));
    },
  });

  const handleToggle = () => {
    toggleMutation.mutate(!isAvailable);
  };

  const openMapPicker = (target: MapTarget, lat?: number | null, lng?: number | null) => {
    setMapPickerTarget(target);
    setMapPickerCoord({ latitude: lat ?? 41.9, longitude: lng ?? 12.5 });
    setMapPickerVisible(true);
  };

  const confirmMapPicker = () => {
    const lat = mapPickerCoord.latitude;
    const lng = mapPickerCoord.longitude;
    const updates: Record<string, number> = {};
    if (mapPickerTarget === "homeReal") { setHomeLatitude(lat); setHomeLongitude(lng); updates.homeLatitude = lat; updates.homeLongitude = lng; }
    else if (mapPickerTarget === "homeFake") { setFakeHomeLatitude(lat); setFakeHomeLongitude(lng); updates.fakeHomeLatitude = lat; updates.fakeHomeLongitude = lng; }
    else if (mapPickerTarget === "workReal") { setWorkLatitude(lat); setWorkLongitude(lng); updates.workLatitude = lat; updates.workLongitude = lng; }
    else if (mapPickerTarget === "workFake") { setFakeWorkLatitude(lat); setFakeWorkLongitude(lng); updates.fakeWorkLatitude = lat; updates.fakeWorkLongitude = lng; }
    else if (mapPickerTarget === "whateverReal") { setWhateverLatitude(lat); setWhateverLongitude(lng); updates.whateverLatitude = lat; updates.whateverLongitude = lng; }
    else if (mapPickerTarget === "whateverFake") { setFakeWhateverLatitude(lat); setFakeWhateverLongitude(lng); updates.fakeWhateverLatitude = lat; updates.fakeWhateverLongitude = lng; }
    privacyMutation.mutate(updates);
    setMapPickerVisible(false);
  };

  const pickFromGPS = async (target: MapTarget) => {
    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== "granted") {
        Alert.alert("Permesso negato", "Concedi l'accesso alla posizione nelle impostazioni.");
        return;
      }
      const loc = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced });
      const lat = loc.coords.latitude;
      const lng = loc.coords.longitude;
      const updates: Record<string, number> = {};
      if (target === "homeReal") { setHomeLatitude(lat); setHomeLongitude(lng); updates.homeLatitude = lat; updates.homeLongitude = lng; }
      else if (target === "homeFake") { setFakeHomeLatitude(lat); setFakeHomeLongitude(lng); updates.fakeHomeLatitude = lat; updates.fakeHomeLongitude = lng; }
      else if (target === "workReal") { setWorkLatitude(lat); setWorkLongitude(lng); updates.workLatitude = lat; updates.workLongitude = lng; }
      else if (target === "workFake") { setFakeWorkLatitude(lat); setFakeWorkLongitude(lng); updates.fakeWorkLatitude = lat; updates.fakeWorkLongitude = lng; }
      else if (target === "whateverReal") { setWhateverLatitude(lat); setWhateverLongitude(lng); updates.whateverLatitude = lat; updates.whateverLongitude = lng; }
      else if (target === "whateverFake") { setFakeWhateverLatitude(lat); setFakeWhateverLongitude(lng); updates.fakeWhateverLatitude = lat; updates.fakeWhateverLongitude = lng; }
      privacyMutation.mutate(updates);
    } catch {
      Alert.alert("Errore GPS", "Impossibile ottenere la posizione.");
    }
  };

  return {
    t,
    user,
    infoModalVisible, setInfoModalVisible,
    showSosModal, setShowSosModal,
    sosReason, setSosReason,
    sosRadiusKm, setSosRadiusKm,
    customRadius, setCustomRadius,
    location,
    toastMsg,
    privacyExpanded, setPrivacyExpanded,
    gpsPrecisionExpanded, setGpsPrecisionExpanded,
    positionFuzz, setPositionFuzz,
    positionFuzzKm, setPositionFuzzKm,
    fakeHomeEnabled, setFakeHomeEnabled,
    homeLatitude, homeLongitude,
    fakeHomeLatitude, fakeHomeLongitude,
    fakeHomeRadius, setFakeHomeRadius,
    fakeWorkEnabled, setFakeWorkEnabled,
    workLatitude, workLongitude,
    fakeWorkLatitude, fakeWorkLongitude,
    fakeWorkRadius, setFakeWorkRadius,
    fakeWhateverEnabled, setFakeWhateverEnabled,
    whateverLatitude, whateverLongitude,
    fakeWhateverLatitude, fakeWhateverLongitude,
    fakeWhateverRadius, setFakeWhateverRadius,
    gpsPrecision, setGpsPrecision,
    mapPickerVisible, setMapPickerVisible,
    mapPickerCoord, setMapPickerCoord,
    ghostModeFeatureEnabled,
    isAvailable,
    isGhostMode,
    hideFromMap,
    offlineRandomize,
    isLoading,
    toggleMutation,
    ghostMutation,
    privacyMutation,
    handleToggle,
    openMapPicker,
    confirmMapPicker,
    pickFromGPS,
  };
}
